INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('7abb834a-305d-43b5-b0fe-283261d83cf0'::uuid, 'card_description', 'The Temple of Victory at Himera, probably dedicated to Athena, dates to between 480 and 470 BC. It was burnt and destroyed, most likely in 409 BC, when the Carthaginians captured the city.', 'A temple built around 480 BC to celebrate victory over a Carthaginian invasion. The battle was fought the same year as Thermopylae and Salamis.', 'teaser-card-s029-rollback:7abb834a-305d-43b5-b0fe-283261d83cf0:card_description', 'rollback of teaser-card-s029: card_description ''A temple built around 480 BC to celebrate victory over a Carthaginian invasion. The battle was fought the same year as Thermopylae and Salamis.'' restored on Temple of Victory, Himera', '2a80d24adb06f552cb646a8ec45cbd118fba6bedbd0d7198777a27dff330e2c0|21fc7bcd89f6fca80ce126989cea13f7aec70295b7bb4123b05c473725aba88a|21fc7bcd89f6fca80ce126989cea13f7aec70295b7bb4123b05c473725aba88a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Temple of Victory at Himera, probably dedicated to Athena, dates to between 480 and 470 BC. It was burnt and destroyed, most likely in 409 BC, when the Carthaginians captured the city."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Temple of Victory is at Himera [S1]; it was probably dedicated to Athena [S3]; it dates to between 480 and 470 BC [S2]; it was burnt and destroyed [S3]; the destruction was most likely in 409 BC [S3]; the Carthaginians captured the city (Himera) at that time [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Temple of Victory at Himera is a temple (a Greek temple of the ancient city of Himera, in Sicily, Italy) [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Victory_(Himera)]; The temple is probably dedicated to Athena [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Victory_(Himera)]; The temple dates to between 480 and 470 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Victory_(Himera)]; The temple was burnt [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Victory_(Himera)]; The temple was destroyed [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Victory_(Himera)]; The burning and destruction most likely happened in 409 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Victory_(Himera)]; The Carthaginians captured the city of Himera in 409 BC [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Victory_(Himera)]"}]'::jsonb),
    ('7bfb0158-bf33-40c2-aff0-3af9efcd5193'::uuid, 'card_description', 'Bone flutes from the Geissenklösterle cave, the oldest musical instruments ever found, are from the Caves and Ice Age Art in the Swabian Jura, like the 41,000 to 39,000-year-old Lion-man.', 'The 41,000 to 39,000-year-old Lion-man and the 42,000 to 41,000-year-old Venus of Hohle Fels are the oldest confirmed sculptures in the world.', 'teaser-card-s029-rollback:7bfb0158-bf33-40c2-aff0-3af9efcd5193:card_description', 'rollback of teaser-card-s029: card_description ''The 41,000 to 39,000-year-old Lion-man and the 42,000 to 41,000-year-old Venus of Hohle Fels are the oldest confirmed sculptures in the world.'' restored on Caves and Ice Age Art in the Swabian Jura', 'a598817a27f04b9dfe2c4fffd8a85a03385512cfa51508f7b656519d317e94c1|3a6926ee90e2e70f9e9b235a4540f7cf3a3fc1da65b551613983ce142b42a0de|3a6926ee90e2e70f9e9b235a4540f7cf3a3fc1da65b551613983ce142b42a0de', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Bone flutes from the Geissenklösterle cave, the oldest musical instruments ever found, are from the Caves and Ice Age Art in the Swabian Jura, like the 41,000 to 39,000-year-old Lion-man."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "bone flutes come from the Geissenklösterle cave [S4]; the flutes are the oldest musical instruments ever found [S4, S2]; Geissenklösterle belongs to the Caves and Ice Age Art in the Swabian Jura [S1, S4]; the Lion-man is 41,000 to 39,000 years old [S5]; the Lion-man is among the finds of these caves [S2, S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Caves and Ice Age Art in the Swabian Jura are a group of caves (six caves) in southern Germany [SUPPORTED: https://en.wikipedia.org/wiki/Caves_and_Ice_Age_Art_in_the_Swabian_Jura]; Bone flutes come from the Geissenklösterle cave, one of the Swabian Jura caves [SUPPORTED: https://en.wikipedia.org/wiki/Caves_and_Ice_Age_Art_in_the_Swabian_Jura]; These bone flutes are the oldest musical instruments ever found [SUPPORTED: https://en.wikipedia.org/wiki/Caves_and_Ice_Age_Art_in_the_Swabian_Jura]; The Lion-man is 41,000 to 39,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Caves_and_Ice_Age_Art_in_the_Swabian_Jura]; The Lion-man and the flutes belong to the Swabian Jura caves [SUPPORTED: https://en.wikipedia.org/wiki/Caves_and_Ice_Age_Art_in_the_Swabian_Jura]"}]'::jsonb),
    ('7c097275-ba5b-44f8-852b-77f450b7b813'::uuid, 'card_description', 'The Welsh Way, a British Iron Age trade route across the Cotswold Hills, links the highest navigable point on the Thames at Lechlade to the lowest crossing of the Severn at Gloucester.', 'An Iron Age trade route crossing the Cotswolds, linking the Thames to the Severn. The Romans later upgraded it to connect their major roads Akeman Street and the Fosse Way.', 'teaser-card-s029-rollback:7c097275-ba5b-44f8-852b-77f450b7b813:card_description', 'rollback of teaser-card-s029: card_description ''An Iron Age trade route crossing the Cotswolds, linking the Thames to the Severn. The Romans later upgraded it to connect their major roads Akeman Street and the Fosse Way.'' restored on Welsh Way', 'e150b8d73eed74276ab6a938dcda770bf6751b9f07bd06743af4704be18c9c73|7e940a225170a926382765c7e45b504a518e87ef379b32fe0e92c431bcbd1b13|7e940a225170a926382765c7e45b504a518e87ef379b32fe0e92c431bcbd1b13', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Welsh Way, a British Iron Age trade route across the Cotswold Hills, links the highest navigable point on the Thames at Lechlade to the lowest crossing of the Severn at Gloucester."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Welsh Way is a British Iron Age trade route [S1]; it crosses the Cotswold Hills [S1]; it links the highest navigable point on the Thames, at Lechlade [S3]; it links to the lowest crossing point of the Severn, at Gloucester [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Welsh Way is a trade route and track-way (a road/trackway) in England [SUPPORTED: https://en.wikipedia.org/wiki/Welsh_Way]; The Welsh Way is British Iron Age in date [SUPPORTED: https://en.wikipedia.org/wiki/Welsh_Way]; The Welsh Way, like the Salt Way and White Way, is an ancient trade route going back to the Iron Age [SUPPORTED: https://www.broad.community/blog/2021/3/25/ted-homer-the-ancient-ways]; The Welsh Way is a trade route (it carried trade between South Wales and the Oxford area) [SUPPORTED: https://en.wikipedia.org/wiki/Welsh_Way]; The Welsh Way crosses the Cotswold Hills [SUPPORTED: https://en.wikipedia.org/wiki/Welsh_Way]; The Welsh Way links the highest navigable point on the Thames at Lechlade [SUPPORTED: https://en.wikipedia.org/wiki/Welsh_Way]; The Welsh Way links to the lowest crossing of the Severn at Gloucester [SUPPORTED: https://en.wikipedia.org/wiki/Welsh_Way]"}]'::jsonb),
    ('7c3cb1c4-0431-4ebb-96e0-a3238de40ca0'::uuid, 'card_description', 'Early antiquarians thought the Romans built Wincobank, an oval earthwork covering about 1 ha. Archaeologists now think the Celtic Brigantes tribe constructed it.', 'An oval Iron Age hillfort covering 1 hectare on a sandstone hill above the River Don. A rubble-core rampart and ditch surround the entire fort.', 'teaser-card-s029-rollback:7c3cb1c4-0431-4ebb-96e0-a3238de40ca0:card_description', 'rollback of teaser-card-s029: card_description ''An oval Iron Age hillfort covering 1 hectare on a sandstone hill above the River Don. A rubble-core rampart and ditch surround the entire fort.'' restored on Wincobank - Hill Fort', '0e256655ecab405338ef8c091e5ce5e94303cd6710ae5776884a3159113eb0d5|61e1bbbf5026236bce71b8ddaf93ed0ea96e8ad14bd00cf6d4c09885f4759fe8|61e1bbbf5026236bce71b8ddaf93ed0ea96e8ad14bd00cf6d4c09885f4759fe8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Early antiquarians thought the Romans built Wincobank, an oval earthwork covering about 1 ha. Archaeologists now think the Celtic Brigantes tribe constructed it."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "early antiquarians thought the Romans built the fort [S6]; it is an oval earthwork [S3]; it covers about 1 ha [S3]; archaeologists now think it was built by the Brigantes [S7]; the Brigantes are a Celtic tribe [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Wincobank is a hill fort (earthwork) in Sheffield, England [SUPPORTED: https://en.wikipedia.org/wiki/Wincobank_(hill_fort)]; Early antiquarians thought the Romans built it [SUPPORTED: https://en.wikipedia.org/wiki/Wincobank_(hill_fort)]; It is an oval earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Wincobank_(hill_fort)]; The earthwork covers about 1 ha [SUPPORTED: https://en.wikipedia.org/wiki/Wincobank_(hill_fort)]; Wincobank is in England (Sheffield) [SUPPORTED: https://en.wikipedia.org/wiki/Wincobank_(hill_fort)]; Archaeologists now think the Celtic Brigantes tribe constructed it [SUPPORTED: https://en.wikipedia.org/wiki/Wincobank_(hill_fort)]"}]'::jsonb),
    ('7c762fd9-2ec5-4d25-a67b-f391837257af'::uuid, 'card_description', 'Near Oddendale stands a stone circle, part of a complex of cairns, circles and standing stones that includes the Shap Stone Avenue. A second circle and ring cairn was excavated nearby.', 'A hamlet with a stone circle that underwent a major excavation in 1997. It revealed oak post circles from 2872 BC were replaced by stone circles centuries later.', 'teaser-card-s029-rollback:7c762fd9-2ec5-4d25-a67b-f391837257af:card_description', 'rollback of teaser-card-s029: card_description ''A hamlet with a stone circle that underwent a major excavation in 1997. It revealed oak post circles from 2872 BC were replaced by stone circles centuries later.'' restored on Oddendale', '21ee9aa29a4cc5c27e7f0c2b83b898f75d485f12b16c59a8799697e4b4edcc8b|d03dac3f539f53ed4227c5bf752c9596b61103be49400d9bee3ac62053067fcc|d03dac3f539f53ed4227c5bf752c9596b61103be49400d9bee3ac62053067fcc', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Oddendale stands a stone circle, part of a complex of cairns, circles and standing stones that includes the Shap Stone Avenue. A second circle and ring cairn was excavated nearby."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "a stone circle stands near Oddendale [S1]; it is part of a complex of cairns, circles and standing stones [S1]; the complex includes the Shap Stone Avenue [S1]; a second circle and ring cairn was excavated nearby [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-041 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "A stone circle stands near Oddendale (Oddendale, Cumbria, England) [SUPPORTED: https://en.wikipedia.org/wiki/Oddendale]; The Oddendale monument is a stone circle (a concentric stone circle, 580m south west of Oddendale Hall Farm) [SUPPORTED, no proving quote: https://historicengland.org.uk/listing/the-list/list-entry/1011513]; Oddendale is a hamlet in Cumbria, England, near Shap [SUPPORTED: https://en.wikipedia.org/wiki/Oddendale]; The stone circle is part of a complex of cairns, circles and standing stones [SUPPORTED: https://en.wikipedia.org/wiki/Oddendale]; The complex includes the Shap Stone Avenue [SUPPORTED: https://coasttocoast.uk/lake-district/haweswater-orton/oddendale-circle/]; A second circle and ring cairn was excavated nearby [SUPPORTED: https://en.wikipedia.org/wiki/Oddendale]"}]'::jsonb),
    ('7cecf4ab-47ef-4c15-90bb-e6ba491732e2'::uuid, 'card_description', 'Near the top of Mockham Down in Devon, at 310 m, an Iron Age hill fort takes the form of a multi-ditch and rampart enclosure. A smaller enclosure lies 2 km to the west on the next hill.', '1st millennium BC. An Iron Age hillfort at 310 m on Mockham Down in Devon — a multi-ditch rampart enclosure with a companion fort 2 km to the west, commanding the high ground above Devon''s valleys.', 'teaser-card-s029-rollback:7cecf4ab-47ef-4c15-90bb-e6ba491732e2:card_description', 'rollback of teaser-card-s029: card_description "1st millennium BC. An Iron Age hillfort at 310 m on Mockham Down in Devon — a multi-ditch rampart enclosure with a companion fort 2 km to the west, commanding the high ground above Devon''s valleys." restored on Mockham Down', 'd78dc25d78bf83b54b95ac1d472693d73dcd25075bfa133e211d754f7abeb079|c43f54fe21d77287c7f288406121f52502939f5f4158b2d11c679bfd0fc75d70|c43f54fe21d77287c7f288406121f52502939f5f4158b2d11c679bfd0fc75d70', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near the top of Mockham Down in Devon, at 310 m, an Iron Age hill fort takes the form of a multi-ditch and rampart enclosure. A smaller enclosure lies 2 km to the west on the next hill."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is in Devon [S1]; it is an Iron Age hill fort [S1]; it lies near the top of the hill known as Mockham Down [S2]; the elevation is 310 m [S2]; it takes the form of a multi-ditch and rampart enclosure [S2]; a smaller enclosure lies 2 km to the west [S3]; the smaller enclosure is on the next hill [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Mockham Down, in Devon, is the site of a hill fort (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]; The hill fort is of the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]; The fort lies near the top of the hill known as Mockham Down [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]; The fort lies at an elevation of 310 m [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]; The fort takes the form of a multi-ditch and rampart enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]; A smaller enclosure exists besides the hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]; The smaller enclosure lies 2 km from the fort [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]; The smaller enclosure lies to the west of the fort [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]; The smaller enclosure lies on the next hill [SUPPORTED: https://en.wikipedia.org/wiki/Mockham_Down]"}]'::jsonb),
    ('7cf71e81-b840-41ac-86e1-9d39eda3a2fb'::uuid, 'card_description', 'In Manchester''s Castlefield stood Mamucium, a Roman fort begun around AD 79 on a sandstone bluff over a crossing of the River Medlock, levelled as the city grew in the Industrial Revolution.', 'A Roman fort founded around 79 AD at the junction of two major roads. The civilian town that grew around it eventually became the modern city of Manchester.', 'teaser-card-s029-rollback:7cf71e81-b840-41ac-86e1-9d39eda3a2fb:card_description', 'rollback of teaser-card-s029: card_description ''A Roman fort founded around 79 AD at the junction of two major roads. The civilian town that grew around it eventually became the modern city of Manchester.'' restored on Mamucium', 'a00cc882069624a46405ba00f9ebc499c2d968a6cd993e79c2f1b05a2cb559f8|97a4f4988ab7d4083226f49399ae29341201566dbcaa4cccdf990832ec1d7e07|97a4f4988ab7d4083226f49399ae29341201566dbcaa4cccdf990832ec1d7e07', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Manchester''s Castlefield stood Mamucium, a Roman fort begun around AD 79 on a sandstone bluff over a crossing of the River Medlock, levelled as the city grew in the Industrial Revolution."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Mamucium stood in the Castlefield area of Manchester [S1]; it was a Roman fort [S1]; construction began around AD 79 [S3]; it was built on a sandstone bluff [S2]; the bluff overlooked a crossing of the River Medlock [S2]; it was levelled as Manchester grew in the Industrial Revolution [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Mamucium was a Roman fort (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]; The fort was in Castlefield, Manchester [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]; The fort no longer stands (\"stood\"): it is a former fort [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]; The fort was begun around AD 79 [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]; The fort was built on a sandstone bluff [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]; The bluff overlooked a crossing of the River Medlock [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]; The fort was levelled [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]; The fort was levelled as the city (Manchester) grew [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]; The levelling happened in the Industrial Revolution [SUPPORTED: https://en.wikipedia.org/wiki/Mamucium]"}]'::jsonb),
    ('7d45e357-77ff-40f6-a4b4-7e16e015996a'::uuid, 'card_description', 'Atop the Iverian Mountain, Anacopia Fortress has walls built of largely tightly assembled and carefully hewn limestone blocks and, at its centre, a Roman-styled tower four storeys high.', 'At the end of the seventh century, walls were constructed around the site of the citadel, with support from the Byzantines who had become alarmed by the Islamic Caliphate''s expansionism.', 'teaser-card-s029-rollback:7d45e357-77ff-40f6-a4b4-7e16e015996a:card_description', 'rollback of teaser-card-s029: card_description "At the end of the seventh century, walls were constructed around the site of the citadel, with support from the Byzantines who had become alarmed by the Islamic Caliphate''s expansionism." restored on Anacopia Fortress', 'eb2ace56a43fa8353d28effb6a1559974a98e1e923e64c5aae5c7209456c1e66|cbd1a624b183d4d3204bd41706cd87e36fba0540c08da55d83a7b753c285cb51|cbd1a624b183d4d3204bd41706cd87e36fba0540c08da55d83a7b753c285cb51', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atop the Iverian Mountain, Anacopia Fortress has walls built of largely tightly assembled and carefully hewn limestone blocks and, at its centre, a Roman-styled tower four storeys high."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the fortress lies at the top of the Iverian Mountain [S2]; it has walls [S5, S6]; the walls are built of limestone blocks [S6]; the blocks are largely tightly assembled and carefully hewn [S6]; there is a tower at the centre of the fortress [S7]; the tower is Roman-styled [S7]; the tower is four storeys high [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Anacopia (Anakopia) Fortress is a fortress, an ancient military citadel (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Anakopia_Fortress]; The fortress stands atop the Iverian Mountain [SUPPORTED: https://en.wikipedia.org/wiki/Anakopia_Fortress]; The fortress walls are built of limestone blocks [SUPPORTED: https://en.wikipedia.org/wiki/Anakopia_Fortress]; The limestone blocks of the walls are largely tightly assembled [SUPPORTED: https://en.wikipedia.org/wiki/Anakopia_Fortress]; The limestone blocks of the walls are carefully hewn [SUPPORTED: https://en.wikipedia.org/wiki/Anakopia_Fortress]; There is a tower at the centre of the fortress [SUPPORTED: https://en.wikipedia.org/wiki/Anakopia_Fortress]; The central tower is Roman-styled [SUPPORTED: https://en.wikipedia.org/wiki/Anakopia_Fortress]; The central tower is four storeys high [SUPPORTED: https://en.wikipedia.org/wiki/Anakopia_Fortress]"}]'::jsonb),
    ('7e45bd64-0e85-4b03-9cb7-2b865ef867dd'::uuid, 'card_description', 'Atop Quarley Hill, 172 metres above sea level, sits an oval Iron Age hill fort. Four large Bronze Age ditches radiate from it, believed to be part of a Bronze Age farming settlement.', 'Oval in plan with a counter-scarp and entrances at northeast and southwest, this Hampshire hillfort sits on a commanding hill. It overlies an earlier palisade enclosure.', 'teaser-card-s029-rollback:7e45bd64-0e85-4b03-9cb7-2b865ef867dd:card_description', 'rollback of teaser-card-s029: card_description ''Oval in plan with a counter-scarp and entrances at northeast and southwest, this Hampshire hillfort sits on a commanding hill. It overlies an earlier palisade enclosure.'' restored on Quarley Hill', '3ee812d3ea3419c26e64983712c0df549f04bf4d1f3c6ca1ea51d30aad71f1fe|078f39b193d54fb7f98e26c0d23a881e8733343d0c19cf3693993ccd0aff6931|078f39b193d54fb7f98e26c0d23a881e8733343d0c19cf3693993ccd0aff6931', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-014", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Atop Quarley Hill, 172 metres above sea level, sits an oval Iron Age hill fort. Four large Bronze Age ditches radiate from it, believed to be part of a Bronze Age farming settlement."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-014 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the hill''s summit is 172 metres above sea level [S7]; an Iron Age hill fort sits on Quarley Hill [S1]; the fort is oval [S2]; four large Bronze Age ditches radiate from the hill fort [S4]; the ditches are believed to be part of a Bronze Age farming settlement [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Quarley Hill is the site of a hill fort (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Quarley_Hill]; The hill fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Quarley_Hill]; The fort sits atop (on the hilltop of) Quarley Hill [SUPPORTED: https://www.geograph.org.uk/photo/2145125]; The hill fort is oval [SUPPORTED: https://en.wikipedia.org/wiki/Quarley_Hill]; Quarley Hill is 172 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Quarley_Hill]; Four large ditches radiate from the hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Quarley_Hill]; The ditches date to the Bronze Age [SUPPORTED: https://www.geograph.org.uk/photo/2145125]; The ditches are believed to be part of a Bronze Age farming settlement [SUPPORTED: https://en.wikipedia.org/wiki/Quarley_Hill]"}]'::jsonb),
    ('7ee712a7-ac2d-448e-953e-1292d104facc'::uuid, 'card_description', 'The entrance of the granite dolmen Cova d''en Daina is oriented to the southeast, letting winter solstice sunlight reach the interior. Excavation unearthed human bones and flint arrowheads.', 'The entrance to the tomb is oriented to the southeast, which allows sunlight to reach the interior on the winter solstice.', 'teaser-card-s029-rollback:7ee712a7-ac2d-448e-953e-1292d104facc:card_description', 'rollback of teaser-card-s029: card_description ''The entrance to the tomb is oriented to the southeast, which allows sunlight to reach the interior on the winter solstice.'' restored on Cova d''en Daina', '0004bd2b3d853a413038dce3c165b7d557ad2d105c2a0dc9966c59ba6c49dd72|8342343da2b9e9c8e7954f9ecb631051c5dff70d829805a5b96245ba4aeab25a|8342343da2b9e9c8e7954f9ecb631051c5dff70d829805a5b96245ba4aeab25a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The entrance of the granite dolmen Cova d''en Daina is oriented to the southeast, letting winter solstice sunlight reach the interior. Excavation unearthed human bones and flint arrowheads."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cova d''en Daina is a dolmen [S1]; it is built of granite [S2]; the entrance is oriented to the southeast [S7]; winter solstice sunlight reaches the interior through the entrance [S7]; excavation unearthed human bones [S4]; excavation unearthed flint arrowheads [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-042 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cova d''en Daina is a dolmen (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Cova_d%27en_Daina]; The dolmen is built of granite [SUPPORTED: https://en.wikipedia.org/wiki/Cova_d%27en_Daina]; The entrance of the dolmen is oriented to the southeast [SUPPORTED: https://en.wikipedia.org/wiki/Cova_d%27en_Daina]; The southeast orientation lets sunlight reach the interior on the winter solstice [SUPPORTED: https://en.wikipedia.org/wiki/Cova_d%27en_Daina]; The dolmen was excavated [SUPPORTED: https://en.wikipedia.org/wiki/Cova_d%27en_Daina]; Excavation unearthed human bones [SUPPORTED: https://en.wikipedia.org/wiki/Cova_d%27en_Daina]; Excavation unearthed flint arrowheads [SUPPORTED: https://en.wikipedia.org/wiki/Cova_d%27en_Daina]"}]'::jsonb),
    ('7ee94c43-3a26-44db-8dee-bd7829b5a171'::uuid, 'card_description', 'Vestiges of low walls ring the slope of the Castro of Castelo Velho, a fortified Chalcolithic settlement in the Alentejo that by the late Bronze Age was a centre of intense metallurgy.', 'Chalcolithic settlement from the 4th millennium BC that became a Bronze Age metallurgical centre, then a Moorish stronghold. Multiple civilisations found this hilltop worth defending.', 'teaser-card-s029-rollback:7ee94c43-3a26-44db-8dee-bd7829b5a171:card_description', 'rollback of teaser-card-s029: card_description ''Chalcolithic settlement from the 4th millennium BC that became a Bronze Age metallurgical centre, then a Moorish stronghold. Multiple civilisations found this hilltop worth defending.'' restored on Castro of Castelo Velho', '3fa5bcad39bccd161c03b32d53f6f37c0da4f8895f00fac317a55b58c8e383c6|db621330c1ea4aac5d25edfbe1e513869db3f14dc1db72c6b62163192e412ccf|db621330c1ea4aac5d25edfbe1e513869db3f14dc1db72c6b62163192e412ccf', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Vestiges of low walls ring the slope of the Castro of Castelo Velho, a fortified Chalcolithic settlement in the Alentejo that by the late Bronze Age was a centre of intense metallurgy."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is the Castro of Castelo Velho [S1]; vestiges of low walls are visible on the slope around its perimeter [S6]; it is a fortified settlement [S5]; it is a Chalcolithic settlement [S1, S2]; it is in the Alentejo [S1]; by the late Bronze Age the location had become a centre of intense metallurgy [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Castro of Castelo Velho is a Chalcolithic settlement (a castro, i.e. a settlement site, not a tomb or temple) in Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Castelo_Velho]; The site lies in the Alentejo (Portugal) [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Castelo_Velho]; The settlement is fortified [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Castelo_Velho]; Visible vestiges of low walls ring the slope around the site''s perimeter [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Castelo_Velho]; The first settlement at the site dates to the Chalcolithic [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Castelo_Velho]; By the late Bronze Age the site had become a centre of intense metallurgy [SUPPORTED: https://en.wikipedia.org/wiki/Castro_of_Castelo_Velho]"}]'::jsonb),
    ('7fc0b9aa-387f-4403-992c-b9648b23b870'::uuid, 'card_description', 'On the Boa Vista savanna, Sítio Arqueológico da Pedra Pintada rises 35 metres above a cave. Its rock art comes in two styles, the abstract Parime and the realist Surumu.', 'Around 2000 BC, abstract images and what may be a calendar were carved into rock here — the most intriguing petroglyphs in the region. Whether it charts seasons or stars remains unanswered.', 'teaser-card-s029-rollback:7fc0b9aa-387f-4403-992c-b9648b23b870:card_description', 'rollback of teaser-card-s029: card_description ''Around 2000 BC, abstract images and what may be a calendar were carved into rock here — the most intriguing petroglyphs in the region. Whether it charts seasons or stars remains unanswered.'' restored on Sítio Arqueológico da Pedra Pintada', '5819997a213b8deb5f2026951806416cee58c1cbf222b819310ba707c4ec2aec|3b88ea123fabda196f89338099465284f50a493c565d84612491640b9b056867|3b88ea123fabda196f89338099465284f50a493c565d84612491640b9b056867', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the Boa Vista savanna, Sítio Arqueológico da Pedra Pintada rises 35 metres above a cave. Its rock art comes in two styles, the abstract Parime and the realist Surumu."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Sítio Arqueológico da Pedra Pintada [S1]; it is located on the Boa Vista savanna [S3]; it is 35 metres high [S2]; there is a cave underneath it [S2]; it has rock art [S4]; the rock art falls into two styles [S6]; one style is the abstract Parime [S6]; the other style is the realist Surumu [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sítio Arqueológico da Pedra Pintada is a large rock formation and rock-art site (not a tomb, fort or temple) [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]; The site is in Brazil (state of Roraima) [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]; The site lies on the Boa Vista savanna [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]; The rock is 35 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]; There is a cave underneath the rock (text: rises above a cave) [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]; The site has rock art [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]; The rock art comes in two styles [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]; One of the two styles is the abstract Parime style [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]; The other style is the realist Surumu style [SUPPORTED: https://en.wikipedia.org/wiki/Pedra_Pintada,_Roraima]"}]'::jsonb),
    ('80ea9e97-d2ed-46f6-b1db-293dfd277039'::uuid, 'card_description', 'On a high hill in Grimsbury Wood, Grimsbury Castle''s ramparts seem stretched to take in a spring reportedly never known to run dry. Saxons thought Woden alias Grim had built the earthworks.', 'A multi-enclosure hillfort in Grimsbury Wood with a spring at its heart that has reportedly never run dry. The southern rampart was extended specifically to enclose that water source.', 'teaser-card-s029-rollback:80ea9e97-d2ed-46f6-b1db-293dfd277039:card_description', 'rollback of teaser-card-s029: card_description ''A multi-enclosure hillfort in Grimsbury Wood with a spring at its heart that has reportedly never run dry. The southern rampart was extended specifically to enclose that water source.'' restored on Grimsbury Castle', '576ab05422c30e4714376a1e9f72e799203d014e93db6414ba13877553f86fa2|7c41070215703155b04c71c93e4b18bf97989af423eb31c40e89d36184bde962|7c41070215703155b04c71c93e4b18bf97989af423eb31c40e89d36184bde962', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a high hill in Grimsbury Wood, Grimsbury Castle''s ramparts seem stretched to take in a spring reportedly never known to run dry. Saxons thought Woden alias Grim had built the earthworks."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Grimsbury Castle [S1]; it stands on a high hill [S1]; it is in Grimsbury Wood [S2]; its ramparts seem (appear) to have been extended to enclose a spring [S4, S5]; the spring is reportedly never known to run dry [S3]; Saxons thought Woden alias Grim had built the earthworks [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Grimsbury Castle is a hillfort (an earthwork fortification), not a castle building, tomb or temple [SUPPORTED: http://berkshirehistory.com/castles/grimsbury_castle.html]; Grimsbury Castle is in England (county of Berkshire) [SUPPORTED: https://en.wikipedia.org/wiki/Grimsbury_Castle]; The site stands on a high hill [SUPPORTED: https://en.wikipedia.org/wiki/Grimsbury_Castle]; The site is within Grimsbury Wood [SUPPORTED: https://en.wikipedia.org/wiki/Grimsbury_Castle]; The site has ramparts [SUPPORTED: http://berkshirehistory.com/castles/grimsbury_castle.html]; The entrenchment appears to have been extended (stretched) to enclose a spring [SUPPORTED: https://en.wikipedia.org/wiki/Grimsbury_Castle]; The site has a natural spring reportedly never known to run dry [SUPPORTED: https://en.wikipedia.org/wiki/Grimsbury_Castle]; Saxon settlers thought the earthworks had been built by Woden alias Grim [SUPPORTED: http://berkshirehistory.com/castles/grimsbury_castle.html]"}]'::jsonb),
    ('8153d20b-c794-4c70-9269-7f20884d5149'::uuid, 'card_description', 'On a promontory on the southern side of Norton Down, approximately 145 metres above sea level, sits Woodbury, an Iron Age hillfort in the parish of Stoke Fleming, near Dartmouth in Devon.', 'Iron Age promontory hillfort at ~145 m in Stoke Fleming parish. On Norton Down''s southern side, Woodbury commanded coastal approaches to Dartmouth - one of the southwest''s finest natural harbours.', 'teaser-card-s029-rollback:8153d20b-c794-4c70-9269-7f20884d5149:card_description', 'rollback of teaser-card-s029: card_description "Iron Age promontory hillfort at ~145 m in Stoke Fleming parish. On Norton Down''s southern side, Woodbury commanded coastal approaches to Dartmouth - one of the southwest''s finest natural harbours." restored on Woodbury, Stoke Fleming', '1a4e7a714dc9781d23cab8b787198de990f27032ff269faf2b0b2498c8672816|576bbe7833fa65f008e7c0fe5f05e94c9bf15d15051e93fabfdddf2159861041|576bbe7833fa65f008e7c0fe5f05e94c9bf15d15051e93fabfdddf2159861041', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a promontory on the southern side of Norton Down, approximately 145 metres above sea level, sits Woodbury, an Iron Age hillfort in the parish of Stoke Fleming, near Dartmouth in Devon."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Woodbury [S1]; it sits on a promontory [S2]; the promontory is on the southern side of Norton Down [S2]; it is approximately 145 metres above sea level [S2]; it is an Iron Age hillfort [S1]; it is in the parish of Stoke Fleming [S1]; it is near (close to) Dartmouth in Devon [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Woodbury is an Iron Age hillfort (not a tomb, temple or settlement) [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury,_Stoke_Fleming]; Woodbury lies in the parish of Stoke Fleming [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Woodbury,_Stoke_Fleming]; It is near Dartmouth [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury,_Stoke_Fleming]; It is in Devon (England) [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury,_Stoke_Fleming]; It sits on a promontory [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury,_Stoke_Fleming]; The promontory is on the southern side of Norton Down [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury,_Stoke_Fleming]; It stands approximately 145 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Woodbury,_Stoke_Fleming]"}]'::jsonb),
    ('81666db8-d2a8-4557-8986-376a02bf40b2'::uuid, 'card_description', 'At sea level near Cartagena, the Cave of Los Aviones yielded perforated, painted seashell beads thought to be jewelry crafted by Neanderthals, their pigments dated to 115,000 years old.', 'The Cave of Los Aviones is a paleontology site dating back to the Middle Paleolithic era.', 'teaser-card-s029-rollback:81666db8-d2a8-4557-8986-376a02bf40b2:card_description', 'rollback of teaser-card-s029: card_description ''The Cave of Los Aviones is a paleontology site dating back to the Middle Paleolithic era.'' restored on Cave of Los Aviones', 'e85a6039fd9d68f61cb4032772c74ee23afb22d36a84096408c6cb440242fd88|a3435fa74423cf2bfe4f9c7fbe825352f258a68289b12cec00063e9112c8d0f5|a3435fa74423cf2bfe4f9c7fbe825352f258a68289b12cec00063e9112c8d0f5', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At sea level near Cartagena, the Cave of Los Aviones yielded perforated, painted seashell beads thought to be jewelry crafted by Neanderthals, their pigments dated to 115,000 years old."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is the Cave of Los Aviones [S1]; it is at sea level near Cartagena [S1]; it yielded perforated, painted seashell beads [S2]; the beads are thought to be jewelry [S2]; the beads are thought to have been crafted by Neanderthals [S2]; the pigments on the shells were dated to 115,000 years old [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-043 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Cave of Los Aviones (Cueva de los Aviones) is a cave (a Middle Paleolithic cave site), not a tomb, fort or temple [SUPPORTED: https://www.nationalgeographic.com/science/article/neanderthals-cave-art-humans-evolution-science]; The cave is near Cartagena (Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Los_Aviones]; The cave is at sea level [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Los_Aviones]; The cave yielded perforated seashell beads [SUPPORTED: https://www.nationalgeographic.com/science/article/neanderthals-cave-art-humans-evolution-science]; The shell beads are painted [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Los_Aviones]; The shell beads are thought to be jewelry [SUPPORTED: https://www.nationalgeographic.com/science/article/neanderthals-cave-art-humans-evolution-science]; The jewelry was crafted by Neanderthals [SUPPORTED: https://www.nationalgeographic.com/science/article/neanderthals-cave-art-humans-evolution-science]; The pigments are dated to 115,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Los_Aviones]; The finds (shell beads and pigments) are at least 115,000 years old [SUPPORTED: https://www.nationalgeographic.com/science/article/neanderthals-cave-art-humans-evolution-science]"}]'::jsonb),
    ('818cc875-92d0-4bc3-be80-704620304599'::uuid, 'card_description', 'On the limestone terraces of the Rohri Hills, the Buddhist city of Siraj-ji-Takri survives as stone and mud-brick walls and small mounds atop three different mesas in Upper Sindh.', 'Buddhist city active 450 BC–1200 AD, perched atop three limestone mesas of the Rohri Hills. Stone and mud-brick walls still crown the summits; architectural remains cling to the slopes below.', 'teaser-card-s029-rollback:818cc875-92d0-4bc3-be80-704620304599:card_description', 'rollback of teaser-card-s029: card_description ''Buddhist city active 450 BC–1200 AD, perched atop three limestone mesas of the Rohri Hills. Stone and mud-brick walls still crown the summits; architectural remains cling to the slopes below.'' restored on Siraj-ji-Takri', '454245aa9ec53d83a3e29739121532f5108552727fc88a92b1f40c312f3f9543|d1744a6f56e4c65c811df424bc9f190530f2e1aeb62cb92c94dd76efd8d90583|d1744a6f56e4c65c811df424bc9f190530f2e1aeb62cb92c94dd76efd8d90583', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the limestone terraces of the Rohri Hills, the Buddhist city of Siraj-ji-Takri survives as stone and mud-brick walls and small mounds atop three different mesas in Upper Sindh."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Siraj-ji-Takri [S1]; it lies on the limestone terraces of the Rohri Hills [S2]; it is a Buddhist city [S2]; its ruins survive as stone and mud-brick walls and small mounds [S3]; the ruins are on top of three different mesas [S3]; it is in Upper Sindh [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Siraj-ji-Takri is a Buddhist city / Buddhist archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Siraj-ji-Takri]; The site is in Upper Sindh [SUPPORTED: https://en.wikipedia.org/wiki/Siraj-ji-Takri]; The city lies on limestone terraces [SUPPORTED: https://en.wikipedia.org/wiki/Siraj-ji-Takri]; The limestone terraces belong to the Rohri Hills [SUPPORTED: https://en.wikipedia.org/wiki/Siraj-ji-Takri]; The city survives as stone and mud-brick walls [SUPPORTED: https://en.wikipedia.org/wiki/Siraj-ji-Takri]; The city survives as small mounds [SUPPORTED: https://en.wikipedia.org/wiki/Siraj-ji-Takri]; The remains are atop three different mesas [SUPPORTED: https://en.wikipedia.org/wiki/Siraj-ji-Takri]"}]'::jsonb),
    ('81a32f2d-5102-47f9-adf3-4f5f8fb54561'::uuid, 'card_description', 'Its name means burnt hill: Sokhta Koh, a Harappan site near Pasni, lies strewn with hundreds of thousands of potsherds, and scores of open pit ovens for firing the pottery can still be seen.', 'Harappan outpost on the Makran coast, occupied 2600–1900 BC, about 24 km north of Pasni. Its coastal position aligns with evidence for Bronze Age overseas maritime commerce.', 'teaser-card-s029-rollback:81a32f2d-5102-47f9-adf3-4f5f8fb54561:card_description', 'rollback of teaser-card-s029: card_description ''Harappan outpost on the Makran coast, occupied 2600–1900 BC, about 24 km north of Pasni. Its coastal position aligns with evidence for Bronze Age overseas maritime commerce.'' restored on Sokhta Koh', '80afc170d016807e9f5b4d33865220f12ce4edddd6d13bb1cd952b883ccdb1cd|78ae4f0bcf09d6731ba4dbaf782af9ea5e0805956319e93dc2ba36318951ed24|78ae4f0bcf09d6731ba4dbaf782af9ea5e0805956319e93dc2ba36318951ed24', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Its name means burnt hill: Sokhta Koh, a Harappan site near Pasni, lies strewn with hundreds of thousands of potsherds, and scores of open pit ovens for firing the pottery can still be seen."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Sokhta Koh [S1]; its name means burnt hill [S1]; it is a Harappan site [S1]; it is near Pasni [S1]; it is strewn with hundreds of thousands of potsherds [S6]; scores of open pit ovens for firing pottery can be seen [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sokhta Koh is a Harappan site [SUPPORTED: https://en.wikipedia.org/wiki/Sokhta_Koh]; Sokhta Koh lies near Pasni [SUPPORTED: https://en.wikipedia.org/wiki/Sokhta_Koh]; The name Sokhta Koh means burnt hill [SUPPORTED: https://en.wikipedia.org/wiki/Sokhta_Koh]; The site is strewn with hundreds of thousands of potsherds [SUPPORTED: https://en.wikipedia.org/wiki/Sokhta_Koh]; Scores of open pit ovens can still be seen at the site [SUPPORTED: https://en.wikipedia.org/wiki/Sokhta_Koh]; The open pit ovens were for firing the pottery [SUPPORTED: https://en.wikipedia.org/wiki/Sokhta_Koh]"}]'::jsonb),
    ('829e47ff-5760-4865-96ec-05ed93bd4399'::uuid, 'card_description', 'At the foot of Mount Ossa, overlooking the plains of Thessaly, Sycurium is where Livy has Perseus of Macedon make camp. Its acropolis still shows 5th century BCE fortifications.', '5th century BC city at the foot of Mount Ossa in Thessaly. During the Third Macedonian War, Perseus camped here between the mountain and the Peneus — overlooking Thessaly''s plains and Larissa.', 'teaser-card-s029-rollback:829e47ff-5760-4865-96ec-05ed93bd4399:card_description', 'rollback of teaser-card-s029: card_description "5th century BC city at the foot of Mount Ossa in Thessaly. During the Third Macedonian War, Perseus camped here between the mountain and the Peneus — overlooking Thessaly''s plains and Larissa." restored on Sycurium', '584346bc95de454650392a32b91f74fd0d1a7fd073e6d8c3ff222eedd8ba9991|c5cb202af0616d891b43d107fbad7b6d134ae39500965dbb5b017185ac91c024|c5cb202af0616d891b43d107fbad7b6d134ae39500965dbb5b017185ac91c024', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At the foot of Mount Ossa, overlooking the plains of Thessaly, Sycurium is where Livy has Perseus of Macedon make camp. Its acropolis still shows 5th century BCE fortifications."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Sycurium [S1]; it lies at the foot of Mount Ossa [S1]; it overlooks the plains of Thessaly [S2]; Livy writes that Perseus of Macedon encamped there [S2]; it has an acropolis [S4]; the acropolis has 5th century BCE fortifications [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sycurium was an ancient town of Thessaly (the central claim: a settlement site) [SUPPORTED: https://en.wikipedia.org/wiki/Sycurium]; Sycurium lies at the foot of Mount Ossa [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus:text:1999.02.0167:book=42:chapter=54]; Sycurium overlooks the plains of Thessaly [SUPPORTED: https://en.wikipedia.org/wiki/Sycurium]; Livy writes about Sycurium [SUPPORTED: https://en.wikipedia.org/wiki/Sycurium]; Perseus of Macedon made camp at Sycurium [SUPPORTED: https://en.wikipedia.org/wiki/Sycurium]; Sycurium has an acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Sycurium]; The acropolis shows fortifications of the 5th century BCE [SUPPORTED: https://en.wikipedia.org/wiki/Sycurium]"}]'::jsonb),
    ('84ec7925-84a6-434c-847f-bf3bf9294cff'::uuid, 'card_description', 'In Cornwall, the Iron Age hill fort of Caer Bran ringed a space 200 feet in diameter with a stone-lined wall. At its centre lie remains of a large circular stone building.', 'Circular stone inner wall 3.6 metres thick enclosing a 61-metre space near Sancreed on the Penwith peninsula. The summit commands a 360-degree panorama of the southern Cornish coast.', 'teaser-card-s029-rollback:84ec7925-84a6-434c-847f-bf3bf9294cff:card_description', 'rollback of teaser-card-s029: card_description ''Circular stone inner wall 3.6 metres thick enclosing a 61-metre space near Sancreed on the Penwith peninsula. The summit commands a 360-degree panorama of the southern Cornish coast.'' restored on Caer Bran', '3035dad9edeb797bf0dc747fe241b7d9168d85b52d071765fc16940adfbca47a|2a074269acc0eea9f122fa5d095aa22e87a02f1fa5aede002852ee662e32a02a|2a074269acc0eea9f122fa5d095aa22e87a02f1fa5aede002852ee662e32a02a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Cornwall, the Iron Age hill fort of Caer Bran ringed a space 200 feet in diameter with a stone-lined wall. At its centre lie remains of a large circular stone building."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Caer Bran [S1]; it is in Cornwall [S1]; it is an Iron Age hill fort [S2]; it originally had a stone-lined circular wall enclosing a space 200 feet in diameter [S2]; at its centre are remains of a large circular stone building [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Caer Bran is an Iron Age hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bran]; Caer Bran is in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bran]; The fort had a circular wall that ringed its interior [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bran]; The wall was stone-lined [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bran]; The wall enclosed a space 200 feet in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bran]; At the centre lie remains of a large circular stone building [SUPPORTED: https://en.wikipedia.org/wiki/Caer_Bran]"}]'::jsonb),
    ('852f3856-ecaa-4bab-82c8-a0ab2d11f94f'::uuid, 'card_description', 'Tenayuca holds the earliest Aztec double pyramid yet found. A double stairway climbs to where the temples of Tlaloc and Huitzilopochtli once stood, above a wall of serpents.', 'A double pyramid with twin shrines to Tlaloc and Huitzilopochtli. It was rebuilt six times, each layer encasing the last like a nesting doll.', 'teaser-card-s029-rollback:852f3856-ecaa-4bab-82c8-a0ab2d11f94f:card_description', 'rollback of teaser-card-s029: card_description ''A double pyramid with twin shrines to Tlaloc and Huitzilopochtli. It was rebuilt six times, each layer encasing the last like a nesting doll.'' restored on Tenayuca', 'efd3986e51a4a6f1d9571b1cffb18e160fece1d17604b70192d795f069c55477|3072b61e605ce537a913568be2a216222bc68bed86ece68c3bd454e26e28b130|3072b61e605ce537a913568be2a216222bc68bed86ece68c3bd454e26e28b130', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tenayuca holds the earliest Aztec double pyramid yet found. A double stairway climbs to where the temples of Tlaloc and Huitzilopochtli once stood, above a wall of serpents."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Tenayuca [S1]; it has the earliest Aztec double pyramid yet found [S4]; a double stairway climbs to where the temples once stood [S6]; the temples were those of Tlaloc and Huitzilopochtli [S6]; the temples once stood, now gone [S6]; there is a wall of serpents at the base of the pyramid, below the temples [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-044 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tenayuca is a pre-Columbian archaeological site in the Valley of Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Tenayuca]; Tenayuca holds an Aztec double pyramid (joined bases supporting two temples) [SUPPORTED: https://en.wikipedia.org/wiki/Tenayuca]; Tenayuca has the earliest such Aztec double pyramid yet found [SUPPORTED: https://en.wikipedia.org/wiki/Tenayuca]; A double stairway climbs the temple platform [SUPPORTED: https://en.wikipedia.org/wiki/Tenayuca]; The temples of Tlaloc and Huitzilopochtli once stood at the top of the stairway [SUPPORTED: https://en.wikipedia.org/wiki/Tenayuca]; A wall of serpents (coatepantli) surrounds the temple base [SUPPORTED: https://en.wikipedia.org/wiki/Tenayuca]; The wall of serpents remains on the base of the pyramid below the temples [SUPPORTED: https://en.wikipedia.org/wiki/Tenayuca]"}]'::jsonb),
    ('865dcc6d-fa4c-429b-8c16-908cb96dcec2'::uuid, 'card_description', NULL, 'Roman Tarraco was capital of Hispania Tarraconensis, the largest province in the west. Cyclopean wall bases near the old prison predate the Romans, belonging to an earlier 5th-century BC settlement.', 'teaser-card-s029-rollback:865dcc6d-fa4c-429b-8c16-908cb96dcec2:card_description', 'rollback of teaser-card-s029: card_description ''Roman Tarraco was capital of Hispania Tarraconensis, the largest province in the west. Cyclopean wall bases near the old prison predate the Romans, belonging to an earlier 5th-century BC settlement.'' restored on Tarragona', '||9854eead7b248e8c8543397238f7d99e9e16a3b049f62337485d5bb1071298a4', '[{"source": "lane WB run wb-ws-2026-09-27-02: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The web check could not prove: Tarragona (Roman Tarraco) is a city in Spain, in Catalonia; The web check could not prove: Tarragona is a city (with Roman ruins) in Spain"}]'::jsonb),
    ('86d06431-4ed1-4f2f-9814-7ed808c78968'::uuid, 'card_description', 'Excavated in secret in 2013 to prevent looting, El Castillo de Huarmey hid a royal Wari tomb: 60 bodies seated in rows, and three royal women buried with gold weaving tools.', 'A pyramid-like Wari mausoleum discovered undisturbed in 2013 with 60 burials, including three elite women. Over 1,000 artifacts were interred with them.', 'teaser-card-s029-rollback:86d06431-4ed1-4f2f-9814-7ed808c78968:card_description', 'rollback of teaser-card-s029: card_description ''A pyramid-like Wari mausoleum discovered undisturbed in 2013 with 60 burials, including three elite women. Over 1,000 artifacts were interred with them.'' restored on El Castillo de Huarmey', '2b4162b6c1f8be1dee10c29a212fb7911d1418bb3f0a96d0a07cc31a4ad2901e|e9c32662658963e7a24efeee82d9da1ac7205b471696e3dbada32a7126f2617b|e9c32662658963e7a24efeee82d9da1ac7205b471696e3dbada32a7126f2617b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Excavated in secret in 2013 to prevent looting, El Castillo de Huarmey hid a royal Wari tomb: 60 bodies seated in rows, and three royal women buried with gold weaving tools."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is El Castillo de Huarmey [S1]; it was excavated in secret in 2013 [S3]; the secret excavation was to prevent looting [S3]; it contained a royal Wari tomb [S2]; the tomb held 60 bodies buried in rows in a seated position [S6]; three royal women were buried there [S2, S7]; the three women were buried with gold weaving tools [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "El Castillo de Huarmey is a pyramid-like structure / archaeological complex on the coast of Peru (Ancash Region) [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; El Castillo de Huarmey contained a royal Wari tomb [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; The tomb lay hidden / undisturbed until found (it hid the tomb) [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; El Castillo de Huarmey was excavated in secret [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; The secret excavation took place in 2013 [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; The excavation was kept secret to prevent looting [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; The tomb held 60 bodies [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; The 60 bodies were buried seated and in rows [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; Three royal (Wari) women were buried in the tomb [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]; The three royal women were buried with gold weaving tools [SUPPORTED: https://en.wikipedia.org/wiki/El_Castillo_de_Huarmey]"}]'::jsonb),
    ('86e1dff8-20ac-4d49-85d8-480ee0b9f3ed'::uuid, 'card_description', 'On Salisbury Plain, a single causeway cuts through the two ditch circuits of Robin Hood''s Ball, a Neolithic enclosure probably built around 4000 BC and in use possibly up to 3000 BC.', NULL, 'teaser-card-s029-rollback:86e1dff8-20ac-4d49-85d8-480ee0b9f3ed:card_description', 'rollback of teaser-card-s029: card_description None restored on Robin Hood''s Ball', '443e0dc0b5bfa2644629bc9b02c839f7aa7bafb99b3e04d860f8e17dc05a57a0|e75044b37d4a22f72d4037b8c091439f370b552fc4c361366cf6b5fdc427e5f6|e75044b37d4a22f72d4037b8c091439f370b552fc4c361366cf6b5fdc427e5f6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Salisbury Plain, a single causeway cuts through the two ditch circuits of Robin Hood''s Ball, a Neolithic enclosure probably built around 4000 BC and in use possibly up to 3000 BC."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Robin Hood''s Ball [S1]; it is on Salisbury Plain [S1]; it has a single causeway [S2]; the causeway cuts through two ditch circuits [S2]; it is a Neolithic enclosure [S1]; it was probably built around 4000 BC [S4]; it was possibly in use up to 3000 BC [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Robin Hood''s Ball is an enclosure (a causewayed enclosure) [SUPPORTED: https://en.wikipedia.org/wiki/Robin_Hood%27s_Ball]; Robin Hood''s Ball lies on Salisbury Plain (Wiltshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Robin_Hood%27s_Ball]; The enclosure is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Robin_Hood%27s_Ball]; It has a single causeway (only one causeway) [SUPPORTED: https://en.wikipedia.org/wiki/Robin_Hood%27s_Ball]; The single causeway cuts through the ditch circuits [SUPPORTED: https://en.wikipedia.org/wiki/Robin_Hood%27s_Ball]; The enclosure has two ditch circuits [SUPPORTED: https://en.wikipedia.org/wiki/Robin_Hood%27s_Ball]; It was probably built around 4000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Robin_Hood%27s_Ball]; It was in use possibly up to 3000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Robin_Hood%27s_Ball]"}]'::jsonb),
    ('86ea97f7-ef72-4599-8d68-152db475d12f'::uuid, 'card_description', 'Among the ruins of KirkBiza, an early Byzantine settlement in northwest Syria, lie remains of the earliest preserved house church after Dura-Europos, from the beginning of the 4th century.', 'An Early-Byzantine settlement with the earliest preserved house church after Dura-Europos, dating to the early 4th century. One of the "Dead Cities" of the region.', 'teaser-card-s029-rollback:86ea97f7-ef72-4599-8d68-152db475d12f:card_description', 'rollback of teaser-card-s029: card_description ''An Early-Byzantine settlement with the earliest preserved house church after Dura-Europos, dating to the early 4th century. One of the "Dead Cities" of the region.'' restored on KirkBiza', 'b1f579236b0b661a7be8f78d6361bcbe1fb4d867e05bcd3f895385f19ee7b888|36663183f345f334c17f447cf7ccaa883db40624030aee297616e40587fda9c8|36663183f345f334c17f447cf7ccaa883db40624030aee297616e40587fda9c8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-015", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Among the ruins of KirkBiza, an early Byzantine settlement in northwest Syria, lie remains of the earliest preserved house church after Dura-Europos, from the beginning of the 4th century."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-015 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is KirkBiza (Qirqbize) [S1]; it is an early Byzantine settlement [S1]; it is in northwest Syria [S1]; the ruins hold remains of the earliest preserved house church after Dura-Europos [S2]; the house church dates from the beginning of the 4th century [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "KirkBiza (Qirqbize) is a settlement (ruins), early Byzantine [SUPPORTED: https://en.wikipedia.org/wiki/Qirqbize]; KirkBiza lies in northwest Syria [SUPPORTED: https://en.wikipedia.org/wiki/Qirqbize]; Among the ruins of KirkBiza lie the remains of a house church [SUPPORTED: https://en.wikipedia.org/wiki/Qirqbize]; It is the earliest preserved house church after Dura-Europos [SUPPORTED: https://en.wikipedia.org/wiki/Qirqbize]; The house church dates from the beginning of the 4th century (Tchalenko''s dating; Wondermondo notes Christine Strube instead dates it late 4th to early 5th century) [SUPPORTED: https://en.wikipedia.org/wiki/Dura-Europos_church]"}]'::jsonb),
    ('87ea9721-2bb2-456a-b1e6-8a44dbde62d3'::uuid, 'card_description', 'Stukeley recorded two concentric sarsen rings at Winterbourne Bassett Stone Circle, with an outlying stone to the west. Were they raised by people, or a scatter of natural stones?', 'Smith''s plan, produced in the 1880s, proposed a diameter of circa 71m for the outer circle and 45m for the inner circle.', 'teaser-card-s029-rollback:87ea9721-2bb2-456a-b1e6-8a44dbde62d3:card_description', 'rollback of teaser-card-s029: card_description "Smith''s plan, produced in the 1880s, proposed a diameter of circa 71m for the outer circle and 45m for the inner circle." restored on Winterbourne Bassett Stone Circle', '1b678ba6f721696b1d2fe19d1728480bcadff8c55704403b533f89bbb12af8a5|a8fd0d0313e269aa8f5ff477e56c254864efe1fd92ce5a68899f24a3dcb55beb|a8fd0d0313e269aa8f5ff477e56c254864efe1fd92ce5a68899f24a3dcb55beb', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Stukeley recorded two concentric sarsen rings at Winterbourne Bassett Stone Circle, with an outlying stone to the west. Were they raised by people, or a scatter of natural stones?"}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Stukeley recorded two concentric rings at the site [S2]; the two rings were of sarsen stones [S2]; there is an outlying stone to the west of the rings [S2]; it is undecided whether the site was raised by people or is a scatter of natural stones (implied by the question) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-045 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Winterbourne Bassett Stone Circle is (the remains of) a stone circle in Wiltshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Winterbourne_Bassett_Stone_Circle]; Stukeley recorded the monument (antiquarian record of its layout) [SUPPORTED: https://en.wikipedia.org/wiki/Winterbourne_Bassett_Stone_Circle]; Stukeley recorded two concentric rings [SUPPORTED: https://en.wikipedia.org/wiki/Winterbourne_Bassett_Stone_Circle]; The two rings were of sarsen stones [SUPPORTED: https://en.wikipedia.org/wiki/Winterbourne_Bassett_Stone_Circle]; There was an outlying stone to the west of the rings [SUPPORTED: https://en.wikipedia.org/wiki/Winterbourne_Bassett_Stone_Circle]; It is an open question whether the circle was raised by people (a human-built structure) [SUPPORTED: https://en.wikipedia.org/wiki/Winterbourne_Bassett_Stone_Circle]; It is an open question whether it is a scatter of natural stones rather than a circle [SUPPORTED: https://en.wikipedia.org/wiki/Winterbourne_Bassett_Stone_Circle]"}]'::jsonb),
    ('89489dc6-0f27-48bc-9365-5c74725b46dc'::uuid, 'card_description', 'Casing stones still cover the top third of the Pyramid of Khafre, middle of the three Pyramids of Giza. In 1818 Giovanni Belzoni found its original entrance on the north side.', 'The second-largest pyramid at Giza, tomb of Pharaoh Khafre who ruled 2558–2532 BC. Its summit still wears a cap of original limestone casing.', 'teaser-card-s029-rollback:89489dc6-0f27-48bc-9365-5c74725b46dc:card_description', 'rollback of teaser-card-s029: card_description ''The second-largest pyramid at Giza, tomb of Pharaoh Khafre who ruled 2558–2532 BC. Its summit still wears a cap of original limestone casing.'' restored on Pyramid of Khafre', '43017cc61bf3b0883b143772de27186967179334867efaf1471eb4773f1d58e0|d5bc4095251eeff323115ec97e1b23f4a55e6a38014ecc012a5b1b67939da9ef|d5bc4095251eeff323115ec97e1b23f4a55e6a38014ecc012a5b1b67939da9ef', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Casing stones still cover the top third of the Pyramid of Khafre, middle of the three Pyramids of Giza. In 1818 Giovanni Belzoni found its original entrance on the north side."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "casing stones cover the top third of the pyramid [S6]; the casing is still there (still has cladding at the top) [S2, S6]; the Pyramid of Khafre is the middle of the three Pyramids of Giza [S1]; in 1818 Giovanni Belzoni found the pyramid''s original entrance [S8]; the original entrance is on the north side [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Pyramid of Khafre is a tomb (a pyramid of the Giza necropolis, Egypt) [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khafre]; It is the middle of the three Pyramids of Giza [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khafre]; Casing stones still cover the top third of the pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khafre]; Giovanni Belzoni found the pyramid''s original entrance in 1818 [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khafre]; The original entrance found by Belzoni is on the north side of the pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khafre]"}]'::jsonb),
    ('89f1d2b7-2579-4c33-82b3-8b58d7857c53'::uuid, 'card_description', 'According to Macrobius, Mars was worshipped at the inland city of Acci as Netos, his head surrounded by the sun''s rays. Its site lies 6 kilometres northwest of modern Guadix.', 'Acci was an ancient inland city of Hispania Tarraconensis, on the borders of Baetica.', 'teaser-card-s029-rollback:89f1d2b7-2579-4c33-82b3-8b58d7857c53:card_description', 'rollback of teaser-card-s029: card_description ''Acci was an ancient inland city of Hispania Tarraconensis, on the borders of Baetica.'' restored on Acci', '65df0098430b6fb2af4035a2acdce02150bb76ee2566b449f02d7bccf25e7a80|4db9a7334291e136413108f891e757846a1b7447c07a991ec9f9f4876f3184a8|4db9a7334291e136413108f891e757846a1b7447c07a991ec9f9f4876f3184a8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "According to Macrobius, Mars was worshipped at the inland city of Acci as Netos, his head surrounded by the sun''s rays. Its site lies 6 kilometres northwest of modern Guadix."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "according to Macrobius, Mars was worshipped at Acci [S3]; he was worshipped under the name Netos [S3]; his head was surrounded by the sun''s rays [S3]; Acci was an inland city [S1]; the site lies 6 kilometres northwest of modern Guadix [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Acci was an ancient inland city (in Hispania Tarraconensis, now Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Acci]; According to Macrobius, Mars was worshipped at Acci [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Acci]; Mars was worshipped at Acci under the name Netos [SUPPORTED: https://en.wikipedia.org/wiki/Acci]; The worshipped Mars had his head surrounded by the sun''s rays [SUPPORTED: https://en.wikipedia.org/wiki/Acci]; The site of Acci lies 6 kilometres northwest of modern Guadix [SUPPORTED: https://en.wikipedia.org/wiki/Acci]"}]'::jsonb),
    ('8ae0ddaa-c1bd-4796-9328-ae7e64812b07'::uuid, 'card_description', 'Beside the Danube, Ratiaria held a gold mine worked by the Thracians. Taken by the Dacians of Burebista and later by the Romans, it became the colony Colonia Ulpia Traiana Ratiaria.', 'A Moesian city founded in the 4th century BC on the Danube, later renamed Colonia Ulpia Traiana Ratiaria. It became a major Roman provincial capital.', 'teaser-card-s029-rollback:8ae0ddaa-c1bd-4796-9328-ae7e64812b07:card_description', 'rollback of teaser-card-s029: card_description ''A Moesian city founded in the 4th century BC on the Danube, later renamed Colonia Ulpia Traiana Ratiaria. It became a major Roman provincial capital.'' restored on Ratiaria', '196ce6d1c456afa243b50ddcbd1bc7a448a5a8a8c5c61d608d86f739c7702fbf|85813d5ec5ebf5e64309f9d630999952c48eef51a599239fb822aed5415016fd|85813d5ec5ebf5e64309f9d630999952c48eef51a599239fb822aed5415016fd', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Beside the Danube, Ratiaria held a gold mine worked by the Thracians. Taken by the Dacians of Burebista and later by the Romans, it became the colony Colonia Ulpia Traiana Ratiaria."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Ratiaria lies beside the Danube [S1]; there was a gold mine in the city [S5]; the gold mine was worked by the Thracians [S5]; the city was taken by the Dacians of Burebista [S4]; the city was later taken by the Romans [S4]; it became the Roman colony Colonia Ulpia Traiana Ratiaria [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Ratiaria was an ancient Roman city (a settlement) beside the Danube [SUPPORTED: https://en.wikipedia.org/wiki/Ratiaria]; Ratiaria is in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Ratiaria]; There was a gold mine in the city [SUPPORTED: https://en.wikipedia.org/wiki/Ratiaria]; The gold mine was worked (exploited) by the Thracians [SUPPORTED: https://en.wikipedia.org/wiki/Ratiaria]; Ratiaria was taken by the Dacians of Burebista [SUPPORTED: https://en.wikipedia.org/wiki/Ratiaria]; Ratiaria was later taken by the Romans [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Ratiaria]; It became the Roman colony Colonia Ulpia Traiana Ratiaria [SUPPORTED: https://en.wikipedia.org/wiki/Ratiaria]"}]'::jsonb),
    ('8b8c6154-987e-4d54-b9ca-fac19630061b'::uuid, 'card_description', 'A bank and ditch 4 metres high encircle Banwell Camp in places: an Iron Age hill fort approximately 1.6 miles east of the village of Banwell, excavated in the late 1950s by J.W. Hunt.', 'Ramparts rise 4 metres high in places around this North Somerset fort, with artefacts spanning the Stone Age and Bronze Age. A local folktale links a nearby carved cross to a miraculous origin.', 'teaser-card-s029-rollback:8b8c6154-987e-4d54-b9ca-fac19630061b:card_description', 'rollback of teaser-card-s029: card_description ''Ramparts rise 4 metres high in places around this North Somerset fort, with artefacts spanning the Stone Age and Bronze Age. A local folktale links a nearby carved cross to a miraculous origin.'' restored on Banwell Camp', '424bc137c6b45e96c14f03dadafbb6252b269dd575ef72c8082006feb9e45626|714551c173bca4ad2fc001bfd3b0273908678db1cc684bbf5af8ab36f14b948c|714551c173bca4ad2fc001bfd3b0273908678db1cc684bbf5af8ab36f14b948c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "A bank and ditch 4 metres high encircle Banwell Camp in places: an Iron Age hill fort approximately 1.6 miles east of the village of Banwell, excavated in the late 1950s by J.W. Hunt."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in places the camp is surrounded by a bank and ditch [S3]; the bank and ditch are 4 metres high [S3]; Banwell Camp is an Iron Age hill fort [S1]; it is approximately 1.6 miles east of the village of Banwell [S2]; it was excavated in the late 1950s [S4]; the excavator was J.W. Hunt [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Banwell Camp is an Iron Age hill fort (in Somerset, England) [SUPPORTED: https://en.wikipedia.org/wiki/Banwell_Camp]; The hill fort is approximately 1.6 miles east of the village of Banwell [SUPPORTED: https://en.wikipedia.org/wiki/Banwell_Camp]; In places the fort is surrounded by a bank and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Banwell_Camp]; The bank and ditch are 4 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Banwell_Camp]; The camp was excavated in the late 1950s [SUPPORTED: https://en.wikipedia.org/wiki/Banwell_Camp]; The excavation was by J.W. Hunt [SUPPORTED: https://en.wikipedia.org/wiki/Banwell_Camp]"}]'::jsonb),
    ('8b9f8fb9-7f39-455b-bf0e-bec8e76fb45d'::uuid, 'card_description', 'Forestry has badly damaged Burfa Castle, an Iron Age hillfort near Offa''s Dyke. Beside its likely entrance, three or four banks and ditches form a torturous approach.', 'Burfa Castle is an Iron Age hillfort near the village of Old Radnor, Radnorshire in Powys.', 'teaser-card-s029-rollback:8b9f8fb9-7f39-455b-bf0e-bec8e76fb45d:card_description', 'rollback of teaser-card-s029: card_description ''Burfa Castle is an Iron Age hillfort near the village of Old Radnor, Radnorshire in Powys.'' restored on Burfa Castle', 'f1601dac10b7fccfbd4331c66c3b5bc8cffb466c77ed6d605af9605a893ea5f9|5fda0080ac2c1ce8ee815ff323e6b0d9a0aea06280a50aa69afceb6c56b1e302|5fda0080ac2c1ce8ee815ff323e6b0d9a0aea06280a50aa69afceb6c56b1e302', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Forestry has badly damaged Burfa Castle, an Iron Age hillfort near Offa''s Dyke. Beside its likely entrance, three or four banks and ditches form a torturous approach."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "forestry has badly damaged Burfa Castle [S5]; Burfa Castle is an Iron Age hillfort [S1]; it is near Offa''s Dyke [S3]; beside the hillfort''s likely entrance are three or four banks and ditches [S6]; the banks and ditches form a torturous entrance approach [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-046 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Burfa Castle is an Iron Age hillfort (in Powys, Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Burfa_Castle]; The hillfort is near Offa''s Dyke [SUPPORTED: https://en.wikipedia.org/wiki/Burfa_Castle]; Forestry has badly damaged the site [SUPPORTED: https://en.wikipedia.org/wiki/Burfa_Castle]; The hillfort has a likely entrance, beside which are three or four banks and ditches [SUPPORTED: https://en.wikipedia.org/wiki/Burfa_Castle]; The banks and ditches form a torturous approach to the entrance [SUPPORTED: https://en.wikipedia.org/wiki/Burfa_Castle]"}]'::jsonb),
    ('8bcea3e7-dfdc-4af5-8b75-70fb9e34d7ee'::uuid, 'card_description', 'Flaked stone tools suggest frequent human visits to the Berbati Valley, northeast of Argos, in the Middle Palaeolithic. In 1936 the Potter''s Quarters came to light on Mastos Hill.', 'In 1936, Persson and Åke Åkerström explored the eastern slopes of the Mastos Hill and found what would later be called the Potter''s Quarters.', 'teaser-card-s029-rollback:8bcea3e7-dfdc-4af5-8b75-70fb9e34d7ee:card_description', 'rollback of teaser-card-s029: card_description "In 1936, Persson and Åke Åkerström explored the eastern slopes of the Mastos Hill and found what would later be called the Potter''s Quarters." restored on Berbati Valley', '924fc42951a1fc499bd20eedf07f69fc77c02c9e31795b343e557b68ff741db3|11ce9aae8b2713f2b92f21fc5a13119606746093a25205eeaf0b90f146e4ee12|11ce9aae8b2713f2b92f21fc5a13119606746093a25205eeaf0b90f146e4ee12', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Flaked stone tools suggest frequent human visits to the Berbati Valley, northeast of Argos, in the Middle Palaeolithic. In 1936 the Potter''s Quarters came to light on Mastos Hill."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "flaked stone tools suggest frequent human visits [S6]; the visits were in the Middle Palaeolithic [S6]; the valley is northeast of Argos [S1]; in 1936 the Potter''s Quarters were found [S3]; the Potter''s Quarters lie on Mastos Hill [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Berbati Valley is an archaeological site (a valley settlement site) in Greece. [SUPPORTED: https://en.wikipedia.org/wiki/Berbati_Valley]; The Berbati Valley lies northeast of Argos. [SUPPORTED: https://en.wikipedia.org/wiki/Berbati_Valley]; Flaked stone tools are found in the Berbati Valley from the Middle Palaeolithic. [SUPPORTED: https://en.wikipedia.org/wiki/Berbati_Valley]; The flaked stone tools suggest frequent human visits to the valley in the Middle Palaeolithic. [SUPPORTED: https://en.wikipedia.org/wiki/Berbati_Valley]; The Potter''s Quarters came to light in 1936. [SUPPORTED: https://en.wikipedia.org/wiki/Berbati_Valley]; The Potter''s Quarters came to light on Mastos Hill. [SUPPORTED: https://en.wikipedia.org/wiki/Berbati_Valley]"}]'::jsonb),
    ('8d5976d1-7cf9-4f7c-aeac-f47bacd89805'::uuid, 'card_description', 'On the west coast of Skye, Dun Ardtreck''s first occupation seems to have ended in violence and destruction. Later came iron tools, bronze ornaments and sherds of Roman Samian ware.', 'A rare D-shaped "semi-broch" from 115 BC — a hybrid between a dun and a broch found almost nowhere else. Its unusual shape still puzzles archaeologists.', 'teaser-card-s029-rollback:8d5976d1-7cf9-4f7c-aeac-f47bacd89805:card_description', 'rollback of teaser-card-s029: card_description ''A rare D-shaped "semi-broch" from 115 BC — a hybrid between a dun and a broch found almost nowhere else. Its unusual shape still puzzles archaeologists.'' restored on Dun Ardtreck', '968a970cf4a161a2f67638604ad31e677eab616b0e527c7381f67100f073fbb5|392ae98efa3988e76ca76fc2030ce9b1b758de142a18ec965b20112b1e123bb7|392ae98efa3988e76ca76fc2030ce9b1b758de142a18ec965b20112b1e123bb7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the west coast of Skye, Dun Ardtreck''s first occupation seems to have ended in violence and destruction. Later came iron tools, bronze ornaments and sherds of Roman Samian ware."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dun Ardtreck is on the west coast of Skye [S1]; its first occupation seems to have ended in violence and destruction (hedged) [S6]; a later (second) phase followed the first [S4, S6, S7]; iron tools were found from the later phase [S8]; bronze ornaments were found from the later phase [S8]; sherds of Roman Samian ware were found from the later phase [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dun Ardtreck is a dun (a D-shaped fortification, a semi-broch). [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Ardtreck]; Dun Ardtreck is on the west coast of Skye. [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Ardtreck]; Dun Ardtreck''s first occupation seems to have ended in violence and destruction. [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Ardtreck]; A later (second) phase of occupation followed the first, dated to the middle of the 2nd century AD. [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Ardtreck]; The later finds at Dun Ardtreck include iron tools. [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Ardtreck]; The later finds at Dun Ardtreck include bronze ornaments. [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Ardtreck]; The later finds at Dun Ardtreck include sherds of Roman Samian ware. [SUPPORTED: https://en.wikipedia.org/wiki/Dun_Ardtreck]"}]'::jsonb),
    ('8d5b27e6-c0ab-4c08-8742-7bb0c59bcfa5'::uuid, 'card_description', 'Found in 1947, the Villa of Torre de Palma, about 5 km northwest of Monforte, spans the 1st to the 5th century: a large residential complex with a thermal complex to its east.', 'A Roman villa near Monforte in Lusitania, occupied from the 1st to 5th century AD. Its extensive floor mosaics and courtyard shrine make it among the largest villa complexes on the peninsula.', 'teaser-card-s029-rollback:8d5b27e6-c0ab-4c08-8742-7bb0c59bcfa5:card_description', 'rollback of teaser-card-s029: card_description ''A Roman villa near Monforte in Lusitania, occupied from the 1st to 5th century AD. Its extensive floor mosaics and courtyard shrine make it among the largest villa complexes on the peninsula.'' restored on Villa of Torre de Palma', '1068a6a0977ea6d3f17f2aaf3a880810f13c0bfb4170635deb6f73186e3b6ffd|f1fa05712324802c8bf0f8d39936246a444b8dc83296c40cbc5c1b2af9cbdc60|f1fa05712324802c8bf0f8d39936246a444b8dc83296c40cbc5c1b2af9cbdc60', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Found in 1947, the Villa of Torre de Palma, about 5 km northwest of Monforte, spans the 1st to the 5th century: a large residential complex with a thermal complex to its east."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the villa''s remains were found in 1947 [S2]; it lies about 5 km northwest of Monforte [S1]; its periods span the 1st to the 5th century [S3]; it has a large residential complex [S4]; a thermal complex lies to the east [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Villa of Torre de Palma is a Roman villa near Monforte in Portugal. [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Torre_de_Palma]; The villa was found (its remains discovered) in 1947. [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Torre_de_Palma]; The villa lies about 5 km northwest of Monforte. [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Torre_de_Palma]; The villa spans the 1st to the 5th century. [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Torre_de_Palma]; The villa has a large residential complex. [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_Torre_de_Palma]; A thermal complex lies to the east of the residential complex. [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Villa_of_Torre_de_Palma]"}]'::jsonb),
    ('8e4daf07-4633-4481-865a-9243993c227c'::uuid, 'card_description', 'From the centre of Castle Close, a circular earthwork overlooking the River Exe, the hill forts of Huntsham Castle, Cranmore Castle and Cadbury Castle are all in plain view.', 'A circular Iron Age earthwork at 208 metres above sea level, overlooking the River Exe. Its layout is classic for a hillfort, though it is labelled as a settlement.', 'teaser-card-s029-rollback:8e4daf07-4633-4481-865a-9243993c227c:card_description', 'rollback of teaser-card-s029: card_description ''A circular Iron Age earthwork at 208 metres above sea level, overlooking the River Exe. Its layout is classic for a hillfort, though it is labelled as a settlement.'' restored on Castle Close', 'b8b5e7d03a52fe5b103862d074ea2292bdd024f6c416d32237d65abcafbb6723|b18df94007d2d401bccf775491e22dc8bb094e8fef5f3e423ffaa323172e9542|b18df94007d2d401bccf775491e22dc8bb094e8fef5f3e423ffaa323172e9542', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "From the centre of Castle Close, a circular earthwork overlooking the River Exe, the hill forts of Huntsham Castle, Cranmore Castle and Cadbury Castle are all in plain view."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Castle Close is a circular earthwork [S1]; it overlooks the River Exe [S3]; Huntsham Castle, Cranmore Castle and Cadbury Castle are hill forts [S4, S5]; all three hill forts are in plain view from the centre of the enclosure [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Castle Close is a circular earthwork (a probable Iron Age hill fort or enclosure) in Devon, England. [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Close]; Castle Close overlooks the River Exe. [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Close]; Huntsham Castle is a hill fort in plain view from the centre of Castle Close. [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Close]; Cranmore Castle is a hill fort in plain view from the centre of Castle Close. [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Close]; Cadbury Castle is a hill fort in plain view from the centre of Castle Close. [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Close]"}]'::jsonb),
    ('8e4f5b3f-25dd-471f-96e4-4398f89754bd'::uuid, 'card_description', 'In Cueva de Bolomor, occupied between 350,000 and 120,000 years ago, excavators have recovered two Neanderthal teeth, a fibula fragment and a nearly complete adult parietal bone.', 'Occupied continuously from 350,000 to 120,000 years ago. Four Neanderthal remains — a fibula, two teeth, and a parietal bone — were found in its layers.', 'teaser-card-s029-rollback:8e4f5b3f-25dd-471f-96e4-4398f89754bd:card_description', 'rollback of teaser-card-s029: card_description ''Occupied continuously from 350,000 to 120,000 years ago. Four Neanderthal remains — a fibula, two teeth, and a parietal bone — were found in its layers.'' restored on Cueva de Bolomor', '5dca0381cc230742365fc44887c1103a38be8a34c2aac805bf6828855551c135|6c607e2c507db9df6ab720b2654ad3773a97e45073470423ff355895fa3c678c|6c607e2c507db9df6ab720b2654ad3773a97e45073470423ff355895fa3c678c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Cueva de Bolomor, occupied between 350,000 and 120,000 years ago, excavators have recovered two Neanderthal teeth, a fibula fragment and a nearly complete adult parietal bone."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the cave was occupied between 350,000 and 120,000 years ago [S2]; excavators recovered two Neanderthal teeth [S3]; excavators recovered a fibula fragment [S3]; excavators recovered a nearly complete parietal bone from an adult [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-047 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cueva de Bolomor is a cave (archaeological site) in Spain. [SUPPORTED: https://en.wikipedia.org/wiki/Cueva_de_Bolomor]; The cave was occupied between 350,000 and 120,000 years ago. [SUPPORTED: https://en.wikipedia.org/wiki/Cueva_de_Bolomor]; Excavators have recovered Neanderthal remains at Bolomor, including two teeth. [SUPPORTED: https://en.wikipedia.org/wiki/Cueva_de_Bolomor]; The Neanderthal remains include a fibula fragment. [SUPPORTED: https://en.wikipedia.org/wiki/Cueva_de_Bolomor]; The Neanderthal remains include a nearly complete adult parietal bone. [SUPPORTED: https://en.wikipedia.org/wiki/Cueva_de_Bolomor]"}]'::jsonb),
    ('8f0bd6a2-46b6-46cb-afbb-efd18b2471d8'::uuid, 'card_description', 'On a plateau by the Akhurian River, the Yereruyk Archaeological Site holds an Armenian church whose name means quivering, ringed by thick walls, underground rooms and a water reservoir.', 'A 4th–6th-century basilica near ancient Ani, built on a plateau above the Akhurian River. Its plan ranks it among the oldest surviving examples of early church architecture in the Caucasus.', 'teaser-card-s029-rollback:8f0bd6a2-46b6-46cb-afbb-efd18b2471d8:card_description', 'rollback of teaser-card-s029: card_description ''A 4th–6th-century basilica near ancient Ani, built on a plateau above the Akhurian River. Its plan ranks it among the oldest surviving examples of early church architecture in the Caucasus.'' restored on Yereruyk Archaeological Site', '503214d312dbd9d952d84f2d30e9e5b12f7b0b4e6da6e4a6a218c88af65f1284|214266f941e2f51d9023592e3b3e7698b18c09f36d54781a0b516610f73350fe|214266f941e2f51d9023592e3b3e7698b18c09f36d54781a0b516610f73350fe', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a plateau by the Akhurian River, the Yereruyk Archaeological Site holds an Armenian church whose name means quivering, ringed by thick walls, underground rooms and a water reservoir."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the church stands on a plateau near the Akhurian River [S2]; the site holds an Armenian church [S1]; the name Yererouk means quivering [S3]; the church was surrounded with thick walls [S5]; underground rooms surround the church [S6]; a water reservoir surrounds the church [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The site is an ancient Armenian church (Yereruyk, also Yererouk), a place with a church, near Anipemza in Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Yererouk]; The church stands on a plateau by the Akhurian River [SUPPORTED: https://en.wikipedia.org/wiki/Yererouk]; The name Yereruyk means quivering [SUPPORTED: https://en.wikipedia.org/wiki/Yererouk]; The church was ringed (surrounded) by thick walls [SUPPORTED: https://en.wikipedia.org/wiki/Yererouk]; The church was surrounded by underground rooms [SUPPORTED: https://en.wikipedia.org/wiki/Yererouk]; The church was surrounded by a water reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Yererouk]"}]'::jsonb),
    ('90923e91-3e29-4568-aa2e-989de43d2a0f'::uuid, 'card_description', 'At least seven Neanderthals were found at La Ferrassie, all in a 60 cm layer dated to 74-68 thousand years ago. Its Mousterian burial structures provided evidence of Neanderthal burial.', 'A cave occupied 70,000 years ago where seven Neanderthals were buried, including infants and a fetus. One of the strongest cases for Neanderthal burial rituals.', 'teaser-card-s029-rollback:90923e91-3e29-4568-aa2e-989de43d2a0f:card_description', 'rollback of teaser-card-s029: card_description ''A cave occupied 70,000 years ago where seven Neanderthals were buried, including infants and a fetus. One of the strongest cases for Neanderthal burial rituals.'' restored on La Ferrassie', 'e494334d8b4c3c3f45fc64d91ec228fc7e4848b90551f2ec20b43e13aa0cf6e8|df943a04a28134ced8a8eecf83f5e1c2f2d35a36811f41da579e96a40528698a|df943a04a28134ced8a8eecf83f5e1c2f2d35a36811f41da579e96a40528698a', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At least seven Neanderthals were found at La Ferrassie, all in a 60 cm layer dated to 74-68 thousand years ago. Its Mousterian burial structures provided evidence of Neanderthal burial."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "at least seven Neanderthals were found at La Ferrassie [S5]; all were found in a 60 cm layer [S6]; the layer is dated to 74-68 thousand years ago [S6]; Mousterian burial structures were found at the site [S4]; they provided evidence of Neanderthal burial [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "La Ferrassie is an archaeological site (cave and rock shelters) in France [SUPPORTED: https://en.wikipedia.org/wiki/La_Ferrassie]; At least seven Neanderthals were found there [SUPPORTED: https://en.wikipedia.org/wiki/La_Ferrassie]; The site is in France [SUPPORTED: https://en.wikipedia.org/wiki/La_Ferrassie]; All were in a 60 cm layer [SUPPORTED: https://en.wikipedia.org/wiki/La_Ferrassie]; The layer is dated to 74-68 thousand years ago [SUPPORTED: https://en.wikipedia.org/wiki/La_Ferrassie]; It has Mousterian burial structures [SUPPORTED: https://en.wikipedia.org/wiki/La_Ferrassie]; Its Mousterian burial structures provided evidence of Neanderthal burial [SUPPORTED: https://en.wikipedia.org/wiki/La_Ferrassie]"}]'::jsonb),
    ('90dac465-52f7-495a-ae8e-79953fa8d9b9'::uuid, 'card_description', 'At the crossing of Silk Road caravan routes, Otrar''s fortress and fortified city formed a five-corner hill about 18 meters high. The Mongol invasion interrupted its prosperity.', 'A Silk Road ghost city that commanded the crossroads connecting China, Europe, the Middle East, and Siberia. It thrived from the 1st to 15th century AD as a regional trade hub.', 'teaser-card-s029-rollback:90dac465-52f7-495a-ae8e-79953fa8d9b9:card_description', 'rollback of teaser-card-s029: card_description ''A Silk Road ghost city that commanded the crossroads connecting China, Europe, the Middle East, and Siberia. It thrived from the 1st to 15th century AD as a regional trade hub.'' restored on Otrar', 'b0973c5b713a01df53e1c15032c001bb4901716f36578ed8da7291584547ea70|2afe1c38ae18025d981daa3683d9f87902bb1ebab6bb214cae1dcbf400e540b2|2afe1c38ae18025d981daa3683d9f87902bb1ebab6bb214cae1dcbf400e540b2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At the crossing of Silk Road caravan routes, Otrar''s fortress and fortified city formed a five-corner hill about 18 meters high. The Mongol invasion interrupted its prosperity."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Otrar lay at the intersection of Silk Road caravan routes [S3]; the Ark (fortress) and Shahristan (fortified city) formed a five-corner hill [S6]; the hill is about 18 meters high [S6]; the Mongol invasion interrupted Otrar''s prosperity [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Otrar is an ancient fortress and fortified city in Kazakhstan (its Ark is the central fortress and Shahristan the fortified city) [SUPPORTED: https://en.wikipedia.org/wiki/Otrar]; Otrar lay at the crossing of Silk Road caravan routes [SUPPORTED: https://en.wikipedia.org/wiki/Otrar]; The fortress and fortified city formed a five-corner hill [SUPPORTED: https://en.wikipedia.org/wiki/Otrar]; The hill was about 18 meters high [SUPPORTED: https://en.wikipedia.org/wiki/Otrar]; The Mongol invasion interrupted Otrar''s prosperity [SUPPORTED: https://en.wikipedia.org/wiki/Otrar]"}]'::jsonb),
    ('91b72d89-5ca1-4427-a02f-7423266c6f39'::uuid, 'card_description', 'Under a building in Toledo lies the Cave of Hercules, a vaulted Roman space that appears to have been a water reservoir, fed by the aqueduct bridge across the River Tagus.', 'A Roman-era vaulted chamber beneath Toledo, constructed in the early centuries AD. Medieval legends made it the "Cave of Hercules" — but it was likely just a water cistern.', 'teaser-card-s029-rollback:91b72d89-5ca1-4427-a02f-7423266c6f39:card_description', 'rollback of teaser-card-s029: card_description ''A Roman-era vaulted chamber beneath Toledo, constructed in the early centuries AD. Medieval legends made it the "Cave of Hercules" — but it was likely just a water cistern.'' restored on Cave of Hercules', 'cac88065bfc86ac6d9556189fcf622451a4879e30eb46d684a456ee771378f87|baf7db742c760e93477ba00c8ae5ef5895f6cada5ee8aeb03b3141ec9e992967|baf7db742c760e93477ba00c8ae5ef5895f6cada5ee8aeb03b3141ec9e992967', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-016", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Under a building in Toledo lies the Cave of Hercules, a vaulted Roman space that appears to have been a water reservoir, fed by the aqueduct bridge across the River Tagus."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-016 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Cave of Hercules lies under a building [S2]; it is in Toledo [S1]; it is a vaulted space [S1]; it is Roman [S1, S3]; it appears to have been a water reservoir (hedged) [S4]; it was supplied via the aqueduct bridge across the River Tagus (within the same hedge) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-048 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Cave of Hercules is a subterranean space in the city of Toledo, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Hercules]; It lies under a building [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Hercules]; The space dates to Roman times [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Hercules]; The space is vaulted [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Hercules]; The space appears to have been a water reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Hercules]; The reservoir was fed by an aqueduct bridge [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Hercules]; The aqueduct bridge crossed the River Tagus [SUPPORTED: https://en.wikipedia.org/wiki/Cave_of_Hercules]"}]'::jsonb),
    ('91f09c72-5e12-49da-bce4-9f139d7e8e2a'::uuid, 'card_description', 'Near the marina of Vilamoura, the Roman Ruins of Cerro da Vila hold a villa that had its own port, serving fertile lands irrigated by a dam two kilometres from the settlement.', 'A Roman villa near modern Vilamoura, occupied from the 1st century AD. Its ruins sit incongruously next to a contemporary luxury resort.', 'teaser-card-s029-rollback:91f09c72-5e12-49da-bce4-9f139d7e8e2a:card_description', 'rollback of teaser-card-s029: card_description ''A Roman villa near modern Vilamoura, occupied from the 1st century AD. Its ruins sit incongruously next to a contemporary luxury resort.'' restored on Roman Ruins of Cerro da Vila', '63ad023babed926e4acf79fe3b0739fbfb3419ca92208385f3c851d1de5e3abc|08028f552ccc4c8f28fad6a8c202390ee2629c14e90193a85f237da7e95b3178|08028f552ccc4c8f28fad6a8c202390ee2629c14e90193a85f237da7e95b3178', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near the marina of Vilamoura, the Roman Ruins of Cerro da Vila hold a villa that had its own port, serving fertile lands irrigated by a dam two kilometres from the settlement."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "near the marina of Vilamoura [S2]; the site holds the remains of a villa [S1]; the settlement had its own port [S3]; the port served fertile lands [S3]; the lands were irrigated by a dam [S3]; the dam was two kilometres from the settlement [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cerro da Vila is the ruin of a Roman villa in Portugal near the marina of Vilamoura [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Cerro_da_Vila]; The site is in Portugal (Algarve) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Cerro_da_Vila]; It had a port [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Cerro_da_Vila]; The port served fertile lands [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Cerro_da_Vila]; The lands were irrigated by a dam [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Cerro_da_Vila]; The dam is two kilometres from the settlement [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Cerro_da_Vila]; It is a Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Roman_ruins_of_Cerro_da_Vila]"}]'::jsonb),
    ('9299ee5a-03c7-415b-a8d2-b8a7b8c71a7e'::uuid, 'card_description', 'On a promontory some 65–80 metres above sea level, Greenway Camp, an Iron Age hill fort also called Noss, looks out over Noss Point in the Dart Estuary, close to Dartmouth in Devon.', 'Iron Age hill fort on a Dart Estuary promontory, 65–80 metres above the sea. Also known as Noss, it commanded sweeping river-mouth views — a natural lookout as much as a fortress.', 'teaser-card-s029-rollback:9299ee5a-03c7-415b-a8d2-b8a7b8c71a7e:card_description', 'rollback of teaser-card-s029: card_description ''Iron Age hill fort on a Dart Estuary promontory, 65–80 metres above the sea. Also known as Noss, it commanded sweeping river-mouth views — a natural lookout as much as a fortress.'' restored on Greenway Camp', 'cecff2896938e769666ae98ac24a5982cc393570a0116f509f27970d9761927d|5cbeb53f5867b6e0b6255271bc7763bb342512e4c3072014c0ddf3cdf18b6a17|5cbeb53f5867b6e0b6255271bc7763bb342512e4c3072014c0ddf3cdf18b6a17', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a promontory some 65–80 metres above sea level, Greenway Camp, an Iron Age hill fort also called Noss, looks out over Noss Point in the Dart Estuary, close to Dartmouth in Devon."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the fort lies on a promontory [S2]; it stands some 65-80 metres above sea level [S2]; the site is Greenway Camp [S1]; it is an Iron Age hill fort [S1]; it is also called Noss [S1]; it looks out over Noss Point [S2]; Noss Point lies in the Dart Estuary [S2]; it is close to Dartmouth [S1]; it is in Devon [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/