    ('94cc711b-1ce7-4f7d-867c-64d59c65c76d'::uuid, 'card_description', 'Roughly 3600 meters up on the Inca Trail, Puyupatamarca is known as La Ciudad entre la Niebla. Among its Inca ruins, five small stone baths run with fresh water through the wet season.', 'An Inca city at 3,600 m altitude, nicknamed "The City Above the Clouds." Five ritual stone baths still channel water through carved channels.', 'teaser-card-s029-rollback:94cc711b-1ce7-4f7d-867c-64d59c65c76d:card_description', 'rollback of teaser-card-s029: card_description ''An Inca city at 3,600 m altitude, nicknamed "The City Above the Clouds." Five ritual stone baths still channel water through carved channels.'' restored on Puyupatamarca', '8a923d96d730a10caa7ae1ca3e0a60a3148bae9bbcc3210d877e0d5c7d711fa8|14afb02a88ef721d4d08e85d2797ae1fb0ee7b4a6d8037bf5d2e3cb2f0abb35c|14afb02a88ef721d4d08e85d2797ae1fb0ee7b4a6d8037bf5d2e3cb2f0abb35c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Roughly 3600 meters up on the Inca Trail, Puyupatamarca is known as La Ciudad entre la Niebla. Among its Inca ruins, five small stone baths run with fresh water through the wet season."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies roughly 3600 meters up [S2]; it is on the Inca Trail [S1]; the site is Puyupatamarca [S1]; it is known as La Ciudad entre la Niebla [S2]; it has Inca ruins [S3]; it has five small stone baths [S3]; the baths run with fresh water through the wet season [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Puyupatamarca is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]; Puyupatamarca lies on the Inca Trail [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]; Puyupatamarca lies at an altitude of roughly 3600 meters [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]; Puyupatamarca is known as La Ciudad entre la Niebla [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]; The site contains Inca ruins [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]; There are five baths among the ruins [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]; The baths are small and of stone [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]; The baths contain fresh running water [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]; The water runs through the wet season [SUPPORTED: https://en.wikipedia.org/wiki/Puyupatamarca]"}]'::jsonb),
    ('94fd509a-71e9-4a1e-b235-4eb91b1cacca'::uuid, 'card_description', 'Mamshit National Park holds a former Nabataean caravan stop on the Incense Road, where the biggest hoard ever found in Israel came to light: 10,500 silver coins weighing 72 kg in total.', 'A former Nabataean caravan stop on the Incense Road that grew into a Byzantine city. Horse stables here could hold dozens of animals — vital for the desert trade route.', 'teaser-card-s029-rollback:94fd509a-71e9-4a1e-b235-4eb91b1cacca:card_description', 'rollback of teaser-card-s029: card_description ''A former Nabataean caravan stop on the Incense Road that grew into a Byzantine city. Horse stables here could hold dozens of animals — vital for the desert trade route.'' restored on Mamshit National Park', 'd9d77e4f51d123f1a473f23acc64279a13c2abd6bc55c1a13ad6c3e5dd788ed0|4879382bf2a8e47d437c2e801ce47dafff74ebdac1d1a7147dbf29547a2a8faf|4879382bf2a8e47d437c2e801ce47dafff74ebdac1d1a7147dbf29547a2a8faf', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Mamshit National Park holds a former Nabataean caravan stop on the Incense Road, where the biggest hoard ever found in Israel came to light: 10,500 silver coins weighing 72 kg in total."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is Mamshit National Park [S1]; the site is a former Nabataean caravan stop [S1]; the caravan stop lay on the Incense Road [S2]; the biggest hoard ever found in Israel was discovered there [S8]; the hoard consisted of 10,500 silver coins [S8]; the coins weighed 72 kg in total [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-049 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Mamshit (Mampsis) is a former Nabataean caravan stop [SUPPORTED: https://en.wikipedia.org/wiki/Mampsis]; The caravan stop lay on the Incense Road [SUPPORTED: https://en.wikipedia.org/wiki/Mampsis]; The site lies within Mamshit National Park [SUPPORTED: https://www.historyhit.com/locations/mamshit/]; The biggest hoard ever found in Israel was discovered at Mamshit [SUPPORTED: https://en.wikipedia.org/wiki/Mampsis]; The hoard consisted of 10,500 silver coins [SUPPORTED: https://en.wikipedia.org/wiki/Mampsis]; The hoard weighed 72 kg in total [SUPPORTED: https://en.wikipedia.org/wiki/Mampsis]"}]'::jsonb),
    ('951c140b-1698-4495-9c6b-c78254c2b4cd'::uuid, 'card_description', 'Near Old Hunstanton in Norfolk stood Seahenge: 55 split oak trunks around an upturned tree root, built in the spring-summer of 2049 BC, one trunk with a narrow Y fork permitting access.', 'A timber circle from 2049 BC with an upturned oak tree root at its centre. The upside-down tree may symbolise a world turned on its head — death itself.', 'teaser-card-s029-rollback:951c140b-1698-4495-9c6b-c78254c2b4cd:card_description', 'rollback of teaser-card-s029: card_description ''A timber circle from 2049 BC with an upturned oak tree root at its centre. The upside-down tree may symbolise a world turned on its head — death itself.'' restored on Seahenge', '908e425cba0896dd37a40e1c6bac11cc321ecd4f6ce9acbf5cd7ed01f25b6acb|98aa240c4d6158574fc8d20a875256602b85c08a276fd0c2be733d8b2a9b3862|98aa240c4d6158574fc8d20a875256602b85c08a276fd0c2be733d8b2a9b3862', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Old Hunstanton in Norfolk stood Seahenge: 55 split oak trunks around an upturned tree root, built in the spring-summer of 2049 BC, one trunk with a narrow Y fork permitting access."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Seahenge stood near Old Hunstanton [S1]; it stood in Norfolk [S1]; it had 55 split oak trunks [S3]; the trunks formed a ring around an upturned tree root at the centre [S2, S3]; it was built in the spring-summer of 2049 BC [S2]; one trunk had a narrow Y fork [S6]; the Y fork permitted access to the central area [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Seahenge was a prehistoric monument (a timber circle) [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; It was near Old Hunstanton [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; It was in Norfolk [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; It consisted of 55 trunks [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; The trunks were oak [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; The trunks were split [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; The trunks formed a ring around an upturned tree root [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; It was built in 2049 BC [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; It was built in the spring-summer of that year (spring or early summer felling) [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; One trunk had a narrow Y fork [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; The Y fork permitted access to the centre of the ring [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]; Seahenge no longer stands at its site (implied by ''stood''): it was excavated and removed [SUPPORTED: https://en.wikipedia.org/wiki/Seahenge]"}]'::jsonb),
    ('95981699-02b0-4ab9-9ccc-cd9efc14f97a'::uuid, 'card_description', 'On the outskirts of Dorchester, Flagstones Enclosure was a ring of unevenly spaced pits from the late 4th millennium BC. Some chalk walls bore engraved designs, probably cut with flint.', 'A late Neolithic enclosure discovered beneath Thomas Hardy''s house. Half was excavated during bypass construction; the rest still lies under the novelist''s garden.', 'teaser-card-s029-rollback:95981699-02b0-4ab9-9ccc-cd9efc14f97a:card_description', 'rollback of teaser-card-s029: card_description "A late Neolithic enclosure discovered beneath Thomas Hardy''s house. Half was excavated during bypass construction; the rest still lies under the novelist''s garden." restored on Flagstones Enclosure', '7bbe8e1f8b9a51252377f95248f260ac03d216567343b6da37d6e03ac9efcc14|c3ed4eca7e20a2aa56fd0344eceab10dc71250e6f2a28d8f7ee6e5d0e7127f1f|c3ed4eca7e20a2aa56fd0344eceab10dc71250e6f2a28d8f7ee6e5d0e7127f1f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the outskirts of Dorchester, Flagstones Enclosure was a ring of unevenly spaced pits from the late 4th millennium BC. Some chalk walls bore engraved designs, probably cut with flint."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the enclosure is on the outskirts of Dorchester [S1]; it was a ring of pits [S5]; the pits were unevenly spaced [S5]; it dates from the late 4th millennium BC [S5]; some chalk walls bore engraved designs [S6]; the designs were probably cut with flint [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Flagstones Enclosure is a late Neolithic enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Flagstones_Enclosure]; It is on the outskirts of Dorchester [SUPPORTED: https://en.wikipedia.org/wiki/Flagstones_Enclosure]; It is in England [SUPPORTED: https://en.wikipedia.org/wiki/Flagstones_Enclosure]; It was a ring of pits [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18013]; The pits were unevenly spaced [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18013]; The pit ring dates from the late 4th millennium BC [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18013]; The chalk walls of some of the pits bore designs [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18013]; The designs were engraved [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18013]; The engraved designs were probably cut with flint [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18013]"}]'::jsonb),
    ('96395824-9c31-477a-bf51-13ecb5035d56'::uuid, 'card_description', NULL, 'A Vaccaean city, part of an early Celtic society in northern Iberia. The Vaccaei were the first sedentary people of the Duero-Pisuerga valley.', 'teaser-card-s029-rollback:96395824-9c31-477a-bf51-13ecb5035d56:card_description', 'rollback of teaser-card-s029: card_description ''A Vaccaean city, part of an early Celtic society in northern Iberia. The Vaccaei were the first sedentary people of the Duero-Pisuerga valley.'' restored on Pintia', '||bd17b9cd25bc0d72f56eabe8d02a8c8e5671bc0a1a36f8f5638bfa183e53fc69', '[{"source": "lane WB run wb-ws-2026-09-27-02: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The web check could not prove: Pintia was an ancient city of the Vaccaei (Vaccean culture), in the area of Padilla de Duero, Spain; The web check contradicts: The Romans destroyed Pintia (https://www.pintiavaccea.es/seccion/las-quintanas-in-pintia: \"Pintia survived as a city after the Roman conquest until the 4th/5th to the 7th centuries A.D.\"); The web check contradicts: The destruction buried forever the Vaccean culture (https://www.pintiavaccea.es/seccion/vaccean-legacy: \"the Romanization of Spain (the native assimilation of Roman culture) should not be confused with the end of the Vaccean culture\"); The web check could not prove: The destruction buried forever the Vaccean religion and language; The web check could not prove: Pintia is an ancient city of the Vaccaei around Padilla de Duero, Spain"}]'::jsonb),
    ('9737ca03-ad30-46d2-8740-3dec20bed1ea'::uuid, 'card_description', 'Found in 2007 as a highway was widened, Grakliani Hill holds a temple to a fertility goddess from the seventh century BCE and signs of human presence possibly going back 300,000 years.', NULL, 'teaser-card-s029-rollback:9737ca03-ad30-46d2-8740-3dec20bed1ea:card_description', 'rollback of teaser-card-s029: card_description None restored on Grakliani Hill', 'df998df67771300f0051d39dab0fe7819a0c5692e473e9193452d71dbe626c21|9f49057b6a02d1f5ea0451ddef355dab0a306d13ae80f07f386ee8114e1d081b|9f49057b6a02d1f5ea0451ddef355dab0a306d13ae80f07f386ee8114e1d081b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Found in 2007 as a highway was widened, Grakliani Hill holds a temple to a fertility goddess from the seventh century BCE and signs of human presence possibly going back 300,000 years."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "found in 2007 [S2]; discovered during highway widening [S2]; holds a temple to a fertility goddess [S3]; the temple dates from the seventh century BCE [S3]; signs of human presence possibly going back 300,000 years (hedged) [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Grakliani Hill is an archaeological site (excavation) in Georgia [SUPPORTED: https://en.wikipedia.org/wiki/Grakliani_Hill]; The site was found in 2007 while a highway was being widened [SUPPORTED: https://en.wikipedia.org/wiki/Grakliani_Hill]; The site holds a temple (to a fertility goddess) [SUPPORTED: https://en.wikipedia.org/wiki/Grakliani_Hill]; The temple dates from the seventh century BCE [SUPPORTED: https://en.wikipedia.org/wiki/Grakliani_Hill]; Evidence of human presence possibly going back 300,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Grakliani_Hill]"}]'::jsonb),
    ('97443726-74e9-40ac-b388-5daa15448ff1'::uuid, 'card_description', 'On a terrace above the Rio Grande de Nazca, Pernil Alto grew sweet potatoes and lima beans. Radiocarbon dates make it the oldest known inland, sedentary farming village in the Central Andes.', 'The oldest known inland sedentary agricultural village in the Central Andes, dating to 3800-3000 BC. It documents the transition from foraging to farming.', 'teaser-card-s029-rollback:97443726-74e9-40ac-b388-5daa15448ff1:card_description', 'rollback of teaser-card-s029: card_description ''The oldest known inland sedentary agricultural village in the Central Andes, dating to 3800-3000 BC. It documents the transition from foraging to farming.'' restored on Pernil Alto', '45759eba7ca92d0407973caad45549ad1cede884de25460134bf90dcb641e70f|6113ce7e4bbbfbc944c0de51d865bcf33e93dfe362087a8dca4fd82f32a98a01|6113ce7e4bbbfbc944c0de51d865bcf33e93dfe362087a8dca4fd82f32a98a01', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a terrace above the Rio Grande de Nazca, Pernil Alto grew sweet potatoes and lima beans. Radiocarbon dates make it the oldest known inland, sedentary farming village in the Central Andes."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies on a terrace above the Rio Grande de Nazca [S6]; the site is Pernil Alto [S1]; its inhabitants grew sweet potatoes [S7]; its inhabitants grew lima beans [S7]; radiocarbon dates establish it as the oldest known inland sedentary agricultural village in the Central Andes [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-050 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Pernil Alto is an archaeological site (an agricultural village) in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Pernil_Alto]; It lies on a terrace above the Rio Grande de Nazca [SUPPORTED: https://en.wikipedia.org/wiki/Pernil_Alto]; The terrace is above the irrigated valley of the Rio Grande de Nazca river [SUPPORTED: https://en.wikipedia.org/wiki/Pernil_Alto]; Its inhabitants grew sweet potatoes and lima beans [SUPPORTED: https://en.wikipedia.org/wiki/Pernil_Alto]; Radiocarbon dates make it the oldest known inland, sedentary agricultural village in the Central Andes [SUPPORTED: https://en.wikipedia.org/wiki/Pernil_Alto]"}]'::jsonb),
    ('98377ef7-6274-433a-98f5-72bd3baf7397'::uuid, 'card_description', 'Beside the Guadiana river rises Alarcos, a small hill of quartzite and volcanic rock 675 metres above sea level, crowned by the remains of a Bronze and Iron Age Iberian oppidum.', NULL, 'teaser-card-s029-rollback:98377ef7-6274-433a-98f5-72bd3baf7397:card_description', 'rollback of teaser-card-s029: card_description None restored on Alarcos', 'b83efd2af1a0d59f69f39e3bfb30aae0eb9c17ff9b6abeb5a6ab1ba2d55cb82f|f8dc2dbd59eb1dccbc71d59b49a54e845739962c24f4dcf0b66cda625abb151e|f8dc2dbd59eb1dccbc71d59b49a54e845739962c24f4dcf0b66cda625abb151e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Beside the Guadiana river rises Alarcos, a small hill of quartzite and volcanic rock 675 metres above sea level, crowned by the remains of a Bronze and Iron Age Iberian oppidum."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Guadiana river flows beside the site [S2]; the site is Alarcos, a small hill [S1]; the hill is made of quartzite [S2]; the hill has components of volcanic origin [S2]; the hill stands 675 metres above sea level [S2]; an archaeological site with remains lies on top of the hill [S3, S4]; the archaeological site has a Bronze/Iron Age Iberian oppidum [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Alarcos is a hill with an archaeological site on top, in Spain (Campo de Calatrava, between the Spanish municipalities of Poblete and Ciudad Real) [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]; Alarcos is a small hill [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]; The hill lies beside the Guadiana river [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]; The hill stands 675 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]; The hill is made of quartzite [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]; The hill also contains rock of volcanic origin [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]; The hill is crowned by an archaeological site (the remains on top of the hill) [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]; The remains are those of an oppidum of the Bronze and Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]; The oppidum is Iberian [SUPPORTED: https://en.wikipedia.org/wiki/Alarcos]"}]'::jsonb),
    ('98c794a6-57b5-4783-b38d-3693bb60b91b'::uuid, 'card_description', 'Built wholly of Parian marble for Athens'' offerings to Apollo, the Athenian Treasury bears metopes of the labors of Theseus and Herakles, the earliest known Theseus in large-scale sculpture.', 'The date of construction is disputed, and scholarly opinions range from 510 to 480 BCE. The Athenian treasury metopes display the earliest known presence of Theseus in a large-scale sculpture.', 'teaser-card-s029-rollback:98c794a6-57b5-4783-b38d-3693bb60b91b:card_description', 'rollback of teaser-card-s029: card_description ''The date of construction is disputed, and scholarly opinions range from 510 to 480 BCE. The Athenian treasury metopes display the earliest known presence of Theseus in a large-scale sculpture.'' restored on Athenian Treasury, Delphi', '22e275ffd30d3b833aa5c78024f2d11d74c0b58e1be29ae40eb587f32d24b2de|bc0474a4fcc9f9f9d5c09a0b64fb846e33c26c5c5c35cddb811d6486f22b0526|bc0474a4fcc9f9f9d5c09a0b64fb846e33c26c5c5c35cddb811d6486f22b0526', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Built wholly of Parian marble for Athens'' offerings to Apollo, the Athenian Treasury bears metopes of the labors of Theseus and Herakles, the earliest known Theseus in large-scale sculpture."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the treasury is built wholly of Parian marble [S2]; it was built for the offerings of Athens to Apollo''s sanctuary [S1]; the site is the Athenian Treasury [S1]; it bears metopes depicting the labors of Theseus and Herakles [S6]; the metopes show the earliest known Theseus in large-scale sculpture [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Athenian Treasury is a treasury building at Delphi, below the Temple of Apollo, built to house offerings [SUPPORTED: https://en.wikipedia.org/wiki/Athenian_Treasury]; Delphi, where the treasury stands, is in Greece [SUPPORTED: https://en.wikipedia.org/wiki/Delphi]; The treasury is built wholly of Parian marble [SUPPORTED: https://en.wikipedia.org/wiki/Athenian_Treasury]; The offerings were those of Athens, to Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Athenian_Treasury]; The treasury bears metopes depicting the labors of Theseus and Herakles [SUPPORTED: https://en.wikipedia.org/wiki/Athenian_Treasury]; The metopes show the earliest known Theseus in large-scale sculpture [SUPPORTED: https://en.wikipedia.org/wiki/Athenian_Treasury]"}]'::jsonb),
    ('996e0b32-f8ca-4d04-8900-ed937b729269'::uuid, 'card_description', NULL, 'Karstic sea cliff housing one of Europe’s most significant Palaeolithic cave sites. Accessible only by boat today — during the ice ages, the sea level stood more than 100 metres lower.', 'teaser-card-s029-rollback:996e0b32-f8ca-4d04-8900-ed937b729269:card_description', 'rollback of teaser-card-s029: card_description ''Karstic sea cliff housing one of Europe’s most significant Palaeolithic cave sites. Accessible only by boat today — during the ice ages, the sea level stood more than 100 metres lower.'' restored on Apidima Cave', '||e3837d14ce6b6e6fc328f959f5e804b9d8322e2eb050221081eb231305c71d0a', '[{"source": "lane WB run wb-ws-2026-09-27-02: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The tone rules are broken (see the checker''s reasons).; S5 only says that research published in July 2019 indicates the Apidima 2 skull fragment has Neanderthal morphology; the card states ''one with Neanderthal morphology'' as plain fact and so sharpens the hedge. Keep the attribution, for example ''research in 2019 indicates one has Neanderthal morphology''.; The web check could not prove: Apidima Cave is a cave (complex) in southern Greece, on the Mani Peninsula; The web check could not prove: The Apidima 2 skull fragment has Neanderthal morphology; The web check could not prove: The Apidima 2 skull fragment is more than 170,000 years old; The web check could not prove: Apidima Cave is a cave complex (Greece); The web check could not prove: Research published in July 2019 dated the Apidima 1 skull to more than 210,000 years"}]'::jsonb),
    ('9a219745-8e06-4d8a-8396-c5d5656990a5'::uuid, 'card_description', 'On a steep Orkney hill facing the Bays of Firth and Kirkwall rises Wideford Hill Chambered Cairn: three concentric walls around a tomb where no human remains were found in the 1840s.', 'A Neolithic cairn on Orkney similar in design to the famous Maeshowe tomb, dating to around 2000 BC. It sits on a steep west-facing hill overlooking the bays.', 'teaser-card-s029-rollback:9a219745-8e06-4d8a-8396-c5d5656990a5:card_description', 'rollback of teaser-card-s029: card_description ''A Neolithic cairn on Orkney similar in design to the famous Maeshowe tomb, dating to around 2000 BC. It sits on a steep west-facing hill overlooking the bays.'' restored on Wideford Hill Chambered Cairn', '730ca1763465acd7db3b55ed477f3590f6065d9746202cbdfca74213ef5fcec2|6f3d3a8c4aee83fda19e98b077a6cffb8a533732ddeaeaba4a3e82cc268b44f7|6f3d3a8c4aee83fda19e98b077a6cffb8a533732ddeaeaba4a3e82cc268b44f7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-017", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a steep Orkney hill facing the Bays of Firth and Kirkwall rises Wideford Hill Chambered Cairn: three concentric walls around a tomb where no human remains were found in the 1840s."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-017 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site stands on a steep hill [S3]; the hill is on Orkney [S1]; the monument faces the Bays of Firth and Kirkwall [S3]; the site is Wideford Hill Chambered Cairn [S1]; the cairn has three concentric walls [S4]; the cairn is a tomb (burial monument) [S2, S7]; no human remains were found when it was excavated in the 1840s [S6, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Wideford Hill Chambered Cairn is a Neolithic chambered cairn (a tomb) on Mainland, Orkney, Scotland [SUPPORTED: https://en.wikipedia.org/wiki/Wideford_Hill_chambered_cairn]; It stands on a steep hill on Orkney [SUPPORTED: https://en.wikipedia.org/wiki/Wideford_Hill_chambered_cairn]; It faces the Bays of Firth and Kirkwall [SUPPORTED: https://en.wikipedia.org/wiki/Wideford_Hill_chambered_cairn]; The cairn has three concentric walls [SUPPORTED: https://en.wikipedia.org/wiki/Wideford_Hill_chambered_cairn]; The walls surround a tomb [SUPPORTED: https://en.wikipedia.org/wiki/Wideford_Hill_chambered_cairn]; No human remains were found in the tomb [SUPPORTED: https://en.wikipedia.org/wiki/Wideford_Hill_chambered_cairn]; The site was excavated in the 1840s [SUPPORTED: https://en.wikipedia.org/wiki/Wideford_Hill_chambered_cairn]"}]'::jsonb),
    ('9a4ccc75-d0d1-4bf8-8068-ef4cf3221aaf'::uuid, 'card_description', 'Near Gweek stands the Tolvan Holed Stone, the largest holed stone in Cornwall: a triangular stone 2.3 m high, pierced near its base by a hole approximately 43 cm in diameter.', 'A Neolithic holed stone 2.3 m tall with a 43 cm hole near its base — the largest of its type in Cornwall. It was moved to its present spot in 1847.', 'teaser-card-s029-rollback:9a4ccc75-d0d1-4bf8-8068-ef4cf3221aaf:card_description', 'rollback of teaser-card-s029: card_description ''A Neolithic holed stone 2.3 m tall with a 43 cm hole near its base — the largest of its type in Cornwall. It was moved to its present spot in 1847.'' restored on Tolvan Holed Stone', '3d625e31e2e26fefc98c6a3cf95118510d331d0f492cae6e1599677c567903c2|564cb5a490c5920643f1c8f4666e5d40cc115a7f7c8207876d7e98b5b8fa3b2b|564cb5a490c5920643f1c8f4666e5d40cc115a7f7c8207876d7e98b5b8fa3b2b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Gweek stands the Tolvan Holed Stone, the largest holed stone in Cornwall: a triangular stone 2.3 m high, pierced near its base by a hole approximately 43 cm in diameter."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Tolvan Holed Stone stands near Gweek [S4]; it is the largest holed stone in Cornwall [S5]; it is a triangular stone [S1]; it is 2.3 m high [S2]; it has a hole near its base [S3]; the hole is approximately 43 cm in diameter [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-051 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Tolvan Holed Stone is a megalithic standing stone near the village of Gweek in Cornwall, England [SUPPORTED: https://en.wikipedia.org/wiki/Tolvan_holed_stone]; It is a holed stone [SUPPORTED: https://en.wikipedia.org/wiki/Tolvan_holed_stone]; It is the largest holed stone in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/Tolvan_holed_stone]; It is a triangular stone [SUPPORTED: https://en.wikipedia.org/wiki/Tolvan_holed_stone]; The stone is 2.3 m high [SUPPORTED: https://en.wikipedia.org/wiki/Tolvan_holed_stone]; The stone is pierced by a hole near its base [SUPPORTED: https://en.wikipedia.org/wiki/Tolvan_holed_stone]; The hole is approximately 43 cm in diameter [SUPPORTED: https://en.wikipedia.org/wiki/Tolvan_holed_stone]"}]'::jsonb),
    ('9adf8063-9af0-4610-b021-0e9f0cef4c02'::uuid, 'card_description', 'In the Alentejo, 34 granite menhirs of the Vale Maria do Meio Cromlech form an east-west arch, and two of them bear engravings of circles, horseshoes and lunar crescents.', 'The cromlech was identified in 1993 by a team of students from the University of Lisbon, led by Manuel Calado.', 'teaser-card-s029-rollback:9adf8063-9af0-4610-b021-0e9f0cef4c02:card_description', 'rollback of teaser-card-s029: card_description ''The cromlech was identified in 1993 by a team of students from the University of Lisbon, led by Manuel Calado.'' restored on Vale Maria do Meio Cromlech', '036fa74a8abc0064981b107586e2bc9afb65c35c53a765d79cf097bdef50251d|394799562bb619cf2860963f8a70626097eea7eceb5921b5bd95a08e955242dd|394799562bb619cf2860963f8a70626097eea7eceb5921b5bd95a08e955242dd', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Alentejo, 34 granite menhirs of the Vale Maria do Meio Cromlech form an east-west arch, and two of them bear engravings of circles, horseshoes and lunar crescents."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is in the Alentejo [S1]; the cromlech has 34 granite menhirs [S4]; the stones form an east-west arch [S5]; two of the menhirs bear engravings [S6]; the engravings show circles, horseshoes and lunar crescents [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Vale Maria do Meio Cromlech is a megalithic stone circle (cromlech) in the Alentejo region of Portugal, in Evora district [SUPPORTED: https://en.wikipedia.org/wiki/Vale_Maria_do_Meio_Cromlech]; The enclosure is made of 34 menhirs [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=visitaveis&subsid=53603&lang=en]; The 34 menhirs are of granite (the national heritage portal says mostly granite) [SUPPORTED: https://en.wikipedia.org/wiki/Vale_Maria_do_Meio_Cromlech]; The stones form an east-west arch [SUPPORTED: https://en.wikipedia.org/wiki/Vale_Maria_do_Meio_Cromlech]; Two of the menhirs bear engravings [SUPPORTED: https://arqueologia.patrimoniocultural.pt/index.php?sid=visitaveis&subsid=53603&lang=en]; The engravings on the two menhirs are of circles, horseshoes and lunar crescents [SUPPORTED: https://en.wikipedia.org/wiki/Vale_Maria_do_Meio_Cromlech]"}]'::jsonb),
    ('9b4bc2f9-521a-467f-a1a6-ebd4563221e9'::uuid, 'card_description', 'On Walbury Hill, at 297 metres the highest natural point in South East England, lies the Iron Age hill fort of Walbury Camp, crowning a summit of the North Wessex Downs.', 'At 297 metres, this is the highest natural point in the South East. A hillfort crowns the summit, its banks and ditch cut into the chalk downs above the village of Combe.', 'teaser-card-s029-rollback:9b4bc2f9-521a-467f-a1a6-ebd4563221e9:card_description', 'rollback of teaser-card-s029: card_description ''At 297 metres, this is the highest natural point in the South East. A hillfort crowns the summit, its banks and ditch cut into the chalk downs above the village of Combe.'' restored on Walbury Hill', '64692bb18d82d1ab0ae19dc690eef2a0560caecbef21a38a1ba7a4bd14e1ca9b|adb1c98dec2e76892069c08bf9e4b25cf676be6ae6668589f846626aacf60e3d|adb1c98dec2e76892069c08bf9e4b25cf676be6ae6668589f846626aacf60e3d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Walbury Hill, at 297 metres the highest natural point in South East England, lies the Iron Age hill fort of Walbury Camp, crowning a summit of the North Wessex Downs."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Walbury Hill is 297 metres high [S2]; it is the highest natural point in South East England [S2]; the Iron Age hill fort of Walbury Camp lies on the hill''s summit [S3]; the hill is a summit of the North Wessex Downs [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Walbury Hill is a summit of the North Wessex Downs (Berkshire, England) with an Iron Age hill fort, Walbury Camp, on its summit [SUPPORTED: https://en.wikipedia.org/wiki/Walbury_Hill]; On the summit of Walbury Hill lies the Iron Age hill fort of Walbury Camp [SUPPORTED: https://en.wikipedia.org/wiki/Walbury_Hill]; Walbury Hill stands 297 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Walbury_Hill]; Walbury Hill is the highest natural point in South East England [SUPPORTED: https://en.wikipedia.org/wiki/Inkpen_and_Walbury_Hills]"}]'::jsonb),
    ('9c827589-5230-48e4-bf6b-fb7dee9e7c35'::uuid, 'card_description', 'A climb of 290 m from Machu Picchu leads to Inti Punku, once the main entrance to the sacred city: a site dedicated to Inti, the Sun god, with windows and gates held up by terraces.', 'The Sun Gate of Machu Picchu -- once the main checkpoint for entering the sacred city. The stone steps controlled all access to the sanctuary.', 'teaser-card-s029-rollback:9c827589-5230-48e4-bf6b-fb7dee9e7c35:card_description', 'rollback of teaser-card-s029: card_description ''The Sun Gate of Machu Picchu -- once the main checkpoint for entering the sacred city. The stone steps controlled all access to the sanctuary.'' restored on Inti Punku', '793a258c889cfa85fff659868ba185e4dfc120bee0e60705a9dd275b6cd8723b|e9e0078f02606ad269072eb6f62841564b5963674a42dcfd1c24eba69217d805|e9e0078f02606ad269072eb6f62841564b5963674a42dcfd1c24eba69217d805', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "A climb of 290 m from Machu Picchu leads to Inti Punku, once the main entrance to the sacred city: a site dedicated to Inti, the Sun god, with windows and gates held up by terraces."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the climb from Machu Picchu to Inti Punku is 290 m [S4]; Inti Punku was once the main entrance to the sacred city (Machu Picchu) [S1, S2]; the site is dedicated to Inti, the Sun god [S3]; the site has windows and gates [S5]; the windows and gates are held up by terraces [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Inti Punku (the Sun Gate) is an archaeological site in the Cusco Region of Peru belonging to the sacred city of Machu Picchu [SUPPORTED: https://en.wikipedia.org/wiki/Inti_Punku]; The climb from Machu Picchu to Inti Punku is 290 m [SUPPORTED: https://en.wikipedia.org/wiki/Inti_Punku]; Inti Punku was once the main entrance to Machu Picchu, the sacred city [SUPPORTED: https://en.wikipedia.org/wiki/Inti_Punku]; Inti Punku is dedicated to Inti, the Sun god [SUPPORTED: https://en.wikipedia.org/wiki/Inti_Punku]; The site has windows and gates held up by terraces [SUPPORTED: https://en.wikipedia.org/wiki/Inti_Punku]"}]'::jsonb),
    ('9e723832-0a2b-43f9-90d1-3743b61b91ed'::uuid, 'card_description', 'At the entrance to Lot''s Cave above the Dead Sea stood a Byzantine monastery of the 5th-7th centuries, with a large basilical church, a reservoir and a hostel complex.', '3rd millennium BC. A cave believed to be that of Lot, nephew of Abraham. A Byzantine church, reservoir, and mosaics surround it — and an inscription inside mentions Lot by name.', 'teaser-card-s029-rollback:9e723832-0a2b-43f9-90d1-3743b61b91ed:card_description', 'rollback of teaser-card-s029: card_description ''3rd millennium BC. A cave believed to be that of Lot, nephew of Abraham. A Byzantine church, reservoir, and mosaics surround it — and an inscription inside mentions Lot by name.'' restored on Lot''s Cave', '2707c70e594201f432e8ae238c92d59b223c0d7a0855d02d7e203a4b3acb132b|1b08ae0cc80ba9db596200fb6b53a47268703fd5aff68c2870d0c713745d29b9|1b08ae0cc80ba9db596200fb6b53a47268703fd5aff68c2870d0c713745d29b9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At the entrance to Lot''s Cave above the Dead Sea stood a Byzantine monastery of the 5th-7th centuries, with a large basilical church, a reservoir and a hostel complex."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "at the entrance to Lot''s Cave stood a Byzantine monastery [S1]; above the Dead Sea [S1, S2]; monastery dates to the 5th-7th centuries [S2]; large basilical church [S2, S6]; a reservoir [S6]; a hostel complex [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Lot''s Cave: a Byzantine monastic site at the entrance to a cave near the Dead Sea in Jordan [SUPPORTED: https://en.wikipedia.org/wiki/Monastery_of_St_Lot]; It was a monastery [SUPPORTED: https://en.wikipedia.org/wiki/Monastery_of_St_Lot]; The monastery dates to the 5th-7th centuries [SUPPORTED: https://en.wikipedia.org/wiki/Monastery_of_St_Lot]; The monastery had a large basilical church [SUPPORTED: https://en.wikipedia.org/wiki/Monastery_of_St_Lot]; The monastery had a reservoir [SUPPORTED: https://en.wikipedia.org/wiki/Monastery_of_St_Lot]; The monastery had a hostel complex [SUPPORTED: https://en.wikipedia.org/wiki/Monastery_of_St_Lot]; The monastery overlooked the Dead Sea (stood above it) [SUPPORTED: https://en.wikipedia.org/wiki/Monastery_of_St_Lot]"}]'::jsonb),
    ('9ee5d047-1345-405a-a689-4624365e0104'::uuid, 'card_description', 'Kot Diji, dug in 1954-55, gave its name to a culture of the Early Harappan Phase, circa 3300-2800 BCE; its houses and fortifications were made from unbaked mud-bricks.', 'A fortified settlement from 3300 BC that was a forerunner of the Indus Civilization. The citadel sits on a 12-metre mound above the surrounding plains.', 'teaser-card-s029-rollback:9ee5d047-1345-405a-a689-4624365e0104:card_description', 'rollback of teaser-card-s029: card_description ''A fortified settlement from 3300 BC that was a forerunner of the Indus Civilization. The citadel sits on a 12-metre mound above the surrounding plains.'' restored on Kot Diji', 'b66fcd0c0a18a23cb6c13ec4e25a4a5c54d89ac563532bfd7b7d712fcc85ef79|3f5c43e38b042ca2bae4b8926e8a1277b6f50134f4d800312f2852ee6dd4f4e9|3f5c43e38b042ca2bae4b8926e8a1277b6f50134f4d800312f2852ee6dd4f4e9', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Kot Diji, dug in 1954-55, gave its name to a culture of the Early Harappan Phase, circa 3300-2800 BCE; its houses and fortifications were made from unbaked mud-bricks."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Kot Diji was excavated in 1954-55 [S1]; Kot Diji gave its name to a culture (it is the type site of the Kot Diji Culture) [S2]; the culture belongs to the Early Harappan Phase [S2]; the Early Harappan Phase dates to circa 3300-2800 BCE [S2]; the houses were made from unbaked mud-bricks [S5]; the fortifications were made from unbaked mud-bricks [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-052 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Kot Diji is an ancient site (settlement with citadel) of the Indus Valley Civilisation in Sindh, Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Kot_Diji]; Kot Diji was excavated in 1954-55 (other sources give 1955 and 1957) [SUPPORTED: https://en.wikipedia.org/wiki/Kot_Diji]; Kot Diji gave its name to a culture (it is the type site of the Kot Diji Culture) [SUPPORTED: https://en.wikipedia.org/wiki/Kot_Diji]; The Kot Diji culture belongs to the Early Harappan Phase [SUPPORTED: https://en.wikipedia.org/wiki/Kot_Diji]; The Kot Diji culture dates to circa 3300-2800 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Kot_Diji]; In the earliest layer (Kot Diji I) the houses were made from unbaked mud-bricks [SUPPORTED: https://en.wikipedia.org/wiki/Kot_Diji]; In the earliest layer (Kot Diji I) the fortifications were made from unbaked mud-bricks (the Harappa page and Britannica also mention stone in the defensive wall) [SUPPORTED: https://en.wikipedia.org/wiki/Kot_Diji]"}]'::jsonb),
    ('9f328a68-b73d-4fd9-bc44-a78d3cae960c'::uuid, 'card_description', 'Where Exeter stands today lay Isca Dumnoniorum, a Roman fortress of the Second Augustan Legion established circa AD 55, its name a Latin form of a Brittonic name for flowing water.', 'Originally a legionary fortress for the Second Augustan Legion around 55 AD. 70% of the Roman wall survives as the base of the medieval city walls.', 'teaser-card-s029-rollback:9f328a68-b73d-4fd9-bc44-a78d3cae960c:card_description', 'rollback of teaser-card-s029: card_description ''Originally a legionary fortress for the Second Augustan Legion around 55 AD. 70% of the Roman wall survives as the base of the medieval city walls.'' restored on Isca Dumnoniorum', 'ad0c2d3d98163012f1b4b22989dc662d5f01e67e31c4c840bfceae0c746dbd77|81cd648971209238411a44143a695d0fe6160c20daa36ecb80d83222a873aeae|81cd648971209238411a44143a695d0fe6160c20daa36ecb80d83222a873aeae', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Where Exeter stands today lay Isca Dumnoniorum, a Roman fortress of the Second Augustan Legion established circa AD 55, its name a Latin form of a Brittonic name for flowing water."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Isca Dumnoniorum lay where Exeter stands today [S1]; it was a Roman fortress of the Second Augustan Legion [S1]; it was established circa AD 55 [S1]; its name is a Latin form (Latinization) of a Brittonic name [S2]; the Brittonic name describes flowing water [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Isca Dumnoniorum was a Roman (legionary) fortress at the site of present-day Exeter [SUPPORTED: https://en.wikipedia.org/wiki/Isca_Dumnoniorum]; The fortress lay where Exeter stands today [SUPPORTED: https://en.wikipedia.org/wiki/Isca_Dumnoniorum]; The fortress was that of the Second Augustan Legion [SUPPORTED: https://en.wikipedia.org/wiki/Isca_Dumnoniorum]; The fortress was established circa AD 55 [SUPPORTED: https://en.wikipedia.org/wiki/Isca_Dumnoniorum]; The name Isca Dumnoniorum is a Latin form of a Brittonic name for flowing water [SUPPORTED: https://en.wikipedia.org/wiki/Isca_Dumnoniorum]"}]'::jsonb),
    ('9f611d23-894b-45e0-ad29-a692e6d46241'::uuid, 'card_description', 'On the northern summit of Gallox Hill, south west of Dunster, Black Ball Camp keeps a 3 metres high rampart and a 2 metres deep ditch: an Iron Age hillfort also known as British Camp.', 'Rampart 3 metres high with a 2-metre ditch rings this Somerset summit. Stone tower foundations were visible at the start of the 20th century but have since disappeared entirely.', 'teaser-card-s029-rollback:9f611d23-894b-45e0-ad29-a692e6d46241:card_description', 'rollback of teaser-card-s029: card_description ''Rampart 3 metres high with a 2-metre ditch rings this Somerset summit. Stone tower foundations were visible at the start of the 20th century but have since disappeared entirely.'' restored on Black Ball Camp', 'fb3f18f75085e5eb0e18f603e2fb9d5b915d955026c87eaf788c728853eac617|6ad6403684a75b5e389949540669b5379397f836ef64cb924c72b533d98a2d0d|6ad6403684a75b5e389949540669b5379397f836ef64cb924c72b533d98a2d0d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the northern summit of Gallox Hill, south west of Dunster, Black Ball Camp keeps a 3 metres high rampart and a 2 metres deep ditch: an Iron Age hillfort also known as British Camp."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Black Ball Camp is on the northern summit of Gallox Hill [S1]; it lies south west of Dunster [S1]; it has a 3 metres high rampart [S4]; it has a 2 metres deep ditch [S4]; it is an Iron Age hillfort [S1]; it is also known as British Camp [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Black Ball Camp is an Iron Age hillfort (in England) [SUPPORTED: https://en.wikipedia.org/wiki/Black_Ball_Camp]; It lies south west of Dunster [SUPPORTED: https://en.wikipedia.org/wiki/Black_Ball_Camp]; It lies on the northern summit of Gallox Hill [SUPPORTED: https://en.wikipedia.org/wiki/Black_Ball_Camp]; It has a rampart 3 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Black_Ball_Camp]; It has a ditch 2 metres deep [SUPPORTED: https://en.wikipedia.org/wiki/Black_Ball_Camp]; It is also known as British Camp [SUPPORTED: https://en.wikipedia.org/wiki/Black_Ball_Camp]"}]'::jsonb),
    ('a06ad29e-06f0-450b-bf8e-cd3b7231f096'::uuid, 'card_description', 'In Avebury parish stand The Longstones, Adam and Eve. Adam, an estimated 62 tons, fell over in 1911 and was re-erected in 1912; close by lay a Beaker burial of a middle-aged man.', NULL, 'teaser-card-s029-rollback:a06ad29e-06f0-450b-bf8e-cd3b7231f096:card_description', 'rollback of teaser-card-s029: card_description None restored on The Longstones', '8f962d3f0876450c5abf6b49fe22047bd7f8204515e77074522df496e44a76c0|cba3cfd305c124e48fe7dc626dfb441fa62935081f6eaf7d6aa874f88d787d2f|cba3cfd305c124e48fe7dc626dfb441fa62935081f6eaf7d6aa874f88d787d2f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In Avebury parish stand The Longstones, Adam and Eve. Adam, an estimated 62 tons, fell over in 1911 and was re-erected in 1912; close by lay a Beaker burial of a middle-aged man."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Longstones stand in Avebury parish [S1]; the two stones are known as Adam and Eve [S2]; Adam weighs an estimated 62 tons [S3]; Adam fell over in 1911 [S7]; Adam was re-erected in 1912 [S7]; a Beaker burial (inhumation) was found close by the stone [S8]; the burial was of a middle-aged man [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Longstones are standing stones (a prehistoric cove and its companion stone) in Avebury parish [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstones]; The Longstones are two standing stones [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstones]; The two stones are called Adam and Eve [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstones]; Adam weighs an estimated 62 tons [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstones]; Adam fell over in 1911 [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstones]; Adam was re-erected in 1912 [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstones]; A Beaker burial of a middle-aged man lay close by [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstones]"}]'::jsonb),
    ('a0d8cc79-b3fd-448f-b983-8155c26de853'::uuid, 'card_description', 'A mound near Antequera covers the Tholos de El Romeral, a megalithic burial site built around 1800 BC, one of the most important examples of early Bronze Age architecture in southern Europe.', 'Corbelled tholos tomb at Antequera dated to 1800 BC, with a 43 m entrance passage ending in a domed chamber. Two flanking tombs—Dolmen de Menga and Dolmen de Viera—lie to the southwest.', 'teaser-card-s029-rollback:a0d8cc79-b3fd-448f-b983-8155c26de853:card_description', 'rollback of teaser-card-s029: card_description ''Corbelled tholos tomb at Antequera dated to 1800 BC, with a 43 m entrance passage ending in a domed chamber. Two flanking tombs—Dolmen de Menga and Dolmen de Viera—lie to the southwest.'' restored on Tholos de El Romeral', 'a9a24b16d77a19b64da5c87a012a8f383bd91f66fcd2715b572b0e43eb778b83|6ec38be578d2266d75552f8b966bfcba7d7c601b4f6704f9676e69bc43e139d8|6ec38be578d2266d75552f8b966bfcba7d7c601b4f6704f9676e69bc43e139d8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "A mound near Antequera covers the Tholos de El Romeral, a megalithic burial site built around 1800 BC, one of the most important examples of early Bronze Age architecture in southern Europe."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Tholos de El Romeral is near Antequera [S1]; it is covered by a mound [S3]; it is a megalithic burial site [S2]; it was built around 1800 BC [S2]; it is one of the most important examples of early Bronze Age architecture in southern Europe [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tholos de El Romeral is a megalithic burial site (a tholos tomb) near Antequera [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_de_El_Romeral]; It is a megalithic burial site [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_de_El_Romeral]; It is covered by a mound [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_de_El_Romeral]; It was built around 1800 BC [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_de_El_Romeral]; It is one of the most important examples of early Bronze Age architecture in southern Europe [SUPPORTED: https://en.wikipedia.org/wiki/Tholos_de_El_Romeral]"}]'::jsonb),
    ('a0f583a3-f913-4c6a-9300-68f005b06999'::uuid, 'card_description', 'At Lambityeco, two imposing masks of Cocijo, the Zapotec rain god, flank the entrance of an elite residence, and the facade of Tomb 6 shows prehispanic governors more than 1300 years old.', 'A Zapotec settlement occupied from 700 BC to 750 AD, with 197 mounds across 117 hectares. Stucco friezes depict a ruling couple with elaborate headdresses and name glyphs.', 'teaser-card-s029-rollback:a0f583a3-f913-4c6a-9300-68f005b06999:card_description', 'rollback of teaser-card-s029: card_description ''A Zapotec settlement occupied from 700 BC to 750 AD, with 197 mounds across 117 hectares. Stucco friezes depict a ruling couple with elaborate headdresses and name glyphs.'' restored on Lambityeco', 'd7d0a5c05bab23b003d2d104faa97cd20fdb3ff180c735e88dfc3859d03ac5cf|cac24b580c8f7769da9f519c697544feb666b5696c00fde62749e5236b03b9f6|cac24b580c8f7769da9f519c697544feb666b5696c00fde62749e5236b03b9f6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At Lambityeco, two imposing masks of Cocijo, the Zapotec rain god, flank the entrance of an elite residence, and the facade of Tomb 6 shows prehispanic governors more than 1300 years old."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "two imposing masks of Cocijo flank the entrance of an elite residence at Lambityeco [S3]; Cocijo is the Zapotec rain god [S3]; the facade of Tomb 6 shows prehispanic governors [S4, S5]; the governors are more than 1300 years old [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-053 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Lambityeco is a Zapotec archaeological site in Oaxaca, Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Lambityeco]; Two imposing masks of Cocijo flank the entrance of an elite residence at Lambityeco [SUPPORTED: https://en.wikipedia.org/wiki/Lambityeco]; Cocijo is the Zapotec rain god [SUPPORTED: https://en.wikipedia.org/wiki/Lambityeco]; The facade of Tomb 6 shows prehispanic governors [SUPPORTED: https://en.wikipedia.org/wiki/Lambityeco]; The governors shown on the Tomb 6 facade are more than 1300 years old [SUPPORTED: https://en.wikipedia.org/wiki/Lambityeco]"}]'::jsonb),
    ('a25c9c7d-58f2-402a-a484-ac9ec953979f'::uuid, 'card_description', 'On a high rocky ledge in the Khyber Pass rises the Sphola Stupa, a Buddhist stone mound on a tiered base, where Gandhara sculptures were excavated, now housed in the museum in Peshawar.', 'A Buddhist stupa in the Khyber Pass with a dome on a three-tiered stone base. Large sections have fallen away, exposing the raw construction underneath.', 'teaser-card-s029-rollback:a25c9c7d-58f2-402a-a484-ac9ec953979f:card_description', 'rollback of teaser-card-s029: card_description ''A Buddhist stupa in the Khyber Pass with a dome on a three-tiered stone base. Large sections have fallen away, exposing the raw construction underneath.'' restored on Sphola Stupa', '196739ff3e26f040370111b2adbd6acce58ef67573dfb5f485942fcbbe358b08|27fb91f8fa0a46714d0f8a974e03689248d5b1473fdd094d2d644ece64f8705c|27fb91f8fa0a46714d0f8a974e03689248d5b1473fdd094d2d644ece64f8705c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a high rocky ledge in the Khyber Pass rises the Sphola Stupa, a Buddhist stone mound on a tiered base, where Gandhara sculptures were excavated, now housed in the museum in Peshawar."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Sphola Stupa stands on a high rocky ledge [S2]; it is in the Khyber Pass [S1, S3]; it is a Buddhist monument [S1]; it consists of a stone mound on a tiered base [S2]; Gandhara sculptures were excavated at the stupa [S4]; the sculptures are now housed in the museum in Peshawar [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sphola Stupa is a monument (a stupa) in the Khyber Pass, Pakistan [SUPPORTED: https://en.wikipedia.org/wiki/Sphola_Stupa]; The monument is Buddhist [SUPPORTED: https://en.wikipedia.org/wiki/Sphola_Stupa]; It stands on a high rocky ledge [SUPPORTED: https://en.wikipedia.org/wiki/Sphola_Stupa]; It consists of a stone mound [SUPPORTED: https://en.wikipedia.org/wiki/Sphola_Stupa]; The stone mound rests on a tiered base [SUPPORTED: https://en.wikipedia.org/wiki/Sphola_Stupa]; Gandhara sculptures were excavated at the stupa [SUPPORTED: https://en.wikipedia.org/wiki/Sphola_Stupa]; The excavated sculptures are now housed in the museum in Peshawar [SUPPORTED: https://en.wikipedia.org/wiki/Sphola_Stupa]"}]'::jsonb),
    ('a2c6e1bf-1538-43c4-ad4a-65a0186193a7'::uuid, 'card_description', 'Found in 2008, the North Bersted Man was a warrior buried in the first century BC with an exceptional set of objects, his helmet adorned with two crests that once ran down its back.', 'An Iron Age warrior buried with an exceptional set of grave goods, including a unique helmet. He was about 45, stood 1.72 metres tall, and was buried with full military honors.', 'teaser-card-s029-rollback:a2c6e1bf-1538-43c4-ad4a-65a0186193a7:card_description', 'rollback of teaser-card-s029: card_description ''An Iron Age warrior buried with an exceptional set of grave goods, including a unique helmet. He was about 45, stood 1.72 metres tall, and was buried with full military honors.'' restored on North Bersted Man', '80f6ab5673fd314b96e118ae537e6b4e3654a3548327acfac98468552542ded8|16d5bd81ed1bb7966f42c76cd407ae33685c34cffd6948fa1bbdf6e83aa6130f|16d5bd81ed1bb7966f42c76cd407ae33685c34cffd6948fa1bbdf6e83aa6130f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Found in 2008, the North Bersted Man was a warrior buried in the first century BC with an exceptional set of objects, his helmet adorned with two crests that once ran down its back."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the North Bersted Man was found in 2008 [S1]; he was a warrior [S1]; he was buried in the first century BC [S4]; the burial contained an exceptional set of objects [S2]; his helmet was adorned with two crests [S5, S6]; the crests once ran down the back of the helmet [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The North Bersted Man was a warrior found in a burial (grave find) near North Bersted [SUPPORTED: https://en.wikipedia.org/wiki/North_Bersted_Man]; He was found in 2008 [SUPPORTED: https://en.wikipedia.org/wiki/North_Bersted_Man]; The burial dates to the first century BC [SUPPORTED: https://en.wikipedia.org/wiki/North_Bersted_Man]; The burial contained an exceptional set of objects [SUPPORTED: https://en.wikipedia.org/wiki/North_Bersted_Man]; The warrior''s helmet was adorned with crests [SUPPORTED: https://en.wikipedia.org/wiki/North_Bersted_Man]; The helmet had two crests [SUPPORTED: https://en.wikipedia.org/wiki/North_Bersted_Man]; The crests once ran down the back of the helmet [SUPPORTED: https://en.wikipedia.org/wiki/North_Bersted_Man]"}]'::jsonb),
    ('a3b55317-bae1-42b5-9c64-477749bdc2d5'::uuid, 'card_description', 'On a hill in the Arequipa Region lie the cemeteries and village of Huamboy, a name possibly from the Quechua wamp''uy, meaning to navigate, to sail, to travel by boat.', 'Pre-Columbian cemetery and hilltop village in Arequipa, on a named hill in Camaná Province. One of the later Andean burial sites, reflecting traditions of the region after Inca contact.', 'teaser-card-s029-rollback:a3b55317-bae1-42b5-9c64-477749bdc2d5:card_description', 'rollback of teaser-card-s029: card_description ''Pre-Columbian cemetery and hilltop village in Arequipa, on a named hill in Camaná Province. One of the later Andean burial sites, reflecting traditions of the region after Inca contact.'' restored on Huamboy', '7f826c9cbd0389199fb3ddd4f45825be3c93d258e185529cebb808b95d1af049|785fd27974180b6aeb15405bb78f64f639abc0c28155740b09b53ddabd9f9a8b|785fd27974180b6aeb15405bb78f64f639abc0c28155740b09b53ddabd9f9a8b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a hill in the Arequipa Region lie the cemeteries and village of Huamboy, a name possibly from the Quechua wamp''uy, meaning to navigate, to sail, to travel by boat."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on a hill [S1]; it is in the Arequipa Region [S2]; it has cemeteries and a village [S1]; the name Huamboy is possibly from the Quechua wamp''uy [S1]; wamp''uy means to navigate, to sail, to travel by boat [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Huamboy is an archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Huamboy]; The site comprises cemeteries and a village [SUPPORTED: https://en.wikipedia.org/wiki/Huamboy]; It is located on a hill [SUPPORTED: https://en.wikipedia.org/wiki/Huamboy]; It lies in the Arequipa Region of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Huamboy]; The name possibly comes from the Quechua wamp''uy [SUPPORTED: https://en.wikipedia.org/wiki/Huamboy]; Quechua wamp''uy means to navigate, to sail, to travel by boat [SUPPORTED: https://en.wikipedia.org/wiki/Huamboy]"}]'::jsonb),
    ('a3e4eae7-5dbb-4e10-be96-065f54ce7e02'::uuid, 'card_description', 'East of Brockley in North Somerset, Taps Combe Camp, also known as Chelvey Batch Settlement, is an Iron Age hill fort shaped like a D, approximately 50 metres by 50 metres wide.', 'Iron Age hill fort shaped like a letter D, about 50 x 50 metres, in North Somerset. Also known as Chelvey Batch Settlement, Taps Combe Camp sits 2.9 km from Brockley — a compact Iron Age enclosure.', 'teaser-card-s029-rollback:a3e4eae7-5dbb-4e10-be96-065f54ce7e02:card_description', 'rollback of teaser-card-s029: card_description ''Iron Age hill fort shaped like a letter D, about 50 x 50 metres, in North Somerset. Also known as Chelvey Batch Settlement, Taps Combe Camp sits 2.9 km from Brockley — a compact Iron Age enclosure.'' restored on Taps Combe Camp', '093128daceb1fe44f35f72d8fac3d7e47634aa38058316658594c6a315bfef41|c0bb7ab2fef3ca47c4f902f9061a57871cd235291aeb8d93a18582c23cdfa5d6|c0bb7ab2fef3ca47c4f902f9061a57871cd235291aeb8d93a18582c23cdfa5d6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-018", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "East of Brockley in North Somerset, Taps Combe Camp, also known as Chelvey Batch Settlement, is an Iron Age hill fort shaped like a D, approximately 50 metres by 50 metres wide."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-018 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Taps Combe Camp lies east of Brockley [S2]; it is in North Somerset [S1]; it is also known as Chelvey Batch Settlement [S1]; it is an Iron Age hill fort [S1]; it is shaped like a D [S3]; it is approximately 50 metres by 50 metres wide [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Taps Combe Camp is a hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Taps_Combe_Camp]; It dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Taps_Combe_Camp]; It lies in North Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Taps_Combe_Camp]; It is also known as Chelvey Batch Settlement [SUPPORTED: https://en.wikipedia.org/wiki/Taps_Combe_Camp]; It lies east of Brockley [SUPPORTED: https://en.wikipedia.org/wiki/Taps_Combe_Camp]; It is shaped like a D [SUPPORTED: https://en.wikipedia.org/wiki/Taps_Combe_Camp]; It measures approximately 50 metres by 50 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Taps_Combe_Camp]"}]'::jsonb),
    ('a4856c44-4e78-4a45-b618-d558b763942d'::uuid, 'card_description', 'Hieroglyphs show Arroyo de Piedra and Tamarindito once formed an independent polity, before Tikal established Dos Pilas. Arroyo de Piedra appears to have been abandoned in the 8th century.', 'While initially a center of some regional importance, with the rise of Dos Pilas, Arroyo de Piedra was subsumed as a secondary center within the Petexbatun region.', 'teaser-card-s029-rollback:a4856c44-4e78-4a45-b618-d558b763942d:card_description', 'rollback of teaser-card-s029: card_description ''While initially a center of some regional importance, with the rise of Dos Pilas, Arroyo de Piedra was subsumed as a secondary center within the Petexbatun region.'' restored on Arroyo de Piedra', '02b0f266e16678e3f35148f3c56e2226e43ce36c75284d7e27a3781412b67c1b|a4ebfb56f8ce300737e4801b2532bda79546d7c40550ed2050582ee5d3b145cf|a4ebfb56f8ce300737e4801b2532bda79546d7c40550ed2050582ee5d3b145cf', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-001", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Hieroglyphs show Arroyo de Piedra and Tamarindito once formed an independent polity, before Tikal established Dos Pilas. Arroyo de Piedra appears to have been abandoned in the 8th century."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "hieroglyphic data shows that Arroyo de Piedra and Tamarindito formed a polity together [S5]; the polity was independent [S5]; the polity existed before Dos Pilas was established [S5]; Tikal established Dos Pilas [S5]; Arroyo de Piedra appears to have been abandoned [S6]; the abandonment was in the 8th century [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-054 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Arroyo de Piedra is a Maya archaeological site in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Arroyo_de_Piedra]; Arroyo de Piedra lies close to Dos Pilas and Tamarindito [SUPPORTED: https://en.wikipedia.org/wiki/Arroyo_de_Piedra]; Hieroglyphs show that Arroyo de Piedra and Tamarindito together formed a polity [SUPPORTED: https://en.wikipedia.org/wiki/Arroyo_de_Piedra]; That polity was independent [SUPPORTED: https://en.wikipedia.org/wiki/Arroyo_de_Piedra]; The independent polity existed before Dos Pilas was established [SUPPORTED: https://en.wikipedia.org/wiki/Arroyo_de_Piedra]; Tikal established Dos Pilas [SUPPORTED: https://en.wikipedia.org/wiki/Arroyo_de_Piedra]; Arroyo de Piedra appears to have been abandoned in the 8th century [SUPPORTED: https://en.wikipedia.org/wiki/Arroyo_de_Piedra]"}]'::jsonb),
    ('a5009e55-a34f-4568-9d9b-1d86d1082a9b'::uuid, 'card_description', 'Across a 270-metre stretch of water from Flores, on a peninsula in Lake Petén Itzá, lies Tayasal: a Maya city of palaces, pyramid-temples, an acropolis, defensive walls and a cenote.', '400 BC–1539 AD Maya city with plazas, palaces, pyramid temples, an acropolis, defensive walls, and a cenote. Fifty burials and twelve caches recovered — Tayasal endured from Preclassic to Postclassic.', 'teaser-card-s029-rollback:a5009e55-a34f-4568-9d9b-1d86d1082a9b:card_description', 'rollback of teaser-card-s029: card_description ''400 BC–1539 AD Maya city with plazas, palaces, pyramid temples, an acropolis, defensive walls, and a cenote. Fifty burials and twelve caches recovered — Tayasal endured from Preclassic to Postclassic.'' restored on Tayasal', 'd00c4aca70a9d47d3c4ba166733cb7eb6b257028c910e4cd74ecb76dda4f6efb|97e1030afdc2d71b2d57580f6b6a7fc9a01746a89610b090925b858cd33160f6|97e1030afdc2d71b2d57580f6b6a7fc9a01746a89610b090925b858cd33160f6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Across a 270-metre stretch of water from Flores, on a peninsula in Lake Petén Itzá, lies Tayasal: a Maya city of palaces, pyramid-temples, an acropolis, defensive walls and a cenote."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tayasal lies across a 270-metre stretch of water from Flores [S4]; it lies on a peninsula in Lake Petén Itzá [S4]; Tayasal is a Maya city [S1, S2]; the city had palaces [S7]; the city had pyramid-temples [S7]; the city had an acropolis [S7]; the city had defensive walls [S7]; the city had a cenote [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tayasal is a Maya city (an archaeological site) in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; Tayasal lies on a peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; The peninsula is in Lake Petén Itzá [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; Tayasal lies across from Flores [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; The stretch of water between Tayasal and Flores is 270 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; The city had palaces [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; The city had pyramid-temples [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; The city had an acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; The city had defensive walls [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]; The city had a cenote [SUPPORTED: https://en.wikipedia.org/wiki/Tayasal_(archaeological_site)]"}]'::jsonb),
    ('a6492846-5963-4307-8ffc-ea06bb554b1e'::uuid, 'card_description', 'In County Monaghan, near the Cavan border, Lisnadarragh Wedge Tomb is walled by 20 orthostats that shrink from south-west to north-east, the largest, at the entrance, 1.8 metres high.', 'Lisnadarragh Wedge Tomb is a prehistoric site, a wedge tomb about 16 kilometres west of Carrickmacross, in County Monaghan near the border with County Cavan.', 'teaser-card-s029-rollback:a6492846-5963-4307-8ffc-ea06bb554b1e:card_description', 'rollback of teaser-card-s029: card_description ''Lisnadarragh Wedge Tomb is a prehistoric site, a wedge tomb about 16 kilometres west of Carrickmacross, in County Monaghan near the border with County Cavan.'' restored on Lisnadarragh Wedge Tomb', 'a4db709b38d22d27c2736680c04bcd3b94c01623a80b2a790c0f25826be8a19d|b85a57e498b1ad92c1dc071e79b0f43c0830f3df8c8a2804c7ca2fe240130253|b85a57e498b1ad92c1dc071e79b0f43c0830f3df8c8a2804c7ca2fe240130253', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In County Monaghan, near the Cavan border, Lisnadarragh Wedge Tomb is walled by 20 orthostats that shrink from south-west to north-east, the largest, at the entrance, 1.8 metres high."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the tomb is in County Monaghan [S1]; it is near the Cavan border [S1]; the sides of the tomb are defined by 20 orthostats [S3]; the orthostats decrease in size from south-west to north-east [S3]; the largest orthostat is at the entrance [S3]; the largest orthostat is 1.8 metres high [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Lisnadarragh Wedge Tomb is a wedge tomb [SUPPORTED: https://en.wikipedia.org/wiki/Lisnadarragh_Wedge_Tomb]; It is in County Monaghan, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Lisnadarragh_Wedge_Tomb]; It lies near the border with County Cavan [SUPPORTED: https://en.wikipedia.org/wiki/Lisnadarragh_Wedge_Tomb]; The sides of the tomb are defined (walled) by 20 orthostats [SUPPORTED: https://en.wikipedia.org/wiki/Lisnadarragh_Wedge_Tomb]; The orthostats shrink (decrease in size) from south-west to north-east [SUPPORTED: https://en.wikipedia.org/wiki/Lisnadarragh_Wedge_Tomb]; The largest orthostat is at the entrance [SUPPORTED: https://en.wikipedia.org/wiki/Lisnadarragh_Wedge_Tomb]; The largest orthostat is 1.8 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Lisnadarragh_Wedge_Tomb]"}]'::jsonb),
    ('a6712eba-ba7a-4047-8462-0f4ae9343373'::uuid, 'card_description', 'In 1951, workmen digging at a nearby tholos tomb stumbled on Grave Circle B, a royal cemetery at Mycenae whose women wore bands of gold, and where a death mask of electrum was unearthed.', 'An earlier royal cemetery than Grave Circle A, dating to the 17th–16th century BC. Its 28-metre-diameter enclosure held both shaft graves and simple pit burials side by side.', 'teaser-card-s029-rollback:a6712eba-ba7a-4047-8462-0f4ae9343373:card_description', 'rollback of teaser-card-s029: card_description ''An earlier royal cemetery than Grave Circle A, dating to the 17th–16th century BC. Its 28-metre-diameter enclosure held both shaft graves and simple pit burials side by side.'' restored on Grave Circle B, Mycenae', 'f0a5cdde1749fc630a80374f3d75343000f424bdb8f62c55802c282703060ca9|6d0c5f80c19bd1d8966f61d604eb860c1ff11a3d5e984463c68372a8fdde4a44|6d0c5f80c19bd1d8966f61d604eb860c1ff11a3d5e984463c68372a8fdde4a44', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In 1951, workmen digging at a nearby tholos tomb stumbled on Grave Circle B, a royal cemetery at Mycenae whose women wore bands of gold, and where a death mask of electrum was unearthed."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the burial complex was found in 1951 [S7]; it was found by accident by workmen [S7]; the workmen were digging at a nearby tholos tomb [S7]; Grave Circle B is a royal cemetery [S1]; it is at Mycenae [S1]; the women in the graves wore bands of gold [S5]; a death mask of electrum was unearthed there [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Grave Circle B is a royal cemetery [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_B,_Mycenae]; Grave Circle B is at Mycenae [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_B,_Mycenae]; It was discovered in 1951 [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_B,_Mycenae]; Workmen digging stumbled on it (discovered by accident) [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_B,_Mycenae]; The workmen were digging at a nearby tholos tomb [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_B,_Mycenae]; The women buried there wore bands of gold [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Grave_Circle_B,_Mycenae]; A death mask of electrum was unearthed there [SUPPORTED: https://en.wikipedia.org/wiki/Grave_Circle_B,_Mycenae]"}]'::jsonb),
    ('a6f8838d-ff92-4aef-9723-5ce4b3605fae'::uuid, 'card_description', 'Thracian Tomb Griffins: the lower leaves of the pediment''s end semi-palmettes look like griffin heads. Opposite the circular chamber''s entrance, a ritual stone bed; before it, gold paws.', 'A 5th-century BC Thracian tomb whose pediment ends resemble griffin heads. Decorative plastic columns on the facade are a uniquely Thracian feature.', 'teaser-card-s029-rollback:a6f8838d-ff92-4aef-9723-5ce4b3605fae:card_description', 'rollback of teaser-card-s029: card_description ''A 5th-century BC Thracian tomb whose pediment ends resemble griffin heads. Decorative plastic columns on the facade are a uniquely Thracian feature.'' restored on Thracian Tomb Griffins', '10bde65f1140752f4ddeb20a465b8c9355774dfae1a42af3fb9ceabe06a16587|e8a4f753447c2177713f33815452be872384b4bd3966d3f659f134251fec53a2|e8a4f753447c2177713f33815452be872384b4bd3966d3f659f134251fec53a2', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Thracian Tomb Griffins: the lower leaves of the pediment''s end semi-palmettes look like griffin heads. Opposite the circular chamber''s entrance, a ritual stone bed; before it, gold paws."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the lower leaves of the semi-palmettes at the pediment''s ends look like griffin heads [S2]; a ritual stone bed stands opposite the entrance of the circular chamber [S4]; gold paws were found in front of the bed [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Thracian Tomb Griffins is a Thracian tomb in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Thracian_tomb_Griffins]; The lower leaves of the pediment''s end semi-palmettes look like griffin heads [SUPPORTED: https://en.wikipedia.org/wiki/Thracian_tomb_Griffins]; The tomb has a circular chamber [SUPPORTED: https://en.wikipedia.org/wiki/Thracian_tomb_Griffins]; Opposite the circular chamber''s entrance stands a ritual stone bed [SUPPORTED: https://en.wikipedia.org/wiki/Thracian_tomb_Griffins]; Gold paws were found in front of the bed [SUPPORTED: https://en.wikipedia.org/wiki/Thracian_tomb_Griffins]"}]'::jsonb),
    ('a705abb0-2fda-42d2-9eaa-dee12b190ce4'::uuid, 'card_description', 'On Fyfield Hill, two standing stones, two fallen stones and a capstone believed to weigh 17 tons are all that remain of a long mound''s entrance: The Devil''s Den, a Neolithic burial chamber.', 'A Neolithic dolmen with a 15.4-tonne capstone bearing cup markings, last remnant of a 70-metre-long burial mound. The fallen stones were reassembled in 1921 to produce what you see today.', 'teaser-card-s029-rollback:a705abb0-2fda-42d2-9eaa-dee12b190ce4:card_description', 'rollback of teaser-card-s029: card_description ''A Neolithic dolmen with a 15.4-tonne capstone bearing cup markings, last remnant of a 70-metre-long burial mound. The fallen stones were reassembled in 1921 to produce what you see today.'' restored on The Devil''s Den', '07fcfc5e06faf779c52462d6ec7064735bcfd914acfaa2001c8ce9b03a85bfa6|bfa9ababad99331810384f0c30151ea1fe1c96633ce50e84fa4d03552c232482|bfa9ababad99331810384f0c30151ea1fe1c96633ce50e84fa4d03552c232482', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Fyfield Hill, two standing stones, two fallen stones and a capstone believed to weigh 17 tons are all that remain of a long mound''s entrance: The Devil''s Den, a Neolithic burial chamber."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is on Fyfield Hill [S1]; two standing stones, two fallen stones and a capstone remain [S3]; the capstone is believed to weigh 17 tons [S4]; these stones are all that remain of the entrance to a long mound [S3]; the Devil''s Den is a burial chamber [S1]; the burial chamber is Neolithic [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-055 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Devil''s Den is a burial chamber (dolmen) [SUPPORTED: https://en.wikipedia.org/wiki/The_Devil%27s_Den]; It stands on Fyfield Hill [SUPPORTED: https://en.wikipedia.org/wiki/The_Devil%27s_Den]; It is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/The_Devil%27s_Den]; Two standing stones remain [SUPPORTED: https://en.wikipedia.org/wiki/The_Devil%27s_Den]; Two fallen stones remain [SUPPORTED: https://en.wikipedia.org/wiki/The_Devil%27s_Den]; A capstone remains [SUPPORTED: https://en.wikipedia.org/wiki/The_Devil%27s_Den]; These stones are all that remain of the entrance of a long mound [SUPPORTED: https://en.wikipedia.org/wiki/The_Devil%27s_Den]; The capstone is believed to weigh 17 tons [SUPPORTED: https://en.wikipedia.org/wiki/The_Devil%27s_Den]"}]'::jsonb),
    ('a7bb511e-92d8-4199-aa70-425d4e88b4cc'::uuid, 'card_description', 'Near Pirovac, an unknown immigrant who came after the Batonian uprising built a Roman villa: the Ivinj Archaeological Site, where oil was produced and a basilica rose in the 5th century.', 'A Roman villa complex near Pirovac in Dalmatia with basilica, baptistery, and the Church of Saint Martin. The villa dates to the early centuries of Roman settlement on the Adriatic coast.', 'teaser-card-s029-rollback:a7bb511e-92d8-4199-aa70-425d4e88b4cc:card_description', 'rollback of teaser-card-s029: card_description ''A Roman villa complex near Pirovac in Dalmatia with basilica, baptistery, and the Church of Saint Martin. The villa dates to the early centuries of Roman settlement on the Adriatic coast.'' restored on Ivinj Archaeological Site', '0035b70f0876b4a67918cb3d583d441e15663d14325264fc3b182c54dcf4c603|c8392b4339130e6ac8dfa4d68608351c72ab363ca3735ebf16989d8ee44c6152|c8392b4339130e6ac8dfa4d68608351c72ab363ca3735ebf16989d8ee44c6152', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Pirovac, an unknown immigrant who came after the Batonian uprising built a Roman villa: the Ivinj Archaeological Site, where oil was produced and a basilica rose in the 5th century."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site is near Pirovac [S1]; the villa was built by an immigrant whose identity is unknown [S3]; the immigrant came after the Batonian uprising [S3]; the villa was a Roman villa [S2]; oil was produced at the villa [S6]; a basilica was added in the 5th century [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Ivinj Archaeological Site is an archaeological site near Pirovac (Dalmatia, Croatia) [SUPPORTED: https://en.wikipedia.org/wiki/Ivinj_archeological_site]; The site includes a Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Ivinj_archeological_site]; The Roman villa was built by an immigrant (someone who moved to Ivinj) [SUPPORTED: https://en.wikipedia.org/wiki/Ivinj_archeological_site]; The immigrant who built the villa is unknown (unnamed) [SUPPORTED: https://en.wikipedia.org/wiki/Ivinj_archeological_site]; The immigrant came after the Batonian uprising [SUPPORTED: https://en.wikipedia.org/wiki/Ivinj_archeological_site]; Oil was produced at the villa [SUPPORTED: https://en.wikipedia.org/wiki/Ivinj_archeological_site]; A basilica rose (was added to the villa) in the 5th century [SUPPORTED: https://en.wikipedia.org/wiki/Ivinj_archeological_site]"}]'::jsonb),
    ('a7e1060c-e0e3-4fe0-a4ff-4737611a2203'::uuid, 'card_description', 'In the village of Marvinci, Isar keeps the remnants of a temple and a stadium designed in the ancient Roman style, and, say Macedonian archaeologists, roughly well over 200 graves.', 'The archeological site contains remnants of a temple and stadium, designed according to the ancient Roman style.', 'teaser-card-s029-rollback:a7e1060c-e0e3-4fe0-a4ff-4737611a2203:card_description', 'rollback of teaser-card-s029: card_description ''The archeological site contains remnants of a temple and stadium, designed according to the ancient Roman style.'' restored on Isar, Marvinci', '9668cb344d397b8e7057c53ce82ded8602d59c0c82ef991ea984efa40905c1d7|9af58b8f8a3e68dd38304318510dee53c69ee542f4b3c66f0118358287ded58d|9af58b8f8a3e68dd38304318510dee53c69ee542f4b3c66f0118358287ded58d', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the village of Marvinci, Isar keeps the remnants of a temple and a stadium designed in the ancient Roman style, and, say Macedonian archaeologists, roughly well over 200 graves."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Isar is in the village of Marvinci [S1]; the site contains remnants of a temple [S5]; the site contains remnants of a stadium [S5]; the temple and stadium were designed in the ancient Roman style [S5]; according to Macedonian archaeologists the site has roughly well over 200 graves [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Isar is an archaeological site in the village of Marvinci (North Macedonia) [SUPPORTED: https://en.wikipedia.org/wiki/Isar,_Marvinci]; The site keeps the remnants of a temple [SUPPORTED: https://en.wikipedia.org/wiki/Isar,_Marvinci]; The site keeps the remnants of a stadium [SUPPORTED: https://en.wikipedia.org/wiki/Isar,_Marvinci]; The temple and stadium were designed in the ancient Roman style [SUPPORTED: https://en.wikipedia.org/wiki/Isar,_Marvinci]; Macedonian archaeologists say the site has graves (the attribution of the grave count to Macedonian archaeologists) [SUPPORTED: https://en.wikipedia.org/wiki/Isar,_Marvinci]; The site has roughly well over 200 graves [SUPPORTED: https://en.wikipedia.org/wiki/Isar,_Marvinci]"}]'::jsonb),
    ('a7e88abd-9d65-4a68-bec6-d9d527f3c172'::uuid, 'card_description', 'A prehistoric farming village grew into an urban Dvaravati centre, among the earliest in Thailand to make contact with India: Si Thep Historical Park, where wheels of the law were recorded.', NULL, 'teaser-card-s029-rollback:a7e88abd-9d65-4a68-bec6-d9d527f3c172:card_description', 'rollback of teaser-card-s029: card_description None restored on Si Thep Historical Park', '62bfd2c027fec48351225803ac779ebc14508ec584733e88ceb2ff4e122b4901|89b4fb84bba3a13404d5e99fe4913adec4794563efbf8c6aff7806b601531eba|89b4fb84bba3a13404d5e99fe4913adec4794563efbf8c6aff7806b601531eba', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "A prehistoric farming village grew into an urban Dvaravati centre, among the earliest in Thailand to make contact with India: Si Thep Historical Park, where wheels of the law were recorded."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Si Thep grew from a prehistoric farming village [S4]; it became an urban Dvaravati centre [S5]; it was among the earliest communities in Thailand to make contact with India [S5]; wheels of the law are recorded from Si Thep [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Si Thep Historical Park is an archaeological site in Thailand [SUPPORTED: https://en.wikipedia.org/wiki/Si_Thep_Historical_Park]; Si Thep developed from a prehistoric farming village [SUPPORTED: https://en.wikipedia.org/wiki/Si_Thep_Historical_Park]; Si Thep became an urban Dvaravati centre [SUPPORTED: https://en.wikipedia.org/wiki/Si_Thep_Historical_Park]; Si Thep was among the earliest communities in Thailand to make contact with India [SUPPORTED: https://en.wikipedia.org/wiki/Si_Thep_Historical_Park]; Wheels of the law were recorded at Si Thep [SUPPORTED: https://en.wikipedia.org/wiki/Si_Thep_Historical_Park]"}]'::jsonb),
    ('a80f19c6-ffde-4350-b122-095a4ef5c97a'::uuid, 'card_description', 'Near Tarquinia, two bulls painted on one of its frescoes gave the Tomb of the Bulls its name, and its explicit sexual scenes remain relatively rare examples in Etruscan art.', 'The oldest elaborately painted tomb in the Monterozzi necropolis, dating to ~530 BC. Its frescoes blend Etruscan and Ionian Greek styles in vivid mythological scenes.', 'teaser-card-s029-rollback:a80f19c6-ffde-4350-b122-095a4ef5c97a:card_description', 'rollback of teaser-card-s029: card_description ''The oldest elaborately painted tomb in the Monterozzi necropolis, dating to ~530 BC. Its frescoes blend Etruscan and Ionian Greek styles in vivid mythological scenes.'' restored on Tomb of the Bulls - Necropolis of Monterozzi', 'd1d8ffaa9d3face1a6b088843af8a4b325607904bbc5edcf44c04f68e909d97d|65986e723bd0ccf220697a9b21547826ff11de189701bd20cee6bf888075106e|65986e723bd0ccf220697a9b21547826ff11de189701bd20cee6bf888075106e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near Tarquinia, two bulls painted on one of its frescoes gave the Tomb of the Bulls its name, and its explicit sexual scenes remain relatively rare examples in Etruscan art."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the tomb is near Tarquinia [S1]; two bulls appear on one of its frescoes [S4]; the tomb is named after those two bulls [S4]; its paintings contain explicit sexual scenes [S6]; they are relatively rare examples of explicit sexual scenes in Etruscan art [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-056 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Tomb of the Bulls is a tomb in the Necropolis of Monterozzi near Tarquinia [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Bulls]; The tomb is named after two bulls [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Bulls]; The two bulls are painted on one of the tomb''s frescoes [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Bulls]; The tomb''s frescoes contain explicit sexual scenes [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Bulls]; Such explicit sexual scenes are relatively rare in Etruscan art [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Bulls]"}]'::jsonb),
    ('a965d140-d212-45f5-a269-1945fc8432b3'::uuid, 'card_description', 'Once a caravan station guarding a western branch of the Incense Road, the Archaeological Site Nitzana became a Nabataean city in the Negev, its people Christianized and Romanized.', 'Onomastics show that the largely Nabataean inhabitants of the city had become Christianized and Romanized in the early centuries CE.', 'teaser-card-s029-rollback:a965d140-d212-45f5-a269-1945fc8432b3:card_description', 'rollback of teaser-card-s029: card_description ''Onomastics show that the largely Nabataean inhabitants of the city had become Christianized and Romanized in the early centuries CE.'' restored on The Archaeological Site Nitzana', 'f56c27acc671b8d40b6c604221961b88883accf35999d07bbfdfc1a174a74c0c|68657cb8d7c365fb5f1e8683452829ce22dd53d10ed23c25de698d43508942a6|68657cb8d7c365fb5f1e8683452829ce22dd53d10ed23c25de698d43508942a6', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Once a caravan station guarding a western branch of the Incense Road, the Archaeological Site Nitzana became a Nabataean city in the Negev, its people Christianized and Romanized."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "once a caravan station [S2]; guarding a western branch of the Incense Road [S2]; became a Nabataean city [S1, S2]; in the Negev [S1]; its people Christianized [S4]; its people Romanized [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Nitzana (Nessana) is an ancient Nabataean city in the Negev, Israel [SUPPORTED: https://en.wikipedia.org/wiki/Nessana]; It began as a caravan station [SUPPORTED: https://en.wikipedia.org/wiki/Nessana]; The caravan station protected a western branch of the Incense Road [SUPPORTED: https://en.wikipedia.org/wiki/Nessana]; It lies in the Negev [SUPPORTED: https://en.wikipedia.org/wiki/Nessana]; Its people were Christianized [SUPPORTED: https://en.wikipedia.org/wiki/Nessana]; Its people were Romanized [SUPPORTED: https://en.wikipedia.org/wiki/Nessana]"}]'::jsonb),
    ('a9c5d1bf-b6d0-4486-a507-8dddfdc57a02'::uuid, 'card_description', 'Farm work in Nakhchivan, researchers say, uncovered the Ağbulaq Necropolis, whose graves are large jars. Two were excavated, yielding agate and glass beads, bronze pins, rings and bells.', 'The Ağbulaq necropolis is an archeological site of antiquity located in the territory of Shahbuz district of Nakhchivan.', 'teaser-card-s029-rollback:a9c5d1bf-b6d0-4486-a507-8dddfdc57a02:card_description', 'rollback of teaser-card-s029: card_description ''The Ağbulaq necropolis is an archeological site of antiquity located in the territory of Shahbuz district of Nakhchivan.'' restored on Ağbulaq Necropolis', 'c298a60da74703677f6cd83228fc0aff2e1c8d694d6c1cf916a50157fa585f8a|ec2b90c030ed349ab451fc3344e8c9617574bd6401754df9e6df4fb4e50ad9c5|ec2b90c030ed349ab451fc3344e8c9617574bd6401754df9e6df4fb4e50ad9c5', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Farm work in Nakhchivan, researchers say, uncovered the Ağbulaq Necropolis, whose graves are large jars. Two were excavated, yielding agate and glass beads, bronze pins, rings and bells."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "according to the researchers the necropolis was discovered during agricultural work [S4]; the necropolis is in Nakhchivan [S1]; the graves are large jars [S3]; two graves were excavated [S5]; agate and glass beads were obtained [S6]; bronze pins, rings and bells were obtained [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Ağbulaq Necropolis is a necropolis (an archaeological site of antiquity) [SUPPORTED: https://en.wikipedia.org/wiki/A%C4%9Fbulaq_necropolis]; The necropolis is in Nakhchivan [SUPPORTED: https://en.wikipedia.org/wiki/A%C4%9Fbulaq_necropolis]; Researchers say the necropolis was uncovered during farm work [SUPPORTED: https://en.wikipedia.org/wiki/A%C4%9Fbulaq_necropolis]; The graves of the necropolis are large jars [SUPPORTED: https://en.wikipedia.org/wiki/A%C4%9Fbulaq_necropolis]; Two graves (jars) were excavated [SUPPORTED: https://en.wikipedia.org/wiki/A%C4%9Fbulaq_necropolis]; The excavation yielded agate and glass beads [SUPPORTED: https://en.wikipedia.org/wiki/A%C4%9Fbulaq_necropolis]; The excavation yielded bronze pins, rings and bells [SUPPORTED: https://en.wikipedia.org/wiki/A%C4%9Fbulaq_necropolis]"}]'::jsonb),
    ('a9f3224a-798f-43ab-b3ea-41be12a41074'::uuid, 'card_description', 'On Gotland''s western coast, the Ajvide Settlement holds a burial ground of some 80 graves, and beside it dark soil mixed with pottery and bone. Around 2900 BC, the sea encroached.', 'Pitted Ware culture settlement on Gotland, active 3100–2700 BC. Around 2900 BC, the sea rose and flooded part of the site — Mesolithic and Bronze Age layers survive beneath the ground.', 'teaser-card-s029-rollback:a9f3224a-798f-43ab-b3ea-41be12a41074:card_description', 'rollback of teaser-card-s029: card_description ''Pitted Ware culture settlement on Gotland, active 3100–2700 BC. Around 2900 BC, the sea rose and flooded part of the site — Mesolithic and Bronze Age layers survive beneath the ground.'' restored on Ajvide Settlement', 'e3f2af09d126221bc35c0a94bc13877393ccac7449ede8f73f1c64918f4e2229|6a8b8b87c8298f90d4fa644f9bdef5b47728878a56a7e78b2a4ced02de46b04c|6a8b8b87c8298f90d4fa644f9bdef5b47728878a56a7e78b2a4ced02de46b04c', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Gotland''s western coast, the Ajvide Settlement holds a burial ground of some 80 graves, and beside it dark soil mixed with pottery and bone. Around 2900 BC, the sea encroached."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the settlement is on the western coast of Gotland [S1]; it holds a burial ground of some 80 graves [S6]; beside the burial ground lies dark soil [S8]; the dark soil is mixed with pottery and bone [S8]; around 2900 BC the sea advanced over the site (marine transgression) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Ajvide Settlement is a settlement site [SUPPORTED: https://en.wikipedia.org/wiki/Ajvide_Settlement]; The Ajvide Settlement is on the western coast of Gotland, Sweden [SUPPORTED: https://en.wikipedia.org/wiki/Ajvide_Settlement]; The site holds a burial ground [SUPPORTED: https://en.wikipedia.org/wiki/Ajvide_Settlement]; The burial ground has some 80 graves [SUPPORTED: https://en.wikipedia.org/wiki/Ajvide_Settlement]; Beside the burial ground lies an area of dark soil [SUPPORTED: https://en.wikipedia.org/wiki/Ajvide_Settlement]; The dark soil is mixed with pottery and bone [SUPPORTED: https://en.wikipedia.org/wiki/Ajvide_Settlement]; Around 2900 BC the sea encroached on the site [SUPPORTED: https://en.wikipedia.org/wiki/Ajvide_Settlement]"}]'::jsonb),
    ('aad935a4-efbd-4133-94ac-ce7d12789e9c'::uuid, 'card_description', 'In 79 AD Vesuvius buried Torre del Greco, probably a suburb of Herculaneum, under ash. Later came the villages of Sora and Calastro, until Belisarius moved their people to Naples in 535.', NULL, 'teaser-card-s029-rollback:aad935a4-efbd-4133-94ac-ce7d12789e9c:card_description', 'rollback of teaser-card-s029: card_description None restored on Torre del Greco', '5202259c6ef8b5857c27a2e880738c3fe5c188273dd36c9b658270836b16f01a|5f79d077108518165e7bce28dcd167674763fbf652ad23734d84c76b496bbe06|5f79d077108518165e7bce28dcd167674763fbf652ad23734d84c76b496bbe06', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In 79 AD Vesuvius buried Torre del Greco, probably a suburb of Herculaneum, under ash. Later came the villages of Sora and Calastro, until Belisarius moved their people to Naples in 535."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "in 79 AD Vesuvius buried the area under ash [S2]; Torre del Greco was probably a suburb of Herculaneum in Roman times [S1]; the villages of Sora and Calastro were established later [S3]; Belisarius moved their inhabitants to Naples in 535 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Torre del Greco is a place (today a comune) near Naples, whose Roman-era area was probably a suburb of Herculaneum [SUPPORTED: https://en.wikipedia.org/wiki/Torre_del_Greco]; In 79 AD Vesuvius buried Torre del Greco under ash [SUPPORTED: https://en.wikipedia.org/wiki/Torre_del_Greco]; Later the villages of Sora and Calastro were established there [SUPPORTED: https://en.wikipedia.org/wiki/Torre_del_Greco]; Belisarius moved the people of Sora and Calastro to Naples in 535 [SUPPORTED: https://en.wikipedia.org/wiki/Torre_del_Greco]"}]'::jsonb),
    ('ab28cd35-6f8c-4789-80df-a123993db0b0'::uuid, 'card_description', 'On a steep cliff on Hisingen, red ochre bonded with the rock still shows ships, fish, a large deer and wave-like patterns: the Tumlehed Rock Painting, the southernmost recorded in Sweden.', 'Dating 4200–2500 BC, this pictograph on Hisingen island is the southernmost rock painting in the country — and among the rarest, with fewer than a handful known from the western provinces.', 'teaser-card-s029-rollback:ab28cd35-6f8c-4789-80df-a123993db0b0:card_description', 'rollback of teaser-card-s029: card_description ''Dating 4200–2500 BC, this pictograph on Hisingen island is the southernmost rock painting in the country — and among the rarest, with fewer than a handful known from the western provinces.'' restored on Tumlehed Rock Painting', '08128d73b929a1971d356164eada0b177cbcb39ce89b149a60a673ee5530e79f|83c5bdbbfbb16774ef2f8739e665a6991b1605f28a8eac3fd5f64e73b93cba97|83c5bdbbfbb16774ef2f8739e665a6991b1605f28a8eac3fd5f64e73b93cba97', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-019", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a steep cliff on Hisingen, red ochre bonded with the rock still shows ships, fish, a large deer and wave-like patterns: the Tumlehed Rock Painting, the southernmost recorded in Sweden."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-019 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the painting is on a steep cliff [S4]; it is on Hisingen [S1]; the painting was made with red ochre bonded with the rock and has survived [S5]; it depicts ships, fish, a large deer and wave-like patterns [S4]; it is the southernmost recorded rock painting in Sweden [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Tumlehed Rock Painting is a prehistoric rock painting (pictograph) site on the island of Hisingen, Sweden [SUPPORTED: https://en.wikipedia.org/wiki/Tumlehed_rock_painting]; The painting is on a steep cliff [SUPPORTED: https://en.wikipedia.org/wiki/Tumlehed_rock_painting]; It shows ships, fish, a large deer and wave-like patterns [SUPPORTED: https://en.wikipedia.org/wiki/Tumlehed_rock_painting]; It is made of red ochre bonded with the rock, which has survived to the present [SUPPORTED: https://en.wikipedia.org/wiki/Tumlehed_rock_painting]; It is the southernmost recorded rock painting in Sweden [SUPPORTED: https://en.wikipedia.org/wiki/Tumlehed_rock_painting]"}]'::jsonb),
    ('ac76d3ef-82df-4fcc-8da4-f4fc7f59716e'::uuid, 'card_description', 'In the Couze valley of the Périgord lies Combe-Capelle, whose Homo sapiens fossil, found in 1909 and sold to a Berlin museum in 1910, proved to be 9,500 years old.', 'A Paleolithic site in the Couze valley. A famous human fossil from here was long considered Upper Paleolithic but later redating sparked controversy.', 'teaser-card-s029-rollback:ac76d3ef-82df-4fcc-8da4-f4fc7f59716e:card_description', 'rollback of teaser-card-s029: card_description ''A Paleolithic site in the Couze valley. A famous human fossil from here was long considered Upper Paleolithic but later redating sparked controversy.'' restored on Combe-Capelle', '4578180a14b6452a67bef9c4e168835ccd75a6ff7f483f226c597fbbfa203184|dc640c0c979595833eab5884117f1e58ef99a70de7bbc34beef4dc40870c10fd|dc640c0c979595833eab5884117f1e58ef99a70de7bbc34beef4dc40870c10fd', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Couze valley of the Périgord lies Combe-Capelle, whose Homo sapiens fossil, found in 1909 and sold to a Berlin museum in 1910, proved to be 9,500 years old."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies in the Couze valley [S1]; the site lies in the Périgord region [S1]; a Homo sapiens fossil comes from Combe-Capelle [S3]; the fossil was found in 1909 [S3]; the fossil was sold to a museum in Berlin [S3]; the sale took place in 1910 [S3]; the fossil was found to be 9,500 years old [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-057 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Combe-Capelle is a Paleolithic and Epipaleolithic (prehistoric) site [SUPPORTED: https://en.wikipedia.org/wiki/Combe-Capelle]; Combe-Capelle lies in the Couze valley [SUPPORTED: https://en.wikipedia.org/wiki/Combe-Capelle]; Combe-Capelle lies in the Périgord region of France [SUPPORTED: https://en.wikipedia.org/wiki/Combe-Capelle]; A Homo sapiens fossil comes from Combe-Capelle [SUPPORTED: https://en.wikipedia.org/wiki/Combe-Capelle]; The fossil was found in 1909 [SUPPORTED: https://en.wikipedia.org/wiki/Combe-Capelle]; The fossil was sold to a museum in Berlin [SUPPORTED: https://en.wikipedia.org/wiki/Combe-Capelle]; The fossil was sold in 1910 [SUPPORTED: https://en.wikipedia.org/wiki/Combe-Capelle]; The fossil proved to be 9,500 years old [SUPPORTED: https://en.wikipedia.org/wiki/Combe-Capelle]"}]'::jsonb),
    ('ad11d27d-d6ad-4384-bf32-ef4e74e0fee2'::uuid, 'card_description', 'In the Sechin River valley, Sechin Bajo holds a circular plaza of rocks and adobe bricks, radiocarbon dated to 3500 BCE, near a 2-meter-tall frieze dated at 3600 BCE.', NULL, 'teaser-card-s029-rollback:ad11d27d-d6ad-4384-bf32-ef4e74e0fee2:card_description', 'rollback of teaser-card-s029: card_description None restored on Sechin Bajo', '6dec72e2b321cf4086db7d0c8dc0ddf7e27da2fc95d743c5b8d93af7b64ffca2|cece3d3088b758441517b22c0d9bf2424eaaaa2f7f7bbacaf1d9a2b557cd187e|cece3d3088b758441517b22c0d9bf2424eaaaa2f7f7bbacaf1d9a2b557cd187e', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Sechin River valley, Sechin Bajo holds a circular plaza of rocks and adobe bricks, radiocarbon dated to 3500 BCE, near a 2-meter-tall frieze dated at 3600 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sechin Bajo lies in the Sechin River valley [S1]; a circular plaza was found at Sechin Bajo [S3]; the plaza is built of rocks and adobe bricks [S3]; radiocarbon dating put the plaza at 3500 BCE [S4]; a frieze stands near the plaza [S5]; the frieze is 2 metres tall [S5]; the frieze was dated at 3600 BCE [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Sechin Bajo is an archaeological site of ruins (a ceremonial centre) [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Bajo]; The site lies in the valley of the Sechin River (Peru) [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Bajo]; Sechin Bajo holds a circular plaza [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Bajo]; The circular plaza was built of rocks and adobe bricks [SUPPORTED: https://www.latimes.com/archives/la-xpm-2008-feb-26-fg-peru26-story.html]; The plaza is radiocarbon dated to 3500 BCE [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Bajo]; A frieze dated at 3600 BCE stands near the plaza [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Bajo]; The frieze is 2 metres tall [SUPPORTED: https://en.wikipedia.org/wiki/Sechin_Bajo]"}]'::jsonb),
    ('ad75ba60-6517-4a16-a529-7c2ba101c40f'::uuid, 'card_description', 'Bulldozing topsoil in 1948, the U.S. Navy struck Venado Beach: the remains of 369 individuals, many burials in ceramic urns, gold offerings and evidence for human sacrifice.', 'A pre-Columbian site with gold offerings and evidence of human sacrifice in its burials. Radiocarbon dates place the main occupation between 200 and 900 AD.', 'teaser-card-s029-rollback:ad75ba60-6517-4a16-a529-7c2ba101c40f:card_description', 'rollback of teaser-card-s029: card_description ''A pre-Columbian site with gold offerings and evidence of human sacrifice in its burials. Radiocarbon dates place the main occupation between 200 and 900 AD.'' restored on Venado Beach', '2005944aada33758c4deed1ed8e683e5a6b52366645070bf04e16a69e36969be|3a6e08e5e094ebe8c33af654897ead9964e934654ea88df829ecdf371d2ab9f7|3a6e08e5e094ebe8c33af654897ead9964e934654ea88df829ecdf371d2ab9f7', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Bulldozing topsoil in 1948, the U.S. Navy struck Venado Beach: the remains of 369 individuals, many burials in ceramic urns, gold offerings and evidence for human sacrifice."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the U.S. Navy was bulldozing topsoil when it found the site [S4]; the discovery happened in 1948 [S4]; the remains of 369 individuals were found at the site [S6]; many burials were in ceramic urns [S7]; the burials include gold offerings [S2]; there is evidence for human sacrifice [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Venado Beach is a pre-Columbian archaeological site on the Pacific coast of Panama (burial ground) [SUPPORTED: https://en.wikipedia.org/wiki/Venado_Beach]; The U.S. Navy found the site in 1948 while bulldozing off topsoil [SUPPORTED: https://en.wikipedia.org/wiki/Venado_Beach]; The remains of 369 individuals were found [SUPPORTED: https://en.wikipedia.org/wiki/Venado_Beach]; Many burials were in ceramic urns [SUPPORTED: https://en.wikipedia.org/wiki/Venado_Beach]; Burials held gold offerings [SUPPORTED: https://en.wikipedia.org/wiki/Venado_Beach]; The site shows evidence for human sacrifice [SUPPORTED: https://en.wikipedia.org/wiki/Venado_Beach]"}]'::jsonb),
    ('ae64dd4f-971f-4fd7-8540-08af5649e67a'::uuid, 'card_description', 'On the Via Appia stood Aeclanum, town of the Hirpini, whose wooden breastwork Sulla set on fire in 89 BC. It recovered, only to be destroyed in 663 and shrink to a hamlet.', NULL, 'teaser-card-s029-rollback:ae64dd4f-971f-4fd7-8540-08af5649e67a:card_description', 'rollback of teaser-card-s029: card_description None restored on Aeclanum', '4d73deaf3d6f359894e12a9916ba28e7f24bd4a3ef9035f40ae4432f1a5ad817|5fc62c22d8c64b04e09afbe5a186d7f63941e95a25e2dde5700861c008eed339|5fc62c22d8c64b04e09afbe5a186d7f63941e95a25e2dde5700861c008eed339', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On the Via Appia stood Aeclanum, town of the Hirpini, whose wooden breastwork Sulla set on fire in 89 BC. It recovered, only to be destroyed in 663 and shrink to a hamlet."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Aeclanum stood on the Via Appia [S1]; Aeclanum was a town of the Hirpini [S4]; it was defended by a wooden breastwork [S5]; Sulla set the breastwork on fire [S5]; this happened in 89 BC [S5]; the town recovered [S6]; it was destroyed in 663 [S8]; it was reduced to a small hamlet [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Aeclanum was an ancient town of Samnium in Southern Italy [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]; Aeclanum lay on the Via Appia [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]; Aeclanum was a town of the Hirpini [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]; Sulla set fire to its wooden breastwork in 89 BC [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]; The town recovered after Sulla''s sack [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]; The town was destroyed in 663 [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]; It shrank to a hamlet [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]; Aeclanum was defended by a wooden breastwork [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]; Sulla captured Aeclanum in 89 BC [SUPPORTED: https://en.wikipedia.org/wiki/Aeclanum]"}]'::jsonb),
    ('aea029cf-6583-48a3-9c2e-67376db31da8'::uuid, 'card_description', 'The Bridestones cairn, described in 1764 with three compartments, keeps one. The main chamber''s southern side, once a single 18-foot-long stone, was split in 1843 by a picknicker''s bonfire.', 'A Neolithic cairn once 110 m long, now reduced to one surviving compartment. Built between 3500 and 2400 BC from massive stone slabs.', 'teaser-card-s029-rollback:aea029cf-6583-48a3-9c2e-67376db31da8:card_description', 'rollback of teaser-card-s029: card_description ''A Neolithic cairn once 110 m long, now reduced to one surviving compartment. Built between 3500 and 2400 BC from massive stone slabs.'' restored on The Bridestones', '9543893bb9eff195e9a4392ce9c05c37bcb72e7129acb67e6346088fcb2bcdee|e5dacee0dd1d82e95b54897b7490fa66958eefd1d2771a251ed071b4dc18dfee|e5dacee0dd1d82e95b54897b7490fa66958eefd1d2771a251ed071b4dc18dfee', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Bridestones cairn, described in 1764 with three compartments, keeps one. The main chamber''s southern side, once a single 18-foot-long stone, was split in 1843 by a picknicker''s bonfire."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Bridestones is a cairn [S1]; it was described in 1764 as having three compartments [S2]; only one compartment remains today [S2]; the southern side of the main chamber was originally a single stone [S6]; that stone was 18 feet long [S6]; it was split in 1843 [S6]; it was split by a picknicker''s bonfire [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Bridestones is a chambered cairn (Neolithic tomb) near Congleton, Cheshire, England [SUPPORTED: https://en.wikipedia.org/wiki/The_Bridestones]; The cairn was described in 1764 [SUPPORTED: https://en.wikipedia.org/wiki/The_Bridestones]; It was described as containing three separate compartments [SUPPORTED: https://en.wikipedia.org/wiki/The_Bridestones]; Only one compartment remains today [SUPPORTED: https://en.wikipedia.org/wiki/The_Bridestones]; The southern side of the main chamber was originally a single 18-foot-long stone [SUPPORTED: https://en.wikipedia.org/wiki/The_Bridestones]; That stone was split in 1843 by a picnicker''s bonfire [SUPPORTED: https://en.wikipedia.org/wiki/The_Bridestones]; The southern side of the main chamber was split by a picnicker''s bonfire [SUPPORTED: https://en.wikipedia.org/wiki/The_Bridestones]; The 18-foot-long stone was a single stone before the split [SUPPORTED: https://en.wikipedia.org/wiki/The_Bridestones]"}]'::jsonb),
    ('af78d851-5a24-4bd6-a1ad-1df1f29f9526'::uuid, 'card_description', 'At Cave di Cusa in Sicily, rock lies in different stages of being cut, still bearing pick marks: the quarry for Selinunte''s temples was left in 409 BC, when the Carthaginians took the city.', 'An ancient stone quarry abandoned mid-work in 409 BC when Carthaginians attacked. Column drums still sit half-carved in the rock — a frozen snapshot of Greek construction.', 'teaser-card-s029-rollback:af78d851-5a24-4bd6-a1ad-1df1f29f9526:card_description', 'rollback of teaser-card-s029: card_description ''An ancient stone quarry abandoned mid-work in 409 BC when Carthaginians attacked. Column drums still sit half-carved in the rock — a frozen snapshot of Greek construction.'' restored on Cave di Cusa', '815446e82d2eba6ea427f735ebf38540156d5dda0e3fc05c41c5bc157b6ae9ca|69bcff4c40dbbe9d5840b67580624825ff29fe7768b7436fd81173c3e032b860|69bcff4c40dbbe9d5840b67580624825ff29fe7768b7436fd81173c3e032b860', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "At Cave di Cusa in Sicily, rock lies in different stages of being cut, still bearing pick marks: the quarry for Selinunte''s temples was left in 409 BC, when the Carthaginians took the city."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cave di Cusa is in Sicily [S1]; the rock lies in different stages of being cut [S6]; the rock still bears pick marks [S7]; the site was a quarry [S1]; the quarry supplied the temples of Selinunte [S4]; the quarry was abandoned in 409 BC [S5]; the abandonment came when the Carthaginians captured the city [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-058 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cave di Cusa is an ancient stone quarry in Sicily, Italy [SUPPORTED: https://en.wikipedia.org/wiki/Cave_di_Cusa]; Rock at the site lies in different stages of being cut [SUPPORTED: https://en.wikipedia.org/wiki/Cave_di_Cusa]; The rock bears pick marks [SUPPORTED: https://en.wikipedia.org/wiki/Cave_di_Cusa]; The quarry supplied the stone for Selinunte''s temples [SUPPORTED: https://en.wikipedia.org/wiki/Cave_di_Cusa]; The quarry was abandoned in 409 BC [SUPPORTED: https://en.wikipedia.org/wiki/Cave_di_Cusa]; The Carthaginians captured the city (Selinunte) in 409 BC [SUPPORTED: https://en.wikipedia.org/wiki/Cave_di_Cusa]; The stone blocks being worked were left where they lay when the quarry was abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Cave_di_Cusa]"}]'::jsonb),
    ('af919ba9-7fa1-4da0-bc15-443767ae8b66'::uuid, 'card_description', 'Discovered only in 1881, Pair-non-Pair Cave bears engravings of wild animals from between 30,000 and 25,000 BP, and most of the animals carved on its walls appear in pairs.', 'A cave with animal engravings dating to 28,000-23,000 BC, among the oldest known examples of prehistoric art. Horses, ibexes, bovines, and mammoths are etched into the walls.', 'teaser-card-s029-rollback:af919ba9-7fa1-4da0-bc15-443767ae8b66:card_description', 'rollback of teaser-card-s029: card_description ''A cave with animal engravings dating to 28,000-23,000 BC, among the oldest known examples of prehistoric art. Horses, ibexes, bovines, and mammoths are etched into the walls.'' restored on Pair-non-Pair Cave', '8c0d791398ae9573c3d37d6c6b83bf4ffd5b3a531d0ac359977fa83a1e278408|37b5493302415f76e581f4dcd3a63fe619366a8721dd1a789131539e4cd27c91|37b5493302415f76e581f4dcd3a63fe619366a8721dd1a789131539e4cd27c91', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Discovered only in 1881, Pair-non-Pair Cave bears engravings of wild animals from between 30,000 and 25,000 BP, and most of the animals carved on its walls appear in pairs."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the cave was discovered in 1881 [S2]; the cave bears engravings of wild animals [S2]; the engravings date from between 30,000 and 25,000 BP [S2]; most of the animals carved on the walls are shown in pairs [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Pair-non-Pair Cave is a cave in France (engraved cave near Prignac-et-Marcamps, Gironde) [SUPPORTED: https://en.wikipedia.org/wiki/Pair-non-Pair]; The cave was discovered only in 1881 [SUPPORTED: https://en.wikipedia.org/wiki/Pair-non-Pair]; The cave bears engravings of wild animals [SUPPORTED: https://en.wikipedia.org/wiki/Pair-non-Pair]; The engravings date from between 30,000 and 25,000 BP [SUPPORTED: https://en.wikipedia.org/wiki/Pair-non-Pair]; Most of the animals carved on the walls appear in pairs [SUPPORTED: https://en.wikipedia.org/wiki/Pair-non-Pair]"}]'::jsonb),
    ('b01e5465-5f19-408e-8a56-4d04f6575537'::uuid, 'card_description', 'On Shilstone Farm near Drewsteignton, three granite supports of Spinsters'' Rock hold up a capstone of 4.5 by 3.1 metres. The Neolithic dolmen collapsed in 1862 and was restored that year.', 'Three granite uprights carry a 4.5 by 3.1 m capstone on Shilstone Farm near Drewsteignton. The structure collapsed in 1862 and was rebuilt the same year.', 'teaser-card-s029-rollback:b01e5465-5f19-408e-8a56-4d04f6575537:card_description', 'rollback of teaser-card-s029: card_description ''Three granite uprights carry a 4.5 by 3.1 m capstone on Shilstone Farm near Drewsteignton. The structure collapsed in 1862 and was rebuilt the same year.'' restored on Spinsters'' Rock', 'd5efe8537edc9ee7bae1744a4cf56c72a73716ee758966402285d8b9c3e65652|14bba77e961191d1a52d3fdaab1ca7fc1ff4db00a25a48c484189f19ee990726|14bba77e961191d1a52d3fdaab1ca7fc1ff4db00a25a48c484189f19ee990726', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Shilstone Farm near Drewsteignton, three granite supports of Spinsters'' Rock hold up a capstone of 4.5 by 3.1 metres. The Neolithic dolmen collapsed in 1862 and was restored that year."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site stands on Shilstone Farm [S2]; the site is near Drewsteignton [S1]; three granite supports hold up the capstone [S3]; the capstone measures 4.5 by 3.1 metres [S3]; it is a Neolithic dolmen [S1]; it collapsed in 1862 [S4]; it was restored in the same year [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Spinsters'' Rock is a dolmen (megalithic tomb) in Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Spinsters%27_Rock]; The dolmen is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Spinsters%27_Rock]; It stands near Drewsteignton [SUPPORTED: https://en.wikipedia.org/wiki/Spinsters%27_Rock]; It is situated on Shilstone Farm [SUPPORTED: https://en.wikipedia.org/wiki/Spinsters%27_Rock]; The dolmen has three granite supports [SUPPORTED: https://en.wikipedia.org/wiki/Spinsters%27_Rock]; The supports hold up a capstone measuring 4.5 by 3.1 metres [SUPPORTED: https://en.wikipedia.org/wiki/Spinsters%27_Rock]; The dolmen collapsed in 1862 [SUPPORTED: https://en.wikipedia.org/wiki/Spinsters%27_Rock]; The dolmen was restored the same year (1862) [SUPPORTED: https://en.wikipedia.org/wiki/Spinsters%27_Rock]"}]'::jsonb),
    ('b0676488-4c32-4b8c-857c-eba8d6db4f59'::uuid, 'card_description', 'On a western slope of Uma Urqu north of Ayacucho, Wichqana was a ceremonial center from around 1200-800 BC, with semicircle temple structures raised on artificial mounds.', NULL, 'teaser-card-s029-rollback:b0676488-4c32-4b8c-857c-eba8d6db4f59:card_description', 'rollback of teaser-card-s029: card_description None restored on Wichqana', '51dec544a989e63b1fff73ac1e12b9fee1af27a3ad178bbab56c30d9d39c411c|5a556e379a756290a032d72457a4ce90ab02f6e69fbe629cc9b96d93de6f1bd8|5a556e379a756290a032d72457a4ce90ab02f6e69fbe629cc9b96d93de6f1bd8', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On a western slope of Uma Urqu north of Ayacucho, Wichqana was a ceremonial center from around 1200-800 BC, with semicircle temple structures raised on artificial mounds."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Wichqana lies on a western slope of Uma Urqu [S3]; it lies north of Ayacucho [S3]; it was a ceremonial center [S4]; it was active from around 1200-800 BC [S4]; the site had semicircle temple structures [S6]; the temple structures stood on artificial mounds [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Wichqana is an archaeological site in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Wichqana]; Wichqana was a ceremonial center [SUPPORTED: https://en.wikipedia.org/wiki/Wichqana]; Wichqana lies on a western slope of Uma Urqu [SUPPORTED: https://en.wikipedia.org/wiki/Wichqana]; The site lies north of Ayacucho [SUPPORTED: https://en.wikipedia.org/wiki/Wichqana]; It was active around 1200-800 BC [SUPPORTED: https://en.wikipedia.org/wiki/Wichqana]; The site had semicircle temple structures [SUPPORTED: https://en.wikipedia.org/wiki/Wichqana]; The semicircle temple structures stood on artificial mounds [SUPPORTED: https://en.wikipedia.org/wiki/Wichqana]"}]'::jsonb),
    ('b27222dd-e77f-419d-9f1b-55bafcf61cc0'::uuid, 'card_description', 'In the Forest of Paimpont, the Neolithic Tombeau de Merlin was 10.5 metres long and about 1.5 metres wide, with four orthostats on one side, one on the other and a sixth slab as an apse.', 'A Neolithic dolmen in the legendary Forest of Broceliande, called Merlin''s tomb since the 12th century. Grave robbers destroyed much of it, but visitors still come.', 'teaser-card-s029-rollback:b27222dd-e77f-419d-9f1b-55bafcf61cc0:card_description', 'rollback of teaser-card-s029: card_description "A Neolithic dolmen in the legendary Forest of Broceliande, called Merlin''s tomb since the 12th century. Grave robbers destroyed much of it, but visitors still come." restored on Tombeau de Merlin', '8dc1b57fba3506ea151407b0773009760add584068c2c52ae28f5dbba82974d0|d727d957290fab9ab4020394b026d84785252febbf9359de7e1a43506d160b9b|d727d957290fab9ab4020394b026d84785252febbf9359de7e1a43506d160b9b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "In the Forest of Paimpont, the Neolithic Tombeau de Merlin was 10.5 metres long and about 1.5 metres wide, with four orthostats on one side, one on the other and a sixth slab as an apse."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the Tombeau de Merlin lies in the Forest of Paimpont [S1]; it is Neolithic [S1]; it was 10.5 metres long [S4]; it was about 1.5 metres wide [S4]; four orthostats on one side of the room [S5]; only one orthostat on the other side [S5]; a sixth slab acted as an apse [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The Tombeau de Merlin is a megalithic monument (a gallery grave) [SUPPORTED: https://en.wikipedia.org/wiki/Tombeau_de_Merlin]; It lies in the Forest of Paimpont [SUPPORTED: https://en.wikipedia.org/wiki/Tombeau_de_Merlin]; The monument is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Tombeau_de_Merlin]; It was 10.5 metres long [SUPPORTED: https://en.wikipedia.org/wiki/Tombeau_de_Merlin]; It was about 1.5 metres wide [SUPPORTED: https://en.wikipedia.org/wiki/Tombeau_de_Merlin]; Four orthostats on one side of the chamber [SUPPORTED: https://en.wikipedia.org/wiki/Tombeau_de_Merlin]; One orthostat on the other side [SUPPORTED: https://en.wikipedia.org/wiki/Tombeau_de_Merlin]; A sixth slab acted as an apse [SUPPORTED: https://en.wikipedia.org/wiki/Tombeau_de_Merlin]"}]'::jsonb),
    ('b2a3365d-ad8d-45e9-a5b2-be3a0c9f5782'::uuid, 'card_description', 'On Rügen stand the seven Granitz Dolmens of Lancken, built of glacial boulders and red sandstone. One keeps a solitary guardian stone to its east; in 1969 they yielded amber pearls.', 'Seven Neolithic tombs from 3500-2800 BC, built by the Funnelbeaker culture. Three are encircled by stones forming rectangles, and one has a lone ''guardian'' stone.', 'teaser-card-s029-rollback:b2a3365d-ad8d-45e9-a5b2-be3a0c9f5782:card_description', 'rollback of teaser-card-s029: card_description "Seven Neolithic tombs from 3500-2800 BC, built by the Funnelbeaker culture. Three are encircled by stones forming rectangles, and one has a lone ''guardian'' stone." restored on Lancken - Granitz Dolmens', '74bdc289ef0c2b9b44bdb47baf9f91373f9e68a2e8888423079937457a80386e|fc00c93c3c4bd177147647fd23af49b230ed1ded1bed5ade8a69cddb4fbbf243|fc00c93c3c4bd177147647fd23af49b230ed1ded1bed5ade8a69cddb4fbbf243', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "On Rügen stand the seven Granitz Dolmens of Lancken, built of glacial boulders and red sandstone. One keeps a solitary guardian stone to its east; in 1969 they yielded amber pearls."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the dolmens are on Rügen [S1]; there are seven of them [S1]; they lie in the Lancken-Granitz municipality [S1]; they are built of glacial boulders [S4]; they are built of red sandstone [S4]; one has a solitary guardian stone on its east side [S3]; in 1969 the tombs were assessed and yielded amber pearls [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-059 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "The site is a group of seven dolmens (megalith tombs) [SUPPORTED: https://en.wikipedia.org/wiki/Lancken-Granitz_dolmens]; They are on Rügen, Germany (Lancken-Granitz) [SUPPORTED: https://en.wikipedia.org/wiki/Lancken-Granitz_dolmens]; They were built of glacial boulders [SUPPORTED: https://en.wikipedia.org/wiki/Lancken-Granitz_dolmens]; They were built with red sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Lancken-Granitz_dolmens]; One has a solitary guardian stone [SUPPORTED: https://en.wikipedia.org/wiki/Lancken-Granitz_dolmens]; The guardian stone stands to the dolmen''s east [SUPPORTED: https://en.wikipedia.org/wiki/Lancken-Granitz_dolmens]; Excavations in 1969 yielded finds [SUPPORTED: https://en.wikipedia.org/wiki/Lancken-Granitz_dolmens]; The finds of 1969 included amber pearls [SUPPORTED: https://en.wikipedia.org/wiki/Lancken-Granitz_dolmens]"}]'::jsonb),
    ('b2a97f1e-1f85-4f7f-97d0-38da53be836a'::uuid, 'card_description', 'Near the summit of Tibradden Mountain, diggers in 1849 found a stone-lined cist holding a pottery vessel and cremated remains, now kept by the National Museum of Ireland in Dublin.', 'The mountain is also a site of archaeological interest with a prehistoric burial site close to the summit.', 'teaser-card-s029-rollback:b2a97f1e-1f85-4f7f-97d0-38da53be836a:card_description', 'rollback of teaser-card-s029: card_description ''The mountain is also a site of archaeological interest with a prehistoric burial site close to the summit.'' restored on Tibradden Mountain', 'aa2d70b2096b103dca5744caf5fd46f0419fe5bb70c49909aca532b55f65f3e6|5a91ec761801985ad06a90e8b28ed766c87f1f7ca0de8591bf4c04255c8bf3f1|5a91ec761801985ad06a90e8b28ed766c87f1f7ca0de8591bf4c04255c8bf3f1', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Near the summit of Tibradden Mountain, diggers in 1849 found a stone-lined cist holding a pottery vessel and cremated remains, now kept by the National Museum of Ireland in Dublin."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the burial site is near the summit of Tibradden Mountain [S2]; it was excavated in 1849 [S4]; a stone-lined cist was found [S4]; the cist held a pottery vessel and cremated remains [S4]; the finds are now kept by the National Museum of Ireland in Dublin [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tibradden Mountain, in County Dublin, Ireland, has a prehistoric burial site (a stone-lined cist burial) close to its summit [SUPPORTED: https://en.wikipedia.org/wiki/Tibradden_Mountain]; The burial site was excavated (dug) in 1849 [SUPPORTED: https://en.wikipedia.org/wiki/Tibradden_Mountain]; The excavators found a stone-lined cist [SUPPORTED: https://en.wikipedia.org/wiki/Tibradden_Mountain]; The cist held a pottery vessel and cremated remains [SUPPORTED: https://en.wikipedia.org/wiki/Tibradden_Mountain]; The finds are now kept by the National Museum of Ireland in Dublin [SUPPORTED: https://en.wikipedia.org/wiki/Tibradden_Mountain]"}]'::jsonb),
    ('b2cb59ca-a7ed-4cc6-be6b-7cf1b95791e5'::uuid, 'card_description', 'South of Churchill in Somerset, the Iron Age Dinghurst Fort hides behind a fosse and a scarp 2.0 metres high in the east and 3.0 metres in the west. Bones, rings and weapons lay inside.', 'Iron Age univallate hillfort south of Churchill in Somerset, encircled by a 2-3 m scarp and a fosse. Dinghurst Fort has yielded bones, rings, and weapons — direct traces of its inhabitants.', 'teaser-card-s029-rollback:b2cb59ca-a7ed-4cc6-be6b-7cf1b95791e5:card_description', 'rollback of teaser-card-s029: card_description ''Iron Age univallate hillfort south of Churchill in Somerset, encircled by a 2-3 m scarp and a fosse. Dinghurst Fort has yielded bones, rings, and weapons — direct traces of its inhabitants.'' restored on Dinghurst Fort', '9dbb1ebcd812461e4c46d22d7c69d805a276b4ebffcc46969d180c94a427c681|4ee27336287c488c4e60093a3b58f037826947cb023b74d48ab4e5e48910192b|4ee27336287c488c4e60093a3b58f037826947cb023b74d48ab4e5e48910192b', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "South of Churchill in Somerset, the Iron Age Dinghurst Fort hides behind a fosse and a scarp 2.0 metres high in the east and 3.0 metres in the west. Bones, rings and weapons lay inside."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the fort lies south of Churchill in Somerset [S1]; it is Iron Age [S1]; it is surrounded by a fosse [S3]; a scarp encircles the camp [S2]; the scarp is 2.0 metres high in the east [S2]; the scarp is 3.0 metres high in the west [S2]; bones, rings and weapons were found inside [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Dinghurst Fort is a hillfort (a fort) [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]; The fort dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]; It lies south of Churchill in Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]; The fort is surrounded by a fosse (ditch) [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]; A scarp encircles the camp, 2.0 metres high in the east [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]; The scarp is 3.0 metres high in the west [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]; Bones were found inside the fort [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]; Rings were found inside the fort [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]; Weapons were found inside the fort [SUPPORTED: https://en.wikipedia.org/wiki/Dinghurst_fort]"}]'::jsonb),
    ('b30f9252-e3c4-4d53-a13e-7a10b1c6a501'::uuid, 'card_description', 'Above the gorges of the Rhumel lie the Tiddis Ruins, a Numidian settlement occupied before Roman rule, as its cemeteries show, and later the seat of a Christian bishopric.', 'A Roman city with both a Mithras sanctuary and a Christian chapel on the same hilltop—two rival religions, one plateau. A Temple of Saturn crowns the crag.', 'teaser-card-s029-rollback:b30f9252-e3c4-4d53-a13e-7a10b1c6a501:card_description', 'rollback of teaser-card-s029: card_description ''A Roman city with both a Mithras sanctuary and a Christian chapel on the same hilltop—two rival religions, one plateau. A Temple of Saturn crowns the crag.'' restored on Tiddis Ruins', '31026158cf7c49fcbe6e167cc67883275b098df6b77404fed6ab0dc5d2a6c78a|bdbfa0dc3c2fe542625be14007c8c2d8c5fccb97a068f719fbf6fbee1bf68c83|bdbfa0dc3c2fe542625be14007c8c2d8c5fccb97a068f719fbf6fbee1bf68c83', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-write-020", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Above the gorges of the Rhumel lie the Tiddis Ruins, a Numidian settlement occupied before Roman rule, as its cemeteries show, and later the seat of a Christian bishopric."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check-020 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "the site lies above the gorges of the Rhumel [S2]; it was a settlement in Numidia [S1]; it was occupied before Roman rule [S4]; the pre-Roman occupation is shown by its cemeteries [S6]; it was later the seat of a Christian bishopric [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Tiddis is an ancient settlement in Numidia, in what is now Constantine Province in eastern Algeria [SUPPORTED: https://en.wikipedia.org/wiki/Tiddis]; It lies above the gorges of the Rhumel [SUPPORTED: https://en.wikipedia.org/wiki/Tiddis]; The site was occupied before Roman rule [SUPPORTED: https://en.wikipedia.org/wiki/Tiddis]; The pre-Roman occupation is shown by the cemeteries [SUPPORTED: https://en.wikipedia.org/wiki/Tiddis]; Tiddis was later the seat of a Christian bishopric [SUPPORTED: https://en.wikipedia.org/wiki/Tiddis]"}]'::jsonb),
    ('b3b17110-a61a-43c1-8962-7c8f71947f52'::uuid, 'card_description', 'Cotzumalhuapa, on the Pacific piedmont of southern Guatemala, was occupied since the Middle Preclassic. In the Late Classic period it was a major city of more than 10 square kilometres.', 'During the Late Classic period, Cotzumalhuapa was a major city that extended more than 10 square kilometres.', 'teaser-card-s029-rollback:b3b17110-a61a-43c1-8962-7c8f71947f52:card_description', 'rollback of teaser-card-s029: card_description ''During the Late Classic period, Cotzumalhuapa was a major city that extended more than 10 square kilometres.'' restored on Cotzumalhuapa', 'e24b7ceb8df3c388e9f394bb2aff54357f59da7d9246ec8cd8076cfd1c747968|c6386889553b7460440f1f38667c95aac9966962c303dfd6884a4f10817c292f|c6386889553b7460440f1f38667c95aac9966962c303dfd6884a4f10817c292f', '[{"source": "lane WB run wb-ws-2026-09-27-02: writer teaser-wb-ws-2026-09-27-02-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cotzumalhuapa, on the Pacific piedmont of southern Guatemala, was occupied since the Middle Preclassic. In the Late Classic period it was a major city of more than 10 square kilometres."}, {"source": "lane WB run wb-ws-2026-09-27-02: checker teaser-wb-ws-2026-09-27-02-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cotzumalhuapa is on the Pacific piedmont of southern Guatemala [S2]; it was occupied since the Middle Preclassic [S1]; in the Late Classic period it was a major city [S3]; the city extended more than 10 square kilometres [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-02: verifier teaser-wb-ws-2026-09-27-02-verify-060 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-02/OUTCOMES.jsonl", "quote": "Cotzumalhuapa is an archaeological zone on the Pacific piedmont of southern Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Cotzumalhuapa]; The site was occupied since the Middle Preclassic period [SUPPORTED: https://en.wikipedia.org/wiki/Cotzumalhuapa]; In the Late Classic period it was a major city [SUPPORTED: https://en.wikipedia.org/wiki/Cotzumalhuapa]; The city extended more than 10 square kilometres [SUPPORTED: https://en.wikipedia.org/wiki/Cotzumalhuapa]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 99;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s029-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s029-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s029-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 99 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('7abb834a-305d-43b5-b0fe-283261d83cf0'::uuid, 'card_description', 'The Temple of Victory at Himera, probably dedicated to Athena, dates to between 480 and 470 BC. It was burnt and destroyed, most likely in 409 BC, when the Carthaginians captured the city.'), ('7bfb0158-bf33-40c2-aff0-3af9efcd5193'::uuid, 'card_description', 'Bone flutes from the Geissenklösterle cave, the oldest musical instruments ever found, are from the Caves and Ice Age Art in the Swabian Jura, like the 41,000 to 39,000-year-old Lion-man.'), ('7c097275-ba5b-44f8-852b-77f450b7b813'::uuid, 'card_description', 'The Welsh Way, a British Iron Age trade route across the Cotswold Hills, links the highest navigable point on the Thames at Lechlade to the lowest crossing of the Severn at Gloucester.'), ('7c3cb1c4-0431-4ebb-96e0-a3238de40ca0'::uuid, 'card_description', 'Early antiquarians thought the Romans built Wincobank, an oval earthwork covering about 1 ha. Archaeologists now think the Celtic Brigantes tribe constructed it.'), ('7c762fd9-2ec5-4d25-a67b-f391837257af'::uuid, 'card_description', 'Near Oddendale stands a stone circle, part of a complex of cairns, circles and standing stones that includes the Shap Stone Avenue. A second circle and ring cairn was excavated nearby.'), ('7cecf4ab-47ef-4c15-90bb-e6ba491732e2'::uuid, 'card_description', 'Near the top of Mockham Down in Devon, at 310 m, an Iron Age hill fort takes the form of a multi-ditch and rampart enclosure. A smaller enclosure lies 2 km to the west on the next hill.'), ('7cf71e81-b840-41ac-86e1-9d39eda3a2fb'::uuid, 'card_description', 'In Manchester''s Castlefield stood Mamucium, a Roman fort begun around AD 79 on a sandstone bluff over a crossing of the River Medlock, levelled as the city grew in the Industrial Revolution.'), ('7d45e357-77ff-40f6-a4b4-7e16e015996a'::uuid, 'card_description', 'Atop the Iverian Mountain, Anacopia Fortress has walls built of largely tightly assembled and carefully hewn limestone blocks and, at its centre, a Roman-styled tower four storeys high.'), ('7e45bd64-0e85-4b03-9cb7-2b865ef867dd'::uuid, 'card_description', 'Atop Quarley Hill, 172 metres above sea level, sits an oval Iron Age hill fort. Four large Bronze Age ditches radiate from it, believed to be part of a Bronze Age farming settlement.'), ('7ee712a7-ac2d-448e-953e-1292d104facc'::uuid, 'card_description', 'The entrance of the granite dolmen Cova d''en Daina is oriented to the southeast, letting winter solstice sunlight reach the interior. Excavation unearthed human bones and flint arrowheads.'), ('7ee94c43-3a26-44db-8dee-bd7829b5a171'::uuid, 'card_description', 'Vestiges of low walls ring the slope of the Castro of Castelo Velho, a fortified Chalcolithic settlement in the Alentejo that by the late Bronze Age was a centre of intense metallurgy.'), ('7fc0b9aa-387f-4403-992c-b9648b23b870'::uuid, 'card_description', 'On the Boa Vista savanna, Sítio Arqueológico da Pedra Pintada rises 35 metres above a cave. Its rock art comes in two styles, the abstract Parime and the realist Surumu.'), ('80ea9e97-d2ed-46f6-b1db-293dfd277039'::uuid, 'card_description', 'On a high hill in Grimsbury Wood, Grimsbury Castle''s ramparts seem stretched to take in a spring reportedly never known to run dry. Saxons thought Woden alias Grim had built the earthworks.'), ('8153d20b-c794-4c70-9269-7f20884d5149'::uuid, 'card_description', 'On a promontory on the southern side of Norton Down, approximately 145 metres above sea level, sits Woodbury, an Iron Age hillfort in the parish of Stoke Fleming, near Dartmouth in Devon.'), ('81666db8-d2a8-4557-8986-376a02bf40b2'::uuid, 'card_description', 'At sea level near Cartagena, the Cave of Los Aviones yielded perforated, painted seashell beads thought to be jewelry crafted by Neanderthals, their pigments dated to 115,000 years old.'), ('818cc875-92d0-4bc3-be80-704620304599'::uuid, 'card_description', 'On the limestone terraces of the Rohri Hills, the Buddhist city of Siraj-ji-Takri survives as stone and mud-brick walls and small mounds atop three different mesas in Upper Sindh.'), ('81a32f2d-5102-47f9-adf3-4f5f8fb54561'::uuid, 'card_description', 'Its name means burnt hill: Sokhta Koh, a Harappan site near Pasni, lies strewn with hundreds of thousands of potsherds, and scores of open pit ovens for firing the pottery can still be seen.'), ('829e47ff-5760-4865-96ec-05ed93bd4399'::uuid, 'card_description', 'At the foot of Mount Ossa, overlooking the plains of Thessaly, Sycurium is where Livy has Perseus of Macedon make camp. Its acropolis still shows 5th century BCE fortifications.'), ('84ec7925-84a6-434c-847f-bf3bf9294cff'::uuid, 'card_description', 'In Cornwall, the Iron Age hill fort of Caer Bran ringed a space 200 feet in diameter with a stone-lined wall. At its centre lie remains of a large circular stone building.'), ('852f3856-ecaa-4bab-82c8-a0ab2d11f94f'::uuid, 'card_description', 'Tenayuca holds the earliest Aztec double pyramid yet found. A double stairway climbs to where the temples of Tlaloc and Huitzilopochtli once stood, above a wall of serpents.'), ('865dcc6d-fa4c-429b-8c16-908cb96dcec2'::uuid, 'card_description', NULL), ('86d06431-4ed1-4f2f-9814-7ed808c78968'::uuid, 'card_description', 'Excavated in secret in 2013 to prevent looting, El Castillo de Huarmey hid a royal Wari tomb: 60 bodies seated in rows, and three royal women buried with gold weaving tools.'), ('86e1dff8-20ac-4d49-85d8-480ee0b9f3ed'::uuid, 'card_description', 'On Salisbury Plain, a single causeway cuts through the two ditch circuits of Robin Hood''s Ball, a Neolithic enclosure probably built around 4000 BC and in use possibly up to 3000 BC.'), ('86ea97f7-ef72-4599-8d68-152db475d12f'::uuid, 'card_description', 'Among the ruins of KirkBiza, an early Byzantine settlement in northwest Syria, lie remains of the earliest preserved house church after Dura-Europos, from the beginning of the 4th century.'), ('87ea9721-2bb2-456a-b1e6-8a44dbde62d3'::uuid, 'card_description', 'Stukeley recorded two concentric sarsen rings at Winterbourne Bassett Stone Circle, with an outlying stone to the west. Were they raised by people, or a scatter of natural stones?'), ('89489dc6-0f27-48bc-9365-5c74725b46dc'::uuid, 'card_description', 'Casing stones still cover the top third of the Pyramid of Khafre, middle of the three Pyramids of Giza. In 1818 Giovanni Belzoni found its original entrance on the north side.'), ('89f1d2b7-2579-4c33-82b3-8b58d7857c53'::uuid, 'card_description', 'According to Macrobius, Mars was worshipped at the inland city of Acci as Netos, his head surrounded by the sun''s rays. Its site lies 6 kilometres northwest of modern Guadix.'), ('8ae0ddaa-c1bd-4796-9328-ae7e64812b07'::uuid, 'card_description', 'Beside the Danube, Ratiaria held a gold mine worked by the Thracians. Taken by the Dacians of Burebista and later by the Romans, it became the colony Colonia Ulpia Traiana Ratiaria.'), ('8b8c6154-987e-4d54-b9ca-fac19630061b'::uuid, 'card_description', 'A bank and ditch 4 metres high encircle Banwell Camp in places: an Iron Age hill fort approximately 1.6 miles east of the village of Banwell, excavated in the late 1950s by J.W. Hunt.'), ('8b9f8fb9-7f39-455b-bf0e-bec8e76fb45d'::uuid, 'card_description', 'Forestry has badly damaged Burfa Castle, an Iron Age hillfort near Offa''s Dyke. Beside its likely entrance, three or four banks and ditches form a torturous approach.'), ('8bcea3e7-dfdc-4af5-8b75-70fb9e34d7ee'::uuid, 'card_description', 'Flaked stone tools suggest frequent human visits to the Berbati Valley, northeast of Argos, in the Middle Palaeolithic. In 1936 the Potter''s Quarters came to light on Mastos Hill.'), ('8d5976d1-7cf9-4f7c-aeac-f47bacd89805'::uuid, 'card_description', 'On the west coast of Skye, Dun Ardtreck''s first occupation seems to have ended in violence and destruction. Later came iron tools, bronze ornaments and sherds of Roman Samian ware.'), ('8d5b27e6-c0ab-4c08-8742-7bb0c59bcfa5'::uuid, 'card_description', 'Found in 1947, the Villa of Torre de Palma, about 5 km northwest of Monforte, spans the 1st to the 5th century: a large residential complex with a thermal complex to its east.'), ('8e4daf07-4633-4481-865a-9243993c227c'::uuid, 'card_description', 'From the centre of Castle Close, a circular earthwork overlooking the River Exe, the hill forts of Huntsham Castle, Cranmore Castle and Cadbury Castle are all in plain view.'), ('8e4f5b3f-25dd-471f-96e4-4398f89754bd'::uuid, 'card_description', 'In Cueva de Bolomor, occupied between 350,000 and 120,000 years ago, excavators have recovered two Neanderthal teeth, a fibula fragment and a nearly complete adult parietal bone.'), ('8f0bd6a2-46b6-46cb-afbb-efd18b2471d8'::uuid, 'card_description', 'On a plateau by the Akhurian River, the Yereruyk Archaeological Site holds an Armenian church whose name means quivering, ringed by thick walls, underground rooms and a water reservoir.'), ('90923e91-3e29-4568-aa2e-989de43d2a0f'::uuid, 'card_description', 'At least seven Neanderthals were found at La Ferrassie, all in a 60 cm layer dated to 74-68 thousand years ago. Its Mousterian burial structures provided evidence of Neanderthal burial.'), ('90dac465-52f7-495a-ae8e-79953fa8d9b9'::uuid, 'card_description', 'At the crossing of Silk Road caravan routes, Otrar''s fortress and fortified city formed a five-corner hill about 18 meters high. The Mongol invasion interrupted its prosperity.'), ('91b72d89-5ca1-4427-a02f-7423266c6f39'::uuid, 'card_description', 'Under a building in Toledo lies the Cave of Hercules, a vaulted Roman space that appears to have been a water reservoir, fed by the aqueduct bridge across the River Tagus.'), ('91f09c72-5e12-49da-bce4-9f139d7e8e2a'::uuid, 'card_description', 'Near the marina of Vilamoura, the Roman Ruins of Cerro da Vila hold a villa that had its own port, serving fertile lands irrigated by a dam two kilometres from the settlement.'), ('9299ee5a-03c7-415b-a8d2-b8a7b8c71a7e'::uuid, 'card_description', 'On a promontory some 65–80 metres above sea level, Greenway Camp, an Iron Age hill fort also called Noss, looks out over Noss Point in the Dart Estuary, close to Dartmouth in Devon.'), ('940444fb-1897-4c1f-bdc2-30e967df95c8'::uuid, 'card_description', 'A granite stone shaped like a mushroom, more than two meters high: at the Rocha dos Namorados, girls of marriageable age still consult the rock to learn how long until they marry.'), ('9431fc19-12a8-4ec7-ac30-183d2d110cf3'::uuid, 'card_description', 'Known since the 1890s yet largely neglected, the Roman Villa of Alto da Cidreira on a Cascais hilltop had a two-storey house, polychromatic mosaics and a thermal bath with heating conduits.'), ('94cc711b-1ce7-4f7d-867c-64d59c65c76d'::uuid, 'card_description', 'Roughly 3600 meters up on the Inca Trail, Puyupatamarca is known as La Ciudad entre la Niebla. Among its Inca ruins, five small stone baths run with fresh water through the wet season.'), ('94fd509a-71e9-4a1e-b235-4eb91b1cacca'::uuid, 'card_description', 'Mamshit National Park holds a former Nabataean caravan stop on the Incense Road, where the biggest hoard ever found in Israel came to light: 10,500 silver coins weighing 72 kg in total.'), ('951c140b-1698-4495-9c6b-c78254c2b4cd'::uuid, 'card_description', 'Near Old Hunstanton in Norfolk stood Seahenge: 55 split oak trunks around an upturned tree root, built in the spring-summer of 2049 BC, one trunk with a narrow Y fork permitting access.'), ('95981699-02b0-4ab9-9ccc-cd9efc14f97a'::uuid, 'card_description', 'On the outskirts of Dorchester, Flagstones Enclosure was a ring of unevenly spaced pits from the late 4th millennium BC. Some chalk walls bore engraved designs, probably cut with flint.'), ('96395824-9c31-477a-bf51-13ecb5035d56'::uuid, 'card_description', NULL), ('9737ca03-ad30-46d2-8740-3dec20bed1ea'::uuid, 'card_description', 'Found in 2007 as a highway was widened, Grakliani Hill holds a temple to a fertility goddess from the seventh century BCE and signs of human presence possibly going back 300,000 years.'), ('97443726-74e9-40ac-b388-5daa15448ff1'::uuid, 'card_description', 'On a terrace above the Rio Grande de Nazca, Pernil Alto grew sweet potatoes and lima beans. Radiocarbon dates make it the oldest known inland, sedentary farming village in the Central Andes.'), ('98377ef7-6274-433a-98f5-72bd3baf7397'::uuid, 'card_description', 'Beside the Guadiana river rises Alarcos, a small hill of quartzite and volcanic rock 675 metres above sea level, crowned by the remains of a Bronze and Iron Age Iberian oppidum.'), ('98c794a6-57b5-4783-b38d-3693bb60b91b'::uuid, 'card_description', 'Built wholly of Parian marble for Athens'' offerings to Apollo, the Athenian Treasury bears metopes of the labors of Theseus and Herakles, the earliest known Theseus in large-scale sculpture.'), ('996e0b32-f8ca-4d04-8900-ed937b729269'::uuid, 'card_description', NULL), ('9a219745-8e06-4d8a-8396-c5d5656990a5'::uuid, 'card_description', 'On a steep Orkney hill facing the Bays of Firth and Kirkwall rises Wideford Hill Chambered Cairn: three concentric walls around a tomb where no human remains were found in the 1840s.'), ('9a4ccc75-d0d1-4bf8-8068-ef4cf3221aaf'::uuid, 'card_description', 'Near Gweek stands the Tolvan Holed Stone, the largest holed stone in Cornwall: a triangular stone 2.3 m high, pierced near its base by a hole approximately 43 cm in diameter.'), ('9adf8063-9af0-4610-b021-0e9f0cef4c02'::uuid, 'card_description', 'In the Alentejo, 34 granite menhirs of the Vale Maria do Meio Cromlech form an east-west arch, and two of them bear engravings of circles, horseshoes and lunar crescents.'), ('9b4bc2f9-521a-467f-a1a6-ebd4563221e9'::uuid, 'card_description', 'On Walbury Hill, at 297 metres the highest natural point in South East England, lies the Iron Age hill fort of Walbury Camp, crowning a summit of the North Wessex Downs.'), ('9c827589-5230-48e4-bf6b-fb7dee9e7c35'::uuid, 'card_description', 'A climb of 290 m from Machu Picchu leads to Inti Punku, once the main entrance to the sacred city: a site dedicated to Inti, the Sun god, with windows and gates held up by terraces.'), ('9e723832-0a2b-43f9-90d1-3743b61b91ed'::uuid, 'card_description', 'At the entrance to Lot''s Cave above the Dead Sea stood a Byzantine monastery of the 5th-7th centuries, with a large basilical church, a reservoir and a hostel complex.'), ('9ee5d047-1345-405a-a689-4624365e0104'::uuid, 'card_description', 'Kot Diji, dug in 1954-55, gave its name to a culture of the Early Harappan Phase, circa 3300-2800 BCE; its houses and fortifications were made from unbaked mud-bricks.'), ('9f328a68-b73d-4fd9-bc44-a78d3cae960c'::uuid, 'card_description', 'Where Exeter stands today lay Isca Dumnoniorum, a Roman fortress of the Second Augustan Legion established circa AD 55, its name a Latin form of a Brittonic name for flowing water.'), ('9f611d23-894b-45e0-ad29-a692e6d46241'::uuid, 'card_description', 'On the northern summit of Gallox Hill, south west of Dunster, Black Ball Camp keeps a 3 metres high rampart and a 2 metres deep ditch: an Iron Age hillfort also known as British Camp.'), ('a06ad29e-06f0-450b-bf8e-cd3b7231f096'::uuid, 'card_description', 'In Avebury parish stand The Longstones, Adam and Eve. Adam, an estimated 62 tons, fell over in 1911 and was re-erected in 1912; close by lay a Beaker burial of a middle-aged man.'), ('a0d8cc79-b3fd-448f-b983-8155c26de853'::uuid, 'card_description', 'A mound near Antequera covers the Tholos de El Romeral, a megalithic burial site built around 1800 BC, one of the most important examples of early Bronze Age architecture in southern Europe.'), ('a0f583a3-f913-4c6a-9300-68f005b06999'::uuid, 'card_description', 'At Lambityeco, two imposing masks of Cocijo, the Zapotec rain god, flank the entrance of an elite residence, and the facade of Tomb 6 shows prehispanic governors more than 1300 years old.'), ('a25c9c7d-58f2-402a-a484-ac9ec953979f'::uuid, 'card_description', 'On a high rocky ledge in the Khyber Pass rises the Sphola Stupa, a Buddhist stone mound on a tiered base, where Gandhara sculptures were excavated, now housed in the museum in Peshawar.'), ('a2c6e1bf-1538-43c4-ad4a-65a0186193a7'::uuid, 'card_description', 'Found in 2008, the North Bersted Man was a warrior buried in the first century BC with an exceptional set of objects, his helmet adorned with two crests that once ran down its back.'), ('a3b55317-bae1-42b5-9c64-477749bdc2d5'::uuid, 'card_description', 'On a hill in the Arequipa Region lie the cemeteries and village of Huamboy, a name possibly from the Quechua wamp''uy, meaning to navigate, to sail, to travel by boat.'), ('a3e4eae7-5dbb-4e10-be96-065f54ce7e02'::uuid, 'card_description', 'East of Brockley in North Somerset, Taps Combe Camp, also known as Chelvey Batch Settlement, is an Iron Age hill fort shaped like a D, approximately 50 metres by 50 metres wide.'), ('a4856c44-4e78-4a45-b618-d558b763942d'::uuid, 'card_description', 'Hieroglyphs show Arroyo de Piedra and Tamarindito once formed an independent polity, before Tikal established Dos Pilas. Arroyo de Piedra appears to have been abandoned in the 8th century.'), ('a5009e55-a34f-4568-9d9b-1d86d1082a9b'::uuid, 'card_description', 'Across a 270-metre stretch of water from Flores, on a peninsula in Lake Petén Itzá, lies Tayasal: a Maya city of palaces, pyramid-temples, an acropolis, defensive walls and a cenote.'), ('a6492846-5963-4307-8ffc-ea06bb554b1e'::uuid, 'card_description', 'In County Monaghan, near the Cavan border, Lisnadarragh Wedge Tomb is walled by 20 orthostats that shrink from south-west to north-east, the largest, at the entrance, 1.8 metres high.'), ('a6712eba-ba7a-4047-8462-0f4ae9343373'::uuid, 'card_description', 'In 1951, workmen digging at a nearby tholos tomb stumbled on Grave Circle B, a royal cemetery at Mycenae whose women wore bands of gold, and where a death mask of electrum was unearthed.'), ('a6f8838d-ff92-4aef-9723-5ce4b3605fae'::uuid, 'card_description', 'Thracian Tomb Griffins: the lower leaves of the pediment''s end semi-palmettes look like griffin heads. Opposite the circular chamber''s entrance, a ritual stone bed; before it, gold paws.'), ('a705abb0-2fda-42d2-9eaa-dee12b190ce4'::uuid, 'card_description', 'On Fyfield Hill, two standing stones, two fallen stones and a capstone believed to weigh 17 tons are all that remain of a long mound''s entrance: The Devil''s Den, a Neolithic burial chamber.'), ('a7bb511e-92d8-4199-aa70-425d4e88b4cc'::uuid, 'card_description', 'Near Pirovac, an unknown immigrant who came after the Batonian uprising built a Roman villa: the Ivinj Archaeological Site, where oil was produced and a basilica rose in the 5th century.'), ('a7e1060c-e0e3-4fe0-a4ff-4737611a2203'::uuid, 'card_description', 'In the village of Marvinci, Isar keeps the remnants of a temple and a stadium designed in the ancient Roman style, and, say Macedonian archaeologists, roughly well over 200 graves.'), ('a7e88abd-9d65-4a68-bec6-d9d527f3c172'::uuid, 'card_description', 'A prehistoric farming village grew into an urban Dvaravati centre, among the earliest in Thailand to make contact with India: Si Thep Historical Park, where wheels of the law were recorded.'), ('a80f19c6-ffde-4350-b122-095a4ef5c97a'::uuid, 'card_description', 'Near Tarquinia, two bulls painted on one of its frescoes gave the Tomb of the Bulls its name, and its explicit sexual scenes remain relatively rare examples in Etruscan art.'), ('a965d140-d212-45f5-a269-1945fc8432b3'::uuid, 'card_description', 'Once a caravan station guarding a western branch of the Incense Road, the Archaeological Site Nitzana became a Nabataean city in the Negev, its people Christianized and Romanized.'), ('a9c5d1bf-b6d0-4486-a507-8dddfdc57a02'::uuid, 'card_description', 'Farm work in Nakhchivan, researchers say, uncovered the Ağbulaq Necropolis, whose graves are large jars. Two were excavated, yielding agate and glass beads, bronze pins, rings and bells.'), ('a9f3224a-798f-43ab-b3ea-41be12a41074'::uuid, 'card_description', 'On Gotland''s western coast, the Ajvide Settlement holds a burial ground of some 80 graves, and beside it dark soil mixed with pottery and bone. Around 2900 BC, the sea encroached.'), ('aad935a4-efbd-4133-94ac-ce7d12789e9c'::uuid, 'card_description', 'In 79 AD Vesuvius buried Torre del Greco, probably a suburb of Herculaneum, under ash. Later came the villages of Sora and Calastro, until Belisarius moved their people to Naples in 535.'), ('ab28cd35-6f8c-4789-80df-a123993db0b0'::uuid, 'card_description', 'On a steep cliff on Hisingen, red ochre bonded with the rock still shows ships, fish, a large deer and wave-like patterns: the Tumlehed Rock Painting, the southernmost recorded in Sweden.'), ('ac76d3ef-82df-4fcc-8da4-f4fc7f59716e'::uuid, 'card_description', 'In the Couze valley of the Périgord lies Combe-Capelle, whose Homo sapiens fossil, found in 1909 and sold to a Berlin museum in 1910, proved to be 9,500 years old.'), ('ad11d27d-d6ad-4384-bf32-ef4e74e0fee2'::uuid, 'card_description', 'In the Sechin River valley, Sechin Bajo holds a circular plaza of rocks and adobe bricks, radiocarbon dated to 3500 BCE, near a 2-meter-tall frieze dated at 3600 BCE.'), ('ad75ba60-6517-4a16-a529-7c2ba101c40f'::uuid, 'card_description', 'Bulldozing topsoil in 1948, the U.S. Navy struck Venado Beach: the remains of 369 individuals, many burials in ceramic urns, gold offerings and evidence for human sacrifice.'), ('ae64dd4f-971f-4fd7-8540-08af5649e67a'::uuid, 'card_description', 'On the Via Appia stood Aeclanum, town of the Hirpini, whose wooden breastwork Sulla set on fire in 89 BC. It recovered, only to be destroyed in 663 and shrink to a hamlet.'), ('aea029cf-6583-48a3-9c2e-67376db31da8'::uuid, 'card_description', 'The Bridestones cairn, described in 1764 with three compartments, keeps one. The main chamber''s southern side, once a single 18-foot-long stone, was split in 1843 by a picknicker''s bonfire.'), ('af78d851-5a24-4bd6-a1ad-1df1f29f9526'::uuid, 'card_description', 'At Cave di Cusa in Sicily, rock lies in different stages of being cut, still bearing pick marks: the quarry for Selinunte''s temples was left in 409 BC, when the Carthaginians took the city.'), ('af919ba9-7fa1-4da0-bc15-443767ae8b66'::uuid, 'card_description', 'Discovered only in 1881, Pair-non-Pair Cave bears engravings of wild animals from between 30,000 and 25,000 BP, and most of the animals carved on its walls appear in pairs.'), ('b01e5465-5f19-408e-8a56-4d04f6575537'::uuid, 'card_description', 'On Shilstone Farm near Drewsteignton, three granite supports of Spinsters'' Rock hold up a capstone of 4.5 by 3.1 metres. The Neolithic dolmen collapsed in 1862 and was restored that year.'), ('b0676488-4c32-4b8c-857c-eba8d6db4f59'::uuid, 'card_description', 'On a western slope of Uma Urqu north of Ayacucho, Wichqana was a ceremonial center from around 1200-800 BC, with semicircle temple structures raised on artificial mounds.'), ('b27222dd-e77f-419d-9f1b-55bafcf61cc0'::uuid, 'card_description', 'In the Forest of Paimpont, the Neolithic Tombeau de Merlin was 10.5 metres long and about 1.5 metres wide, with four orthostats on one side, one on the other and a sixth slab as an apse.'), ('b2a3365d-ad8d-45e9-a5b2-be3a0c9f5782'::uuid, 'card_description', 'On Rügen stand the seven Granitz Dolmens of Lancken, built of glacial boulders and red sandstone. One keeps a solitary guardian stone to its east; in 1969 they yielded amber pearls.'), ('b2a97f1e-1f85-4f7f-97d0-38da53be836a'::uuid, 'card_description', 'Near the summit of Tibradden Mountain, diggers in 1849 found a stone-lined cist holding a pottery vessel and cremated remains, now kept by the National Museum of Ireland in Dublin.'), ('b2cb59ca-a7ed-4cc6-be6b-7cf1b95791e5'::uuid, 'card_description', 'South of Churchill in Somerset, the Iron Age Dinghurst Fort hides behind a fosse and a scarp 2.0 metres high in the east and 3.0 metres in the west. Bones, rings and weapons lay inside.'), ('b30f9252-e3c4-4d53-a13e-7a10b1c6a501'::uuid, 'card_description', 'Above the gorges of the Rhumel lie the Tiddis Ruins, a Numidian settlement occupied before Roman rule, as its cemeteries show, and later the seat of a Christian bishopric.'), ('b3b17110-a61a-43c1-8962-7c8f71947f52'::uuid, 'card_description', 'Cotzumalhuapa, on the Pacific piedmont of southern Guatemala, was occupied since the Middle Preclassic. In the Late Classic period it was a major city of more than 10 square kilometres.'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s029-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM p.written::character varying
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
SELECT 'temp table _teaser_card_plan left behind',
